INSERT INTO `agent_routing_capabilities` (`id`, `capability_key`, `agent_id`, `display_name`, `description`, `examples_json`, `exclusions_json`, `required_tools_json`, `enabled`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 'app.lifecycle', 2, '应用生命周期', '检测、下载、安装、启动、关闭或卸载 Windows 应用。', '[\"安装 VLC\",\"关闭微信\",\"下载某个应用的安装包\"]', '[\"操作应用内部界面\",\"查看系统状态\"]', '[\"check_app_installed\",\"download_file\",\"open_app\",\"close_app\",\"install_app\",\"uninstall_app\"]', 1, 10, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(2, 'computer.system', 3, '系统管理', '读取或调整本机系统状态，并执行不属于普通文件管理的系统操作。', '[\"查看内存占用\",\"清空回收站\",\"检查磁盘空间\"]', '[\"安装应用\",\"整理普通文件\"]', '[\"get_system_status\",\"recycle_bin_status\",\"shell_executor\"]', 1, 20, '2026-07-31 07:30:04', '2026-08-08 05:42:59'),
(3, 'computer.desktop_ui', 3, '桌面界面操作', '使用截图、UIA、鼠标和键盘操作已经打开的桌面界面。', '[\"在记事本中输入内容\",\"点击桌面窗口按钮\"]', '[\"启动应用\",\"操作网页 DOM\"]', '[\"computer_observe\",\"computer_interact\",\"computer_complete\"]', 1, 30, '2026-07-31 07:30:04', '2026-08-09 06:18:43'),
(4, 'browser.automation', 4, '浏览器自动化', '打开网页并对网页元素执行导航、填写、点击和视觉分析。', '[\"填写动态网页表单\",\"点击网页中的登录按钮\"]', '[\"桌面软件界面操作\",\"只做互联网资料调研\"]', '[\"browser_automation_control\",\"vls_analyze_browser\"]', 1, 40, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(5, 'browser.page_extraction', 4, '指定网页读取', '读取指定 URL 内容，或将指定网页及其资源本地化。', '[\"读取这个网页\",\"把这个网站保存到本地\"]', '[\"没有指定页面的联网调研\",\"普通文件下载\"]', '[\"web_fetch\",\"web_crawler\"]', 1, 50, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(6, 'file.management', 5, '文件管理', '创建、读取、编辑、复制、移动、下载、删除或打开普通文件和目录。', '[\"整理下载目录\",\"把文件复制到备份目录\",\"下载并保存这个 PDF\"]', '[\"修改项目代码\",\"清空回收站\"]', '[\"create_folder\",\"list_files\",\"read_file\",\"create_file\",\"edit_file\",\"copy_file\",\"move_file\",\"delete_file\",\"open_file\",\"download_file\"]', 1, 60, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(7, 'file.office', 5, 'Office 产物', '生成、编辑和验证 Word、Excel、PowerPoint 与 PDF 产物。', '[\"整理成 docx\",\"生成 xlsx 报表\",\"制作 pptx\"]', '[\"编写应用代码\",\"只搜索资料不生成文件\"]', '[\"read_file\",\"create_file\",\"python_executor\",\"shell_executor\",\"get_command_status\",\"stop_command\"]', 1, 70, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(8, 'search.web_research', 6, '联网调研', '搜索最新互联网信息、汇总多个来源并返回可访问的来源链接。', '[\"搜索 2026 年最新资料\",\"调研竞品并列出来源\"]', '[\"操作指定网页表单\",\"保存整个网站\"]', '[\"web_search\",\"web_fetch\"]', 1, 80, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(9, 'code.engineering', 7, '代码工程', '浏览、修改、运行和验证项目代码，并使用 LSP 定位诊断与引用。', '[\"修复项目 Bug\",\"检查 LSP 报错\",\"重构代码\"]', '[\"整理普通文档\",\"安装桌面应用\"]', '[\"list_files\",\"read_file\",\"create_file\",\"edit_file\",\"grep\",\"glob\",\"shell_executor\",\"python_executor\",\"get_command_status\",\"stop_command\",\"get_diagnostics\",\"find_references\",\"goto_definition\"]', 1, 90, '2026-07-31 07:30:04', '2026-07-31 07:30:04'),
(73, 'code.project_delivery', 7, '代码项目交付', '由项目负责人先建立架构、公共契约和文件边界，再组织一至六名项目成员并行实现，最后完成集成验收。', '[\"从设计文档实现完整前端项目\",\"并行开发多模块应用\",\"需要多人分工并最终集成验收的代码任务\"]', '[\"单文件小修复\",\"只做代码解释或只读检查\"]', '[\"list_files\",\"read_file\",\"create_file\",\"edit_file\",\"grep\",\"glob\",\"shell_executor\",\"python_executor\",\"get_command_status\",\"stop_command\",\"get_diagnostics\",\"find_references\",\"goto_definition\"]', 1, 100, '2026-08-03 14:23:34', '2026-08-03 14:23:34'),
(74, 'media.visual_understanding', 57, '图片与视频理解', '理解用户已上传的图片或视频，只返回结构化证据供 MoonYa 最终回答。', '[\"分析这张图片\",\"理解视频内容\",\"读取图片中的文字和图表\"]', '[\"生成图片\",\"转写纯音频\",\"直接向用户作答\"]', '[]', 1, 35, '2026-08-07 10:18:38', '2026-08-07 10:18:38');
INSERT INTO `agent_runtime_config` (`config_key`, `config_value`, `description`, `updated_at`) VALUES
('approval_timeout_seconds', '0', '工具确认等待秒数；0 表示无限等待，直到用户决定或取消', '2026-08-03 10:54:18'),
('event_payload_max_bytes', '8388608', '持久化事件 payload 最大字节数（完整 Agent 回合，默认 8 MiB）', '2026-07-31 07:30:04'),
('function_calling_compatibility', '[{\"model_contains\":\"deepseek\",\"thinking\":\"preserve\",\"supports_tool_choice\":false,\"requires_reasoning_content\":true,\"requires_assistant_content\":true}]', '原生 Function Calling 的模型协议兼容配置；DeepSeek V4 Thinking 保留 reasoning_content 且不发送 tool_choice', '2026-07-31 07:30:04'),
('loop_guard_max_period', '4', '循环守卫识别的最大周期步数', '2026-08-03 10:54:18'),
('loop_guard_recovery_attempts', '1', '同一循环允许的系统纠偏次数', '2026-08-03 10:54:18'),
('loop_guard_repeat_count', '3', '循环周期完整重复多少次后判定', '2026-08-03 10:54:18'),
('max_agent_iterations', '12', '已废弃：Work 模式轮次仅作为统计数据', '2026-08-03 10:54:18'),
('max_parallel_agents', '6', 'Work 模式无依赖 Agent 最大并发数', '2026-08-03 14:23:34'),
('max_planning_corrections', '1', '已废弃：Work 模式不再按规划纠错次数终止', '2026-08-03 10:54:18'),
('max_project_members', '6', '单个代码项目组最多并行项目成员数；项目负责人不计入', '2026-08-03 14:23:34'),
('max_root_delegations', '2', '已废弃：Work 模式不再按委派批次数终止', '2026-08-03 10:54:18'),
('max_shell_preflight_corrections', '1', '已废弃：Work Shell 预检纠错不再按次数终止', '2026-08-03 10:54:18'),
('mcp_gateway', 'true', '启用原生 Function Calling + MCP 混合工具网关', '2026-07-31 07:30:04'),
('multi_agent_v1', 'true', '启用 Work/CU 多 Agent 团队协议', '2026-07-31 07:30:04'),
('stream_delta_flush_bytes', '4096', 'Work 模式单次增量达到该字节数时立即发送', '2026-08-03 14:23:34'),
('stream_delta_flush_ms', '50', 'Work 模式同一回合流式增量合并窗口（毫秒）', '2026-08-03 14:23:34');
