(242, '88fd2af2-c2ef-420b-af4e-b37a45c1de48', 8533, 'tool.completed', 'code', 'moonya', 'implement-workbench', 'call_00_YEr1Q5hsAfRiZSBHEgFu3057', '{\"tool_key\":\"create_file\",\"ok\":true,\"content\":\"文件创建成功: D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\\js\\\\pages-work.js\",\"error\":null,\"stage\":null,\"status\":null,\"error_code\":null,\"command_fingerprint\":null,\"operation_receipt\":null}', '2026-08-03 09:44:06'),
(243, '88fd2af2-c2ef-420b-af4e-b37a45c1de48', 8534, 'agent.turn.started', 'code', 'moonya', 'implement-workbench', NULL, '{\"turn_id\":\"implement-workbench-turn-11\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":11}}', '2026-08-03 09:44:06'),
(244, '88fd2af2-c2ef-420b-af4e-b37a45c1de48', 9278, 'agent.turn.completed', 'code', 'moonya', 'implement-workbench', NULL, '{\"turn_id\":\"implement-workbench-turn-11\",\"status\":\"completed\",\"reasoning_content\":\"现在写 pages-study.js（考公区 8 页）。\\n\\n页面：\\n9. 考公区总览：#/study\\n10. 知识点树：#/study/tree\\n11. 知识点详情：#/study/knowledge/:id\\n12. 题库：#/study/questions\\n13. 错题本：#/study/wrong\\n14. 学习计划：#/study/plans\\n15. 学习打卡：#/study/checkin\\n16. 时政积累：#/study/current\\n\\n考公总览：三个数据卡（本周累计时长/连续打卡/计划完成率）+ 六个入口卡片（知识点树/题库/错题本/学习计划/学习打卡/时政积累）带数据摘要，数字滚动动画。\\n\\n知识点树：\\n- 左侧折叠树（行测/申论 多级），旋转箭头动画\\n- 右侧知识点卡片（标题、掌握程度进度条、下次复习日期、关联题目数量）\\n- 顶部搜索框\\n- 掌握程度点击弹五级选择器\\n- 树节点点击加载对应模块\\n\\n知识点详情：\\n- 返回 + 面包屑\\n- 标题、富文本正文、常见考法/易错点折叠区块\\n- 底部信息栏：掌握程度（可调）、下次复习日期、关联题目\\n- 修改掌握程度后自动重算复习日期\\n- 全屏阅读\\n\\n题库：\\n- 筛选栏：模块下拉 + 标签 + 来源 + 搜索\\n- 题目卡片：题干首行截断、选项折叠、答案遮罩、来源标注\\n- +录入题目\\n- 底部批量导入（文本粘贴解析）\\n\\n错题本：\\n- 统计概览 4 个\\n- 筛选 Tabs\\n- 题目列表（题干摘要、错误原因标签、复习次数、最近结果、下次复习日期）\\n- 点击进入复习模式（先做题再看答案）\\n- 答对3次自动归档庆祝\\n- 答错降级、艾宾浩斯重算\\n\\n学习计划：\\n- 周/月切换\\n- 计划卡片：起止日期、模块目标分配堆叠条形图、完成进度\\n- 实际 vs 目标对比柱状图\\n- +新建计划\\n\\n学习打卡：\\n- 今日目标/已学 + 环形进度\\n- 计时器（开始/暂停/重置）正计时\\n- 模块多选标签\\n- 提交打卡 + 今日总结\\n- 后台继续计（通过 Date.now 差值）\\n- 切走页面后台继续计（计时器存全局，通过 setInterval 更新 UI；tick 时若页面隐藏也继续）\\n\\n时政积累：\\n- 月份选择器 + 标签筛选\\n- 卡片列表（标题、来源、日期、摘要三行、解读斜体、金句引号）\\n- +录入时政\\n- 30天前标建议回顾\\n- 按月归档翻月\\n\\n写吧。注意打卡计时器的全局实现：把计时器状态放 store（timer），页面渲染时恢复。UI 更新用 interval，在页面卸载时清除。后台继续计的逻辑：interval 每 1s 更新，即使切走 tab，interval 会暂停，但恢复时根据 Date.now() - startAt 重算，所以后台计继续成立。\",\"content\":\"编写 pages-study.js（考公区 8 个页面：总览/知识点树/知识点详情/题库/错题本/学习计划/学习打卡/时政积累）：\",\"summary\":\"编写 pages-study.js（考公区 8 个页面：总览/知识点树/知识点详情/题库/错题本/学习计划/学习打卡/时政积累）：\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":11,\"finish_reason\":\"tool_calls\"}}', '2026-08-03 09:45:55');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
(245, '88fd2af2-c2ef-420b-af4e-b37a45c1de48', 9279, 'tool.started', 'code', 'moonya', 'implement-workbench', 'call_00_Mz6HjJCokVDHwqyCWLp07538', '{\"tool_key\":\"create_file\",\"display_name\":\"Create File\",\"arguments\":{\"content\":\"/* ============================================================\\n * pages-study.js —— 考公区（总览/知识点/题库/错题/计划/打卡/时政）\\n * ============================================================ */\\n(function () {\\n  \'use strict\';\\n  const S = () => WB.store.data();\\n  const icon = WB.icon, el = WB.el, $ = WB.$, $$ = WB.$$;\\n  const esc = WB.escapeHtml;\\n  WB.pages = WB.pages || {};\\n\\n  const MASTERY_NAMES = [\'未学\', \'了解\', \'掌握\', \'熟练\', \'精通\'];\\n\\n  /* ================= 9. 考公区总览 ================= */\\n  WB.pages.study = function () {\\n    const data = S();\\n    /* 本周累计时长 */\\n    let weekSec = 0;\\n    const d = new Date();\\n    const dayOfWeek = (d.getDay() + 6) % 7;\\n    for (let i = 0; i < 7; i++) {\\n      const t = new Date(d); t.setDate(t.getDate() - i);\\n      const c = data.checkins[WB.store.iso(t)];\\n      if (c && c.submitted) weekSec += c.seconds || 0;\\n    }\\n    /* 计划完成率 */\\n    const plans = data.plans.filter(p => p.status === \'active\');\\n    const completion = plans.length ? Math.round(plans.filter(p => p.done).length / plans.length * 100) : 0;\\n    const streak = WB.store.ops.streakDays();\\n    /* 各入口摘要 */\\n    const dueWrong = data.wrongQuestions.filter(w => w.status !== \'archived\' && w.nextReview && w.nextReview <= WB.todayStr()).length;\\n    const knowCount = data.knowledgeItems.length;\\n    const qCount = data.questions.length;\\n\\n    const cards = [\\n      { icon: \'grid\', name: \'知识点树\', sub: knowCount + \' 个知识点\', goto: \'tree\' },\\n      { icon: \'list\', name: \'题库\', sub: qCount + \' 道题\', goto: \'questions\' },\\n      { icon: \'refresh\', name: \'错题本\', sub: \'今日待复习 \' + dueWrong + \' 题\', goto: \'wrong\' },\\n      { icon: \'calendar\', name: \'学习计划\', sub: plans.length + \' 个进行中\', goto: \'plans\' },\\n      { icon: \'alarm\', name: \'学习打卡\', sub: \'今日已学 \' + WB.fmtDuration((data.checkins[WB.todayStr()] || {}).seconds || 0), goto: \'checkin\' },\\n      { icon: \'news\', name: \'时政积累\', sub: data.currentAffairs.length + \' 条时政\', goto: \'current\' },\\n    ];\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>考公区</h2><div class=\\\"sub\\\">保持节奏，日拱一卒</div></div>\' +\\n      \'<div class=\\\"study-hero\\\">\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-label\\\">本周累计时长</div><div class=\\\"stat-num\\\" data-roll=\\\"\' + Math.floor(weekSec / 3600) + \'\\\">0</div><div class=\\\"stat-label\\\">小时</div></div>\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-label\\\">连续打卡天数</div><div class=\\\"stat-num\\\" data-roll=\\\"\' + streak + \'\\\">0</div><div class=\\\"stat-label\\\">天</div></div>\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-label\\\">计划完成率</div><div class=\\\"stat-num\\\" data-roll=\\\"\' + completion + \'\\\">0<small style=\\\"font-size:14px\\\">%</small></div><div class=\\\"progress\\\" style=\\\"margin-top:6px\\\"><i style=\\\"width:\' + completion + \'%\\\"></i></div></div>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"section-title\\\">学习入口</div>\' +\\n      \'<div class=\\\"study-entry-grid\\\">\' +\\n        cards.map(c => \'<div class=\\\"glass entry-card\\\" data-goto=\\\"\' + c.goto + \'\\\">\' +\\n          \'<div class=\\\"ec-icon\\\">\' + icon(c.icon, 21) + \'</div><div class=\\\"ec-name\\\">\' + c.name + \'</div><div class=\\\"ec-sub\\\">\' + c.sub + \'</div></div>\').join(\'\') +\\n      \'</div></div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      $$(\'[data-roll]\', content).forEach(n => {\\n        const target = Number(n.dataset.roll);\\n        const suffix = n.querySelector(\'small\') ? \'\' : \'\';\\n        WB.animateNumber(n, target, 600, suffix);\\n      });\\n      $$(\'[data-goto]\', content).forEach(c => c.addEventListener(\'click\', () => location.hash = \'#/study/\' + c.dataset.goto));\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 10. 知识点树 ================= */\\n  WB.pages.tree = function () {\\n    const data = S();\\n    const kw = (this._kw || \'\').toLowerCase();\\n    const selected = this._selected || \'k_xc\';\\n    const selectedNode = findNode(data.knowledgeTree, selected);\\n\\n    function findNode(nodes, id) {\\n      for (const n of nodes) {\\n        if (n.id === id) return n;\\n        if (n.children) { const r = findNode(n.children, id); if (r) return r; }\\n      }\\n      return null;\\n    }\\n    function nodeHtml(node, depth) {\\n      const hasKids = node.children && node.children.length;\\n      const sel = node.id === selected;\\n      return \'<div class=\\\"tree-node\\\">\' +\\n        \'<div class=\\\"tree-row\' + (sel ? \' selected\' : \'\') + \'\\\" data-node=\\\"\' + node.id + \'\\\" data-depth=\\\"\' + depth + \'\\\" style=\\\"padding-left:\' + (10 + depth * 18) + \'px\\\">\' +\\n        (hasKids ? \'<span class=\\\"tw\' + (node.open ? \' open\' : \'\') + \'\\\" data-tw>\' + icon(\'chevron-right\', 13) + \'</span>\' : \'<span style=\\\"width:14px;flex-shrink:0\\\"></span>\') +\\n        \'<span>\' + esc(node.name) + \'</span></div>\' +\\n        (hasKids && node.open ? \'<div class=\\\"tree-children\\\">\' + node.children.map(c => nodeHtml(c, depth + 1)).join(\'\') + \'</div>\' : \'\') +\\n        \'</div>\';\\n    }\\n\\n    /* 该模块下的知识点 */\\n    const ownItems = data.knowledgeItems.filter(k => k.moduleId === selected);\\n    const childItems = collectChildItems(data.knowledgeItems, selectedNode);\\n    function collectChildItems(items, node) {\\n      if (!node) return [];\\n      const mine = items.filter(k => k.moduleId === node.id);\\n      const kids = (node.children || []).flatMap(c => collectChildItems(items, c));\\n      return mine.concat(kids);\\n    }\\n    const filteredItems = (kw ? data.knowledgeItems.filter(k => (k.title + \' \' + k.content).toLowerCase().includes(kw)) : childItems);\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>知识点树</h2><div style=\\\"flex:1\\\"></div>\' +\\n        \'<div class=\\\"topbar-search\\\" style=\\\"max-width:240px;flex:0 1 240px\\\">\' + icon(\'search\', 16) + \'<input data-search placeholder=\\\"全局检索知识点…\\\" style=\\\"border:none;outline:none;background:transparent;flex:1;font-size:13px\\\" value=\\\"\' + esc(this._kw || \'\') + \'\\\"></div></div>\' +\\n      \'<div class=\\\"tree-layout\\\">\' +\\n        \'<div class=\\\"glass tree-panel\\\" data-tree>\' + data.knowledgeTree.map(n => nodeHtml(n, 0)).join(\'\') + \'</div>\' +\\n        \'<div>\' +\\n          (kw ? \'<div class=\\\"section-title\\\">全局搜索结果</div>\' : \'\') +\\n          (filteredItems.length ? filteredItems.map(k => kpCardHtml(k)).join(\'\')\\n            : \'<div class=\\\"empty glass card\\\">\' + icon(\'book\', 30) + \'<div>\' + (kw ? \'没有匹配的知识点\' : \'该模块下暂无知识点\') + \'</div></div>\') +\\n        \'</div>\' +\\n      \'</div></div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const rerender = (patch) => {\\n        const p = { kw: ($(\'[data-search]\', content).value || \'\').trim() };\\n        if (patch && patch.selected) p.selected = patch.selected;\\n        WB.navigate(\'#/study/tree\', p);\\n      };\\n\\n      $(\'[data-search]\', content).addEventListener(\'input\', WB.debounce(() => rerender(), 300));\\n\\n      /* 树节点：点击三角展开/折叠，点击文字选择模块 */\\n      $$(\'[data-node]\', content).forEach(row => {\\n        row.addEventListener(\'click\', (e) => {\\n          const nodeId = row.dataset.node;\\n          const node = findNode(data.knowledgeTree, nodeId);\\n          const isTw = e.target.closest(\'[data-tw]\');\\n          if (isTw && node.children && node.children.length) {\\n            node.open = !node.open;\\n            WB.store.save();\\n            rerender({ selected: row.classList.contains(\'selected\') ? nodeId : undefined });\\n          } else {\\n            rerender({ selected: nodeId });\\n          }\\n        });\\n      });\\n\\n      bindKpCards(content, rerender);\\n    };\\n    return { html, bind };\\n  };\\n\\n  function kpCardHtml(k) {\\n    const pct = k.mastery * 25;\\n    const dueCls = k.nextReview && k.nextReview <= WB.todayStr() ? \' due-soon\' : \'\';\\n    return \'<div class=\\\"glass kp-card\\\" data-kp=\\\"\' + k.id + \'\\\">\' +\\n      \'<div class=\\\"kp-title\\\">\' + esc(k.title) + \'<span class=\\\"kp-mastery\\\" data-mastery=\\\"\' + k.mastery + \'\\\">\' + MASTERY_NAMES[k.mastery] + \'</span></div>\' +\\n      \'<div class=\\\"progress\\\" style=\\\"margin-top:10px\\\"><i style=\\\"width:\' + pct + \'%;\' + (k.mastery >= 3 ? \'background:var(--accent-2)\' : \'\') + \'\\\"></i></div>\' +\\n      \'<div class=\\\"kp-meta\\\">\' +\\n        \'<span>掌握 \' + pct + \'%</span>\' +\\n        \'<span class=\\\"\' + dueCls + \'\\\">下次复习 \' + (k.nextReview ? WB.fmtDate(k.nextReview) : \'—\') + \'</span>\' +\\n        \'<span>关联题目 \' + (k.questionIds ? k.questionIds.length : 0) + \'</span></div>\' +\\n      \'</div>\';\\n  }\\n\\n  function bindKpCards(root, rerender) {\\n    $$(\'[data-kp]\', root).forEach(card => {\\n      card.addEventListener(\'click\', (e) => {\\n        if (e.target.closest(\'[data-mastery]\')) return;\\n        location.hash = \'#/study/knowledge/\' + card.dataset.kp;\\n      });\\n      /* 掌握程度五级选择器 */\\n      card.querySelector(\'[data-mastery]\').addEventListener(\'click\', (e) => {\\n        e.stopPropagation();\\n        const kpId = card.dataset.kp;\\n        const cur = S().knowledgeItems.find(x => x.id === kpId);\\n        const body = el(\'<div><div class=\\\"mastery-5\\\">\' + MASTERY_NAMES.map((n, i) =>\\n          \'<button data-lvl=\\\"\' + i + \'\\\"\' + (cur.mastery === i ? \' class=\\\"on\\\"\' : \'\') + \'>\' + n + \'</button>\').join(\'\') + \'</div>\' +\\n          \'<div class=\\\"hint\\\" style=\\\"margin-top:12px\\\">修改后将按艾宾浩斯间隔（1/3/7/15/30 天）自动重算下次复习日期</div></div>\');\\n        const m = WB.openModal({ title: \'调整掌握程度\', body });\\n        $$(\'[data-lvl]\', body).forEach(b => b.addEventListener(\'click\', () => {\\n          WB.store.ops.setMastery(kpId, Number(b.dataset.lvl));\\n          m.close();\\n          WB.toast(\'已更新为「\' + MASTERY_NAMES[Number(b.dataset.lvl)] + \'」\');\\n          rerender && rerender();\\n        }));\\n      });\\n    });\\n  }\\n\\n  /* ================= 11. 知识点详情 ================= */\\n  WB.pages.knowledgeDetail = function (id) {\\n    const data = S();\\n    const k = data.knowledgeItems.find(x => x.id === id);\\n    if (!k) return { html: \'<div class=\\\"page\\\"><div class=\\\"empty\\\">\' + icon(\'book\', 34) + \'<div>知识点不存在</div><button class=\\\"btn\\\" data-back>返回知识点树</button></div></div>\', bind() { $(\'[data-back]\').addEventListener(\'click\', () => location.hash = \'#/study/tree\'); } };\\n\\n    const pathArr = (k.modulePath || \'\').split(\' > \').filter(Boolean);\\n    const crumb = pathArr.map((p, i) =>\\n      i < pathArr.length - 1 ? \'<a data-crumb=\\\"\' + esc(p) + \'\\\">\' + esc(p) + \'</a>\' : \'<span>\' + esc(p) + \'</span>\').join(\'<span style=\\\"opacity:.5\\\">›</span>\');\\n\\n    const relQuestions = data.questions.filter(q => (k.questionIds || []).includes(q.id));\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\">\' +\\n        \'<button class=\\\"btn ghost\\\" data-back>\' + icon(\'arrow-left\', 17) + \' 返回</button>\' +\\n        \'<button class=\\\"topbar-icon-btn\\\" data-full style=\\\"margin-left:auto\\\" title=\\\"全屏阅读\\\">\' + icon(\'maximize\', 17) + \'</button></div>\' +\\n      \'<div class=\\\"breadcrumb\\\" style=\\\"margin-bottom:12px\\\">\' + crumb + \'</div>\' +\\n      \'<div class=\\\"glass kp-detail-body\\\">\' +\\n        \'<h2 style=\\\"font-size:20px;margin-bottom:10px\\\">\' + esc(k.title) + \'</h2>\' +\\n        k.content +\\n      \'</div>\' +\\n      \'<div style=\\\"margin-top:14px\\\">\' +\\n        \'<div class=\\\"fold-block open\\\" data-fold><div class=\\\"fb-head\\\">常见考法 \' + icon(\'chevron-down\', 15) + \'</div><div class=\\\"fb-body\\\">\' + (k.examUsage || \'<p>暂无</p>\') + \'</div></div>\' +\\n        \'<div class=\\\"fold-block\\\" data-fold><div class=\\\"fb-head\\\">易错点 \' + icon(\'chevron-down\', 15) + \'</div><div class=\\\"fb-body\\\">\' + (k.pitfalls || \'<p>暂无</p>\') + \'</div></div>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"glass card\\\" style=\\\"margin-top:14px\\\"><div class=\\\"card-title\\\">学习信息</div>\' +\\n        \'<div class=\\\"proj-info\\\">\' +\\n          \'<div class=\\\"pi-item\\\"><div class=\\\"pi-label\\\">掌握程度</div><div class=\\\"pi-val\\\"><button class=\\\"btn sm\\\" data-mastery>\' + MASTERY_NAMES[k.mastery] + \' ▾</button></div></div>\' +\\n          \'<div class=\\\"pi-item\\\"><div class=\\\"pi-label\\\">下次复习（艾宾浩斯）</div><div class=\\\"pi-val\\\" data-next>\' + (k.nextReview ? WB.fmtDate(k.nextReview, true) : \'—\') + \'</div></div>\' +\\n          \'<div class=\\\"pi-item\\\" style=\\\"grid-column:1/-1\\\"><div class=\\\"pi-label\\\">关联题目</div><div class=\\\"pi-val\\\">\' +\\n            (relQuestions.length ? relQuestions.map(q => \'<span class=\\\"chip clickable\\\" data-q=\\\"\' + q.id + \'\\\" style=\\\"margin:2px 4px 2px 0\\\">\' + esc(q.stem.slice(0, 22)) + \'…</span>\').join(\'\') : \'<span style=\\\"color:var(--text-3);font-weight:400\\\">暂无关联题目</span>\') +\\n          \'</div></div>\' +\\n        \'</div></div>\' +\\n      \'</div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      $(\'[data-back]\', content).addEventListener(\'click\', () => location.hash = \'#/study/tree\');\\n      $(\'[data-full]\', content).addEventListener(\'click\', () => {\\n        WB.toggleFullscreen($(\'.content\'));\\n        WB.toast(document.fullscreenElement ? \'已进入全屏阅读\' : \'已退出全屏\');\\n      });\\n      /* 折叠区块 */\\n      $$(\'[data-fold]\', content).forEach(b => b.querySelector(\'.fb-head\').addEventListener(\'click\', () => b.classList.toggle(\'open\')));\\n      /* 掌握程度 */\\n      $(\'[data-mastery]\', content).addEventListener(\'click\', () => {\\n        const body = el(\'<div><div class=\\\"mastery-5\\\">\' + MASTERY_NAMES.map((n, i) =>\\n          \'<button data-lvl=\\\"\' + i + \'\\\"\' + (k.mastery === i ? \' class=\\\"on\\\"\' : \'\') + \'>\' + n + \'</button>\').join(\'\') + \'</div></div>\');\\n        const m = WB.openModal({ title: \'调整掌握程度\', body });\\n        $$(\'[data-lvl]\', body).forEach(b => b.addEventListener(\'click\', () => {\\n          const kk = WB.store.ops.setMastery(id, Number(b.dataset.lvl));\\n          m.close();\\n          $(\'[data-mastery]\', content).textContent = MASTERY_NAMES[kk.mastery] + \' ▾\';\\n          $(\'[data-next]\', content).textContent = WB.fmtDate(kk.nextReview, true);\\n          WB.toast(\'已更新，复习日期已按艾宾浩斯重算\');\\n        }));\\n      });\\n      /* 关联题目跳转题库 */\\n      $$(\'[data-q]\', content).forEach(c => c.addEventListener(\'click\', () => {\\n        location.hash = \'#/study/questions?focus=\' + c.dataset.q;\\n      }));\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 12. 题库 ================= */\\n  WB.pages.questions = function () {\\n    const data = S();\\n    const mods = [...new Set(data.questions.map(q => q.module))];\\n    const tags = [...new Set(data.questions.flatMap(q => q.tags || []))];\\n    const sources = [...new Set(data.questions.map(q => q.source).filter(Boolean))];\\n    const fMod = this._mod || \'\', fTag = this._tag || \'\', fSrc = this._src || \'\', fKw = (this._kw || \'\').toLowerCase();\\n    const focusId = this._focus || \'\';\\n\\n    const list = data.questions.filter(q =>\\n      (!fMod || q.module === fMod) &&\\n      (!fTag || (q.tags || []).includes(fTag)) &&\\n      (!fSrc || q.source === fSrc) &&\\n      (!fKw || (q.stem + \' \' + (q.tags || []).join(\' \')).toLowerCase().includes(fKw))\\n    );\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>题库</h2><div style=\\\"flex:1\\\"></div>\' +\\n        \'<button class=\\\"btn primary\\\" data-new>\' + icon(\'plus\', 16) + \' 录入题目</button></div>\' +\\n      \'<div class=\\\"filter-bar\\\">\' +\\n        \'<select class=\\\"select\\\" data-mod><option value=\\\"\\\">全部模块</option>\' + mods.map(m => \'<option value=\\\"\' + esc(m) + \'\\\"\' + (fMod === m ? \' selected\' : \'\') + \'>\' + esc(m) + \'</option>\').join(\'\') + \'</select>\' +\\n        \'<select class=\\\"select\\\" data-tag><option value=\\\"\\\">全部标签</option>\' + tags.map(t => \'<option value=\\\"\' + esc(t) + \'\\\"\' + (fTag === t ? \' selected\' : \'\') + \'>\' + esc(t) + \'</option>\').join(\'\') + \'</select>\' +\\n        \'<select class=\\\"select\\\" data-src><option value=\\\"\\\">全部来源</option>\' + sources.map(s => \'<option value=\\\"\' + esc(s) + \'\\\"\' + (fSrc === s ? \' selected\' : \'\') + \'>\' + esc(s) + \'</option>\').join(\'\') + \'</select>\' +\\n        \'<div class=\\\"topbar-search\\\" style=\\\"max-width:220px;flex:1\\\">\' + icon(\'search\', 15) + \'<input data-search placeholder=\\\"搜索题干…\\\" style=\\\"border:none;outline:none;background:transparent;flex:1;font-size:13px\\\" value=\\\"\' + esc(this._kw || \'\') + \'\\\"></div>\' +\\n      \'</div>\' +\\n      \'<div data-list>\' +\\n        list.map((q, i) => {\\n          const optHtml = (q.options || []).map(o => {\\n            const letter = o.slice(0, 1);\\n            const correct = letter === q.answer;\\n            return \'<div class=\\\"q-option\' + (correct ? \' correct\' : \'\') + \'\\\">\' + esc(o) + \'</div>\';\\n          }).join(\'\');\\n          return \'<div class=\\\"glass q-card\' + (focusId === q.id ? \' expanded\' : \'\') + \'\\\" data-q=\\\"\' + q.id + \'\\\">\' +\\n            \'<div class=\\\"q-stem\\\" data-toggle>\' + (i + 1) + \'. \' + esc(q.stem) + \'</div>\' +\\n            \'<div class=\\\"q-options\\\">\' + optHtml + \'</div>\' +\\n            \'<div class=\\\"q-answer-mask\\\">\' +\\n              \'<button class=\\\"btn sm\\\" data-reveal>\' + icon(\'eye\', 14) + \' 查看答案</button>\' +\\n              \'<div class=\\\"q-answer\\\">答案：\' + esc(q.answer) + \'</div>\' +\\n              \'<div class=\\\"q-analysis\\\">解析：\' + esc(q.analysis || \'暂无\') + \'</div>\' +\\n            \'</div>\' +\\n            \'<div class=\\\"q-meta\\\"><span class=\\\"chip\\\">\' + esc(q.module) + \'</span>\' + (q.tags || []).map(t => \'<span class=\\\"chip\\\">#\' + esc(t) + \'</span>\').join(\'\') +\\n              (q.source ? \'<span class=\\\"chip\\\" style=\\\"background:var(--info-soft);color:var(--info)\\\">\' + esc(q.source) + \'</span>\' : \'\') +\\n              \'<span style=\\\"font-size:11px;color:var(--text-3);margin-left:auto\\\">\' + WB.fmtDate(q.createdAt) + \'</span></div>\' +\\n          \'</div>\';\\n        }).join(\'\') +\\n        (!list.length ? \'<div class=\\\"empty glass card\\\">\' + icon(\'list\', 30) + \'<div>没有符合条件的题目</div></div>\' : \'\') +\\n      \'</div>\' +\\n      \'<div style=\\\"text-align:center;margin-top:18px\\\"><button class=\\\"btn\\\" data-import>\' + icon(\'upload\', 15) + \' 批量导入（粘贴文本解析）</button></div>\' +\\n      \'</div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const getFilters = () => ({\\n        mod: $(\'[data-mod]\', content).value, tag: $(\'[data-tag]\', content).value,\\n        src: $(\'[data-src]\', content).value, kw: ($(\'[data-search]\', content).value || \'\').trim(),\\n      });\\n      const rerender = () => { const f = getFilters(); WB.navigate(\'#/study/questions\', { mod: f.mod, tag: f.tag, src: f.src, kw: f.kw }); };\\n      [\'mod\', \'tag\', \'src\'].forEach(k => $(\'[data-\' + k + \']\', content).addEventListener(\'change\', rerender));\\n      $(\'[data-search]\', content).addEventListener(\'input\', WB.debounce(rerender, 300));\\n\\n      /* 展开/收起 + 答案遮罩 */\\n      $$(\'.q-card\', content).forEach(card => {\\n        card.querySelector(\'[data-toggle]\').addEventListener(\'click\', () => card.classList.toggle(\'expanded\'));\\n        card.querySelector(\'[data-reveal]\').addEventListener(\'click\', () => {\\n          card.classList.toggle(\'show-answer\');\\n          const btn = card.querySelector(\'[data-reveal]\');\\n          btn.innerHTML = card.classList.contains(\'show-answer\') ? icon(\'eye-off\', 14) + \' 隐藏答案\' : icon(\'eye\', 14) + \' 查看答案\';\\n        });\\n      });\\n\\n      /* 录入题目 */\\n      $(\'[data-new]\', content).addEventListener(\'click\', () => {\\n        const body = el(\'<div>\' +\\n          \'<div class=\\\"form-row\\\"><label>题干 *</label><textarea class=\\\"textarea\\\" data-stem placeholder=\\\"题目内容\\\"></textarea></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>选项（每行一个，如：A. xxx）</label><textarea class=\\\"textarea\\\" data-opts placeholder=\\\"A. ...\\\\nB. ...\\\\nC. ...\\\\nD. ...\\\" style=\\\"min-height:100px\\\"></textarea></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>答案（字母）</label><input class=\\\"input\\\" data-ans placeholder=\\\"A\\\"></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>解析</label><textarea class=\\\"textarea\\\" data-ana placeholder=\\\"答案解析\\\"></textarea></div>\' +\\n          \'<div style=\\\"display:flex;gap:10px\\\"><div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>所属模块</label><input class=\\\"input\\\" data-mod placeholder=\\\"如：判断推理\\\"></div>\' +\\n          \'<div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>来源</label><input class=\\\"input\\\" data-src placeholder=\\\"如：历年真题\\\"></div></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>标签（逗号分隔）</label><input class=\\\"input\\\" data-tags placeholder=\\\"假言命题, 翻译推理\\\"></div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-cancel>取消</button><button class=\\\"btn primary\\\" data-ok style=\\\"margin-left:10px\\\">保存题目</button></div>\');\\n        const m = WB.openModal({ title: \'录入题目\', body, foot, wide: true });\\n        foot.querySelector(\'[data-cancel]\').addEventListener(\'click\', m.close);\\n        foot.querySelector(\'[data-ok]\').addEventListener(\'click\', () => {\\n          const stem = body.querySelector(\'[data-stem]\').value.trim();\\n          if (!stem) { WB.toast(\'题干必填\', \'err\'); return; }\\n          const options = body.querySelector(\'[data-opts]\').value.split(\'\\\\n\').map(s => s.trim()).filter(Boolean);\\n          const answer = body.querySelector(\'[data-ans]\').value.trim().toUpperCase();\\n          WB.store.ops.addQuestion({\\n            stem, options: options.length ? options : [\'A. \', \'B. \', \'C. \', \'D. \'],\\n            answer: answer || \'A\',\\n            analysis: body.querySelector(\'[data-ana]\').value.trim(),\\n            module: body.querySelector(\'[data-mod]\').value.trim() || \'未分类\',\\n            source: body.querySelector(\'[data-src]\').value.trim() || \'\',\\n            tags: body.querySelector(\'[data-tags]\').value.split(/[,，]/).map(s => s.trim()).filter(Boolean),\\n          });\\n          m.close();\\n          WB.toast(\'题目已录入\');\\n          rerender();\\n        });\\n      });\\n\\n      /* 批量导入：解析纯文本格式 */\\n      $(\'[data-import]\', content).addEventListener(\'click\', () => {\\n        const body = el(\'<div>\' +\\n          \'<div class=\\\"form-row\\\"><label>粘贴题目文本（格式：题干；选项 A/B/C/D；答案：X；解析：…，用空行分隔多题）</label>\' +\\n          \'<textarea class=\\\"textarea\\\" data-batch style=\\\"min-height:180px\\\" placeholder=\\\"示例：&#10;我国的根本政治制度是？&#10;A. 人民代表大会制度 B. 多党合作制 C. 民族区域自治 D. 基层群众自治&#10;答案：A&#10;解析：宪法规定…\\\"></textarea></div>\' +\\n          \'<div class=\\\"hint\\\">也可从 .txt 文件导入</div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-cancel>取消</button><button class=\\\"btn primary\\\" data-ok style=\\\"margin-left:10px\\\">解析并导入</button></div>\');\\n        const m = WB.openModal({ title: \'批量导入题目\', body, foot, wide: true });\\n        foot.querySelector(\'[data-cancel]\').addEventListener(\'click\', m.close);\\n        foot.querySelector(\'[data-ok]\').addEventListener(\'click\', () => {\\n          const text = body.querySelector(\'[data-batch]\').value.trim();\\n          if (!text) { WB.toast(\'请粘贴题目文本\', \'err\'); return; }\\n          const blocks = text.split(/\\\\n\\\\s*\\\\n/).map(b => b.trim()).filter(Boolean);\\n          let count = 0;\\n          blocks.forEach(block => {\\n            const lines = block.split(\'\\\\n\').map(l => l.trim()).filter(Boolean);\\n            if (!lines.length) return;\\n            const stem = lines[0];\\n            const optLine = lines.find(l => /^[A-Da-d]\\\\./.test(l));\\n            const options = lines.filter(l => /^[A-Da-d]\\\\./.test(l));\\n            const ansLine = lines.find(l => /^答案[:：]/.test(l)) || lines.find(l => /^[A-Da-d]$/.test(l));\\n            const anaLine = lines.find(l => /^解析[:：]/.test(l));\\n            if (!options.length) return;\\n            WB.store.ops.addQuestion({\\n              stem,\\n              options,\\n              answer: ansLine ? (ansLine.replace(/^答案[:：]/, \'\').trim() || ansLine.trim()).toUpperCase() : \'A\',\\n              analysis: anaLine ? anaLine.replace(/^解析[:：]/, \'\') : \'\',\\n              module: \'批量导入\', source: \'\', tags: [],\\n            });\\n            count++;\\n          });\\n          m.close();\\n          WB.toast(\'成功导入 \' + count + \' 道题\');\\n          rerender();\\n        });\\n      });\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 13. 错题本 ================= */\\n  WB.pages.wrong = function () {\\n    const data = S();\\n    const today = WB.todayStr();\\n    const total = data.wrongQuestions.length;\\n    const pending = data.wrongQuestions.filter(w => w.status === \'pending\').length;\\n    const learning = data.wrongQuestions.filter(w => w.status === \'learning\').length;\\n    const archived = data.wrongQuestions.filter(w => w.status === \'archived\').length;\\n    const tab = this._tab || \'all\';\\n\\n    const list = data.wrongQuestions.filter(w => tab === \'all\' ? true : w.status === tab);\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>错题本</h2><div class=\\\"sub\\\">先做题，再看答案，连续答对 3 次自动归档</div></div>\' +\\n      \'<div class=\\\"wrong-stats\\\">\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-num\\\">\' + total + \'</div><div class=\\\"stat-label\\\">总错题数</div></div>\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-num\\\" style=\\\"color:var(--danger)\\\">\' + pending + \'</div><div class=\\\"stat-label\\\">待复习</div></div>\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-num\\\" style=\\\"color:var(--warn)\\\">\' + learning + \'</div><div class=\\\"stat-label\\\">掌握中</div></div>\' +\\n        \'<div class=\\\"glass card stat-card\\\"><div class=\\\"stat-num\\\" style=\\\"color:var(--accent-2)\\\">\' + archived + \'</div><div class=\\\"stat-label\\\">已归档</div></div>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"tabs\\\" data-tabs style=\\\"margin-bottom:14px\\\">\' +\\n        [[\'all\', \'全部\'], [\'pending\', \'待复习\'], [\'learning\', \'掌握中\'], [\'archived\', \'已归档\']].map(([k, label]) =>\\n          \'<button class=\\\"tab-btn\' + (tab === k ? \' active\' : \'\') + \'\\\" data-tab=\\\"\' + k + \'\\\">\' + label + \'</button>\').join(\'\') +\\n        \'<span class=\\\"tab-indicator\\\"></span></div>\' +\\n      \'<div data-list>\' +\\n        list.map(w => \'<div class=\\\"glass wrong-item\\\" data-wrong=\\\"\' + w.id + \'\\\">\' +\\n          \'<div style=\\\"display:flex;align-items:center;gap:8px;margin-bottom:6px\\\">\' +\\n            \'<span class=\\\"reason-tag\\\">\' + esc(w.reason || \'未分类\') + \'</span>\' +\\n            \'<span class=\\\"chip\\\">复习 \' + w.reviewCount + \' 次</span>\' +\\n            \'<span class=\\\"chip\\\">最近 \' + (w.lastResult ? \'✅ 正确\' : \'❌ 错误\') + \'</span>\' +\\n            (w.status === \'archived\' ? \'<span class=\\\"chip\\\" style=\\\"background:var(--accent-2-soft);color:var(--accent-2)\\\">已归档</span>\' : \'\') +\\n            \'<span style=\\\"margin-left:auto;font-size:12px;color:\' + (w.nextReview && w.nextReview <= today ? \'var(--danger)\' : \'var(--text-3)\') + \'\\\">下次复习 \' + (w.nextReview ? WB.fmtDate(w.nextReview) : \'—\') + \'</span></div>\' +\\n          \'<div style=\\\"font-size:14px;font-weight:600\\\">\' + esc(w.stem) + \'</div></div>\').join(\'\') +\\n        (!list.length ? \'<div class=\\\"empty glass card\\\">\' + icon(\'refresh\', 30) + \'<div>这里空空如也</div></div>\' : \'\') +\\n      \'</div></div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const rerender = (tab) => WB.navigate(\'#/study/wrong\', { tab: tab || $(\'[data-tab].active\', content).dataset.tab });\\n      const ind = $(\'.tab-indicator\', content);\\n      const move = (btn) => { ind.style.left = btn.offsetLeft + \'px\'; ind.style.width = btn.offsetWidth + \'px\'; };\\n      move($(\'[data-tab].active\', content));\\n      $$(\'[data-tab]\', content).forEach(b => b.addEventListener(\'click\', () => rerender(b.dataset.tab)));\\n\\n      /* 复习模式 */\\n      $$(\'[data-wrong]\', content).forEach(card => card.addEventListener(\'click\', () => {\\n        const w = S().wrongQuestions.find(x => x.id === card.dataset.wrong);\\n        if (!w) return;\\n        const body = el(\'<div class=\\\"review-quiz\\\">\' +\\n          \'<div style=\\\"font-size:16px;font-weight:700;line-height:1.8;margin-bottom:6px\\\">\' + esc(w.stem) + \'</div>\' +\\n          \'<div class=\\\"rq-options\\\">\' + (w.options || []).map((o, i) =>\\n            \'<div class=\\\"rq-option\\\" data-opt=\\\"\' + esc(o.slice(0, 1)) + \'\\\" data-idx=\\\"\' + i + \'\\\">\' + esc(o) + \'</div>\').join(\'\') + \'</div>\' +\\n          \'<div data-feedback style=\\\"margin-top:16px;display:none\\\"></div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-close>关闭</button></div>\');\\n        const m = WB.openModal({ title: \'复习模式 · 先做题再看答案\', body, foot, wide: true });\\n        let answered = false;\\n        $$(\'.rq-option\', body).forEach(opt => opt.addEventListener(\'click\', () => {\\n          if (answered) return;\\n          answered = true;\\n          const picked = opt.dataset.opt.toUpperCase();\\n          const correct = picked === (w.answer || \'\').toUpperCase();\\n          $$(\'.rq-option\', body).forEach(o => {\\n            o.classList.add(\'disabled\');\\n            if (o.dataset.opt.toUpperCase() === (w.answer || \'\').toUpperCase()) o.classList.add(\'correct\');\\n            if (o === opt && !correct) o.classList.add(\'wrong\');\\n          });\\n          const ww = WB.store.ops.reviewWrong(w.id, correct);\\n          const fb = body.querySelector(\'[data-feedback]\');\\n          fb.style.display = \'\';\\n          if (correct) {\\n            if (ww.status === \'archived\') { fb.innerHTML = \'<div style=\\\"background:var(--accent-2-soft);color:var(--accent-2);padding:12px 16px;border-radius:12px;font-weight:700\\\">🎉 连续答对 3 次，已自动归档！</div>\'; WB.confetti(); }\\n            else fb.innerHTML = \'<div style=\\\"background:var(--accent-2-soft);color:var(--accent-2);padding:12px 16px;border-radius:12px;font-weight:600\\\">✅ 回答正确！下次复习：\' + WB.fmtDate(ww.nextReview) + \'</div>\';\\n          } else {\\n            fb.innerHTML = \'<div style=\\\"background:var(--danger-soft);color:var(--danger);padding:12px 16px;border-radius:12px;font-weight:600\\\">❌ 回答错误，复习间隔已重算：明天再来</div>\' +\\n              \'<div style=\\\"margin-top:10px;padding:10px 14px;border-radius:10px;background:var(--input-bg);font-size:13px;color:var(--text-2)\\\">正确答案：\' + esc(w.answer) + \'</div>\';\\n          }\\n          foot.querySelector(\'[data-close]\').textContent = \'完成\';\\n        }));\\n        foot.querySelector(\'[data-close]\').addEventListener(\'click\', () => { m.close(); rerender(tab); });\\n      }));\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 14. 学习计划 ================= */\\n  WB.pages.plans = function () {\\n    const data = S();\\n    const type = this._type || \'week\';\\n    const today = WB.todayStr();\\n    const plans = data.plans.filter(p => p.type === type);\\n\\n    const MOD_COLORS = [\'#c96f4a\', \'#6b8f71\', \'#5b7f9e\', \'#c99a3d\', \'#b9825f\', \'#9a8f80\'];\\n    const planBarHtml = (p) => {\\n      const total = Object.values(p.modules || {}).reduce((a, b) => a + (Number(b) || 0), 0);\\n      const entries = Object.entries(p.modules || {});\\n      const segs = entries.map(([name, h], i) => \'<i style=\\\"width:\' + (total ? h / total * 100 : 0) + \'%;background:\' + MOD_COLORS[i % 6] + \'\\\" title=\\\"\' + esc(name) + \' \' + h + \'h\\\"></i>\').join(\'\');\\n      return { total, entries, segs };\\n    };\\n    const actualHours = (p) => {\\n      let sec = 0;\\n      const d0 = new Date(p.start + \'T00:00:00\'), d1 = new Date(p.end + \'T00:00:00\');\\n      const cur = new Date(d0);\\n      while (cur <= d1 && cur <= new Date()) {\\n        const c = data.checkins[WB.store.iso(cur)];\\n        if (c && c.submitted) sec += c.seconds || 0;\\n        cur.setDate(cur.getDate() + 1);\\n      }\\n      return sec / 3600;\\n    };\\n\\n    /* 对比柱状图：本周/本月 */\\n    const chartMode = type;\\n    const labels = chartMode === \'week\' ? [\'一\', \'二\', \'三\', \'四\', \'五\', \'六\', \'日\'] : [\'第1周\', \'第2周\', \'第3周\', \'第4周\'];\\n    const chart = labels.map((label, i) => {\\n      let target = 3, actual = 0;\\n      if (chartMode === \'week\') {\\n        const d = new Date(); d.setDate(d.getDate() - d.getDay() + i + 1);\\n        const key = WB.store.iso(d);\\n        const c = data.checkins[key];\\n        if (c && c.submitted) actual = (c.seconds || 0) / 3600;\\n      } else {\\n        const y = new Date().getFullYear(), mo = new Date().getMonth();\\n        const d0 = new Date(y, mo, i * 7 + 1), d1 = new Date(y, mo, Math.min((i + 1) * 7, new Date(y, mo + 1, 0).getDate()));\\n        for (let dd = new Date(d0); dd <= d1; dd.setDate(dd.getDate() + 1)) {\\n          const c = data.checkins[WB.store.iso(dd)];\\n          if (c && c.submitted) actual += (c.seconds || 0) / 3600;\\n        }\\n      }\\n      return { label, target, actual };\\n    });\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>学习计划</h2><div style=\\\"flex:1\\\"></div>\' +\\n        \'<div class=\\\"segmented\\\" data-type><button data-t=\\\"week\\\" class=\\\"\' + (type === \'week\' ? \'on\' : \'\') + \'\\\">周计划</button><button data-t=\\\"month\\\" class=\\\"\' + (type === \'month\' ? \'on\' : \'\') + \'\\\">月计划</button></div>\' +\\n        \'<button class=\\\"btn primary\\\" data-new>\' + icon(\'plus\', 16) + \' 新建计划</button></div>\' +\\n\\n      \'<div data-plans>\' +\\n        plans.map(p => {\\n          const { total, entries, segs } = planBarHtml(p);\\n          const actual = actualHours(p);\\n          const pct = Math.min(100, total ? Math.round(actual / total * 100) : 0);\\n          const overdue = p.end < today && !p.done;\\n          return \'<div class=\\\"glass plan-card\\\" data-plan=\\\"\' + p.id + \'\\\">\' +\\n            \'<div class=\\\"pc-top\\\"><div><div class=\\\"pc-title\\\">\' + esc(p.title) + (overdue ? \' <span class=\\\"plan-overdue\\\">超期未完成</span>\' : \'\') + \'</div>\' +\\n            \'<div class=\\\"pc-range\\\">\' + WB.fmtDate(p.start) + \' ~ \' + WB.fmtDate(p.end) + \' · 共 \' + total + \'h</div></div>\' +\\n            \'<span class=\\\"chip\\\">已完成 \' + pct + \'%</span></div>\' +\\n            \'<div class=\\\"stack-bar\\\">\' + segs + \'</div>\' +\\n            \'<div style=\\\"display:flex;justify-content:space-between;font-size:11.5px;color:var(--text-3);margin-top:6px\\\">\' +\\n              entries.map(([n, h], i) => \'<span><i style=\\\"display:inline-block;width:8px;height:8px;border-radius:2px;background:\' + MOD_COLORS[i % 6] + \';margin-right:4px\\\"></i>\' + esc(n) + \' \' + h + \'h</span>\').join(\'\') +\\n            \'</div>\' +\\n            \'<div class=\\\"progress\\\" style=\\\"margin-top:10px\\\"><i class=\\\"\' + (pct >= 100 ? \'green\' : \'\') + \'\\\" style=\\\"width:\' + pct + \'%\\\"></i></div>\' +\\n            \'<div style=\\\"font-size:12px;color:var(--text-3);margin-top:6px\\\">已投入 \' + actual.toFixed(1) + \'h / 目标 \' + total + \'h</div></div>\';\\n        }).join(\'\') +\\n        (!plans.length ? \'<div class=\\\"empty glass card\\\">\' + icon(\'calendar\', 30) + \'<div>还没有\' + (type === \'week\' ? \'周\' : \'月\') + \'计划，点击右上角新建</div></div>\' : \'\') +\\n      \'</div>\' +\\n\\n      \'<div class=\\\"section-title\\\">本周实际投入 vs 目标</div>\' +\\n      \'<div class=\\\"glass card\\\"><div class=\\\"bar-chart\\\">\' +\\n        chart.map(c => \'<div class=\\\"bar-group\\\"><div class=\\\"bar-pair\\\"><div class=\\\"bar actual\\\" style=\\\"height:\' + Math.max(3, c.actual / 6 * 100) + \'%\\\" title=\\\"实际 \' + c.actual.toFixed(1) + \'h\\\"></div>\' +\\n        \'<div class=\\\"bar target\\\" style=\\\"height:\' + Math.max(3, c.target / 6 * 100) + \'%\\\" title=\\\"目标 \' + c.target + \'h\\\"></div></div><div class=\\\"bg-label\\\">\' + c.label + \'</div></div>\').join(\'\') +\\n      \'</div>\' +\\n      \'<div class=\\\"legend\\\"><span><i style=\\\"background:var(--accent)\\\"></i>实际投入</span><span><i style=\\\"background:var(--hover);border:1px dashed var(--text-3)\\\"></i>目标</span></div></div>\' +\\n      \'</div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const rerender = (t) => WB.navigate(\'#/study/plans\', { type: t || $(\'[data-t=\\\"\' + type + \'\\\"]\', content).dataset.t });\\n      $$(\'[data-t]\', content).forEach(b => b.addEventListener(\'click\', () => rerender(b.dataset.t)));\\n\\n      /* 计划详情展开 */\\n      $$(\'[data-plan]\', content).forEach(card => card.addEventListener(\'click\', (e) => {\\n        if (e.target.closest(\'.btn\')) return;\\n        const p = data.plans.find(x => x.id === card.dataset.plan);\\n        const { entries, total } = planBarHtml(p);\\n        const actual = actualHours(p);\\n        const body = el(\'<div>\' + entries.map(([n, h], i) =>\\n          \'<div class=\\\"plan-detail-row\\\"><span><i style=\\\"display:inline-block;width:9px;height:9px;border-radius:2px;background:\' + MOD_COLORS[i % 6] + \';margin-right:6px\\\"></i>\' + esc(n) + \'</span><b>\' + h + \'h</b></div>\').join(\'\') +\\n          \'<div class=\\\"plan-detail-row\\\"><span>累计投入</span><b>\' + actual.toFixed(1) + \'h / \' + total + \'h</b></div>\' +\\n          \'<div style=\\\"margin-top:12px\\\" class=\\\"progress\\\"><i style=\\\"width:\' + Math.min(100, total ? actual / total * 100 : 0) + \'%\\\"></i></div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-done>\' + (p.done ? \'标记未完成\' : \'标记完成\') + \'</button><button class=\\\"btn primary\\\" data-close>关闭</button></div>\');\\n        const m = WB.openModal({ title: p.title + \' · 模块明细\', body, foot });\\n        foot.querySelector(\'[data-close]\').addEventListener(\'click\', m.close);\\n        foot.querySelector(\'[data-done]\').addEventListener(\'click\', () => {\\n          p.done = !p.done;\\n          p.status = p.done ? \'finished\' : \'active\';\\n          WB.store.save();\\n          m.close();\\n          WB.toast(p.done ? \'已标记完成并存入历史\' : \'已取消完成\');\\n          rerender(type);\\n        });\\n      }));\\n\\n      /* 新建计划 */\\n      $(\'[data-new]\', content).addEventListener(\'click\', () => {\\n        const body = el(\'<div>\' +\\n          \'<div class=\\\"form-row\\\"><label>计划标题</label><input class=\\\"input\\\" data-title placeholder=\\\"如：冲刺周计划\\\"></div>\' +\\n          \'<div style=\\\"display:flex;gap:10px\\\"><div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>开始</label><input class=\\\"input\\\" type=\\\"date\\\" data-start value=\\\"\' + WB.todayStr() + \'\\\"></div>\' +\\n          \'<div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>结束</label><input class=\\\"input\\\" type=\\\"date\\\" data-end></div></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>各模块目标小时数（模块名:小时，每行一个）</label><textarea class=\\\"textarea\\\" data-modules placeholder=\\\"言语理解: 3\\\\n判断推理: 4\\\\n资料分析: 2\\\"></textarea></div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-cancel>取消</button><button class=\\\"btn primary\\\" data-ok style=\\\"margin-left:10px\\\">创建</button></div>\');\\n        const m = WB.openModal({ title: \'新建\' + (type === \'week\' ? \'周\' : \'月\') + \'计划\', body, foot });\\n        foot.querySelector(\'[data-cancel]\').addEventListener(\'click\', m.close);\\n        foot.querySelector(\'[data-ok]\').addEventListener(\'click\', () => {\\n          const title = body.querySelector(\'[data-title]\').value.trim() || (type === \'week\' ? \'本周计划\' : \'本月计划\');\\n          const modules = {};\\n          body.querySelector(\'[data-modules]\').value.split(\'\\\\n\').forEach(line => {\\n            const [n, h] = line.split(/[:：]/).map(s => s.trim());\\n            if (n && h) modules[n] = Number(h) || 0;\\n          });\\n          if (!Object.keys(modules).length) { WB.toast(\'请至少填写一个模块目标\', \'err\'); return; }\\n          const start = body.querySelector(\'[data-start]\').value;\\n          const end = body.querySelector(\'[data-end]\').value;\\n          if (!start || !end || end < start) { WB.toast(\'请选择有效日期范围\', \'err\'); return; }\\n          WB.store.ops.addPlan({ type, title, start, end, modules });\\n          m.close();\\n          WB.toast(\'计划已创建\');\\n          rerender(type);\\n        });\\n      });\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 15. 学习打卡 ================= */\\n  WB.pages.checkin = function () {\\n    const data = S();\\n    const today = WB.todayStr();\\n    const goal = data.checkinDailyGoal || 3 * 3600;\\n    const todayCheckin = data.checkins[today];\\n    const baseSeconds = (todayCheckin && todayCheckin.seconds) || 0;\\n    const t = data.timer;\\n\\n    /* 计算当前已学时长（含运行中的计时） */\\n    const nowSeconds = baseSeconds + (t.running ? Math.max(0, (Date.now() - t.startAt) / 1000) : 0);\\n    const pct = Math.min(100, Math.round(nowSeconds / goal * 100));\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>学习打卡</h2><div class=\\\"sub\\\">今日目标 \' + WB.fmtDuration(goal) + \' · 已学 <span data-dur>\' + WB.fmtDuration(nowSeconds) + \'</span> · 连续 \' + WB.store.ops.streakDays() + \' 天</div></div>\' +\\n      \'<div class=\\\"checkin-layout\\\">\' +\\n        \'<div class=\\\"glass card checkin-main\\\">\' +\\n          \'<div data-ring>\' + WB.ring(pct, 150, 12) + \'</div>\' +\\n          \'<div class=\\\"timer-display\\\" data-timer>\' + WB.fmtSeconds(nowSeconds) + \'</div>\' +\\n          \'<div class=\\\"timer-controls\\\">\' +\\n            \'<button class=\\\"btn \' + (t.running ? \'danger\' : \'primary\') + \' lg\\\" data-start>\' + (t.running ? icon(\'pause\', 16) + \' 暂停\' : icon(\'play\', 16) + \' 开始\') + \'</button>\' +\\n            \'<button class=\\\"btn lg\\\" data-reset>\' + icon(\'refresh\', 15) + \' 重置</button>\' +\\n          \'</div>\' +\\n          \'<div class=\\\"section-title\\\" style=\\\"margin:6px 0 0\\\">本次计时归入模块（可多选）</div>\' +\\n          \'<div class=\\\"module-chips\\\" data-modules>\' +\\n            WB.studyModules.map(m => \'<span class=\\\"chip clickable\\\" data-mod=\\\"\' + m + \'\\\">\' + m + \'</span>\').join(\'\') +\\n          \'</div>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"glass card today-record\\\">\' +\\n          \'<div class=\\\"card-title\\\">今日打卡记录</div>\' +\\n          \'<div style=\\\"font-size:13px;color:var(--text-2);margin-bottom:12px\\\">已提交时长：<b data-submitted>\' + WB.fmtDuration(baseSeconds) + \'</b>（计时中时长提交时自动并入）</div>\' +\\n          \'<div class=\\\"form-row\\\"><label>今日总结</label><textarea class=\\\"textarea\\\" data-summary placeholder=\\\"今天学了什么？有什么收获？\\\">\' + esc((todayCheckin && todayCheckin.summary) || \'\') + \'</textarea></div>\' +\\n          \'<button class=\\\"btn success lg\\\" data-submit style=\\\"width:100%\\\">\' + icon(\'check\', 17) + \' 提交打卡</button>\' +\\n          \'<div class=\\\"hint\\\" style=\\\"margin-top:10px\\\">提交后写入当日记录，自动更新首页进度环与连续打卡天数；切走页面计时继续。</div>\' +\\n        \'</div>\' +\\n      \'</div></div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const timerEl = $(\'[data-timer]\', content);\\n      const durEl = $(\'[data-dur]\', content);\\n      const startBtn = $(\'[data-start]\', content);\\n      const ringEl = $(\'[data-ring]\', content);\\n      const valEl = ringEl.querySelector(\'.ring-val\');\\n      if (valEl) valEl.innerHTML = \'<span style=\\\"font-size:13px\\\">今日</span><br><span data-pct>\' + pct + \'</span><small>%</small>\';\\n\\n      const update = () => {\\n        const t2 = S().timer;\\n        const secs = baseSeconds + (t2.running ? Math.max(0, (Date.now() - t2.startAt) / 1000) : 0);\\n        timerEl.textContent = WB.fmtSeconds(secs);\\n        durEl.textContent = WB.fmtDuration(secs);\\n        const p = Math.min(100, Math.round(secs / goal * 100));\\n        const pctEl = ringEl.querySelector(\'[data-pct]\');\\n        if (pctEl) pctEl.textContent = p;\\n        WB.animateRing(ringEl, p);\\n      };\\n      const iv = setInterval(update, 1000);\\n      update();\\n      content._checkinIv = iv;\\n\\n      const setRunning = (running) => {\\n        S().timer.running = running;\\n        S().timer.startAt = running ? Date.now() : S().timer.startAt;\\n        WB.store.save();\\n        startBtn.innerHTML = running ? icon(\'pause\', 16) + \' 暂停\' : icon(\'play\', 16) + \' 开始\';\\n        startBtn.className = \'btn \' + (running ? \'danger\' : \'primary\') + \' lg\';\\n      };\\n      startBtn.addEventListener(\'click\', () => {\\n        const t2 = S().timer;\\n        if (t2.running) {\\n          /* 暂停：把当前增量并入当日记录 */\\n          const add = Math.max(0, (Date.now() - t2.startAt) / 1000);\\n          S().checkins[today] = { seconds: baseSeconds + add, summary: (todayCheckin && todayCheckin.summary) || \'\', modules: (todayCheckin && todayCheckin.modules) || [], submitted: (todayCheckin && todayCheckin.submitted) || false };\\n          setRunning(false);\\n          WB.toast(\'已暂停，时长已累计\');\\n          WB.navigate(\'#/study/checkin\');\\n        } else {\\n          setRunning(true);\\n          WB.toast(\'计时开始，切走页面也会继续计时 ⏱\');\\n        }\\n      });\\n      $(\'[data-reset]\', content).addEventListener(\'click\', () => {\\n        WB.confirmDialog({ title: \'重置计时\', message: \'将清空本次计时增量（不删除已提交记录），确定？\', okText: \'重置\', onOk: () => { S().timer = { running: false, startAt: null, elapsed: 0, modules: [] }; WB.store.save(); WB.navigate(\'#/study/checkin\'); } });\\n      });\\n\\n      /* 模块多选 */\\n      let selModules = (t.modules || []).slice();\\n      $$(\'[data-mod]\', content).forEach(chip => {\\n        if (selModules.includes(chip.dataset.mod)) chip.classList.add(\'on\');\\n        chip.addEventListener(\'click\', () => {\\n          const m = chip.dataset.mod;\\n          const idx = selModules.indexOf(m);\\n          if (idx >= 0) { selModules.splice(idx, 1); chip.classList.remove(\'on\'); }\\n          else { selModules.push(m); chip.classList.add(\'on\'); }\\n        });\\n      });\\n\\n      /* 提交打卡 */\\n      $(\'[data-submit]\', content).addEventListener(\'click\', () => {\\n        const summary = $(\'[data-summary]\', content).value.trim();\\n        const t2 = S().timer;\\n        let finalSeconds = baseSeconds;\\n        if (t2.running) finalSeconds += Math.max(0, (Date.now() - t2.startAt) / 1000);\\n        else if (t2.elapsed) finalSeconds += t2.elapsed;\\n        WB.store.ops.submitCheckin(today, Math.round(finalSeconds), summary, selModules);\\n        S().timer = { running: false, startAt: null, elapsed: 0, modules: [] };\\n        WB.toast(\'打卡成功！已写入今日记录 🎉\');\\n        clearInterval(iv);\\n        WB.navigate(\'#/study/checkin\');\\n      });\\n    };\\n    return { html, bind };\\n  };\\n\\n  /* ================= 16. 时政积累 ================= */\\n  WB.pages.current = function () {\\n    const data = S();\\n    const now = new Date();\\n    const month = this._month || (now.getFullYear() + \'-\' + String(now.getMonth() + 1).padStart(2, \'0\'));\\n    const fTag = this._tag || \'\';\\n    const tags = [...new Set(data.currentAffairs.flatMap(c => c.tags || []))];\\n    const today = WB.todayStr();\\n\\n    const list = data.currentAffairs.filter(c =>\\n      (c.date || \'\').startsWith(month) && (!fTag || (c.tags || []).includes(fTag))\\n    ).sort((a, b) => b.date.localeCompare(a.date));\\n\\n    const months = [];\\n    const m0 = new Date(now.getFullYear(), now.getMonth(), 1);\\n    for (let i = 0; i < 6; i++) {\\n      const d = new Date(m0);\\n      d.setMonth(d.getMonth() - i);\\n      months.push(d.getFullYear() + \'-\' + String(d.getMonth() + 1).padStart(2, \'0\'));\\n    }\\n\\n    const html = \'<div class=\\\"page\\\">\' +\\n      \'<div class=\\\"page-head\\\"><h2>时政积累</h2><div style=\\\"flex:1\\\"></div>\' +\\n        \'<button class=\\\"btn primary\\\" data-new>\' + icon(\'plus\', 16) + \' 录入时政</button></div>\' +\\n      \'<div style=\\\"display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:16px\\\">\' +\\n        \'<select class=\\\"select\\\" data-month style=\\\"width:130px\\\">\' + months.map(m => \'<option value=\\\"\' + m + \'\\\"\' + (m === month ? \' selected\' : \'\') + \'>\' + m.replace(\'-\', \' 年 \') + \' 月</option>\').join(\'\') + \'</select>\' +\\n        \'<div style=\\\"display:flex;gap:6px;flex-wrap:wrap\\\">\' +\\n          \'<span class=\\\"chip clickable\' + (!fTag ? \' on\' : \'\') + \'\\\" data-tag=\\\"\\\">全部</span>\' +\\n          tags.map(t => \'<span class=\\\"chip clickable\' + (fTag === t ? \' on\' : \'\') + \'\\\" data-tag=\\\"\' + esc(t) + \'\\\">\' + esc(t) + \'</span>\').join(\'\') +\\n        \'</div></div>\' +\\n      \'<div data-list>\' +\\n        list.map(c => {\\n          const old = c.date && c.date < today && (new Date(today + \'T00:00:00\') - new Date(c.date + \'T00:00:00\')) / 86400000 > 30;\\n          return \'<div class=\\\"glass current-card\\\" data-id=\\\"\' + c.id + \'\\\">\' +\\n            \'<div class=\\\"cc-head\\\"><div class=\\\"cc-title\\\">\' + esc(c.title) + (old ? \' <span class=\\\"review-hint\\\">\' + icon(\'clock\', 11) + \'建议回顾</span>\' : \'\') + \'</div>\' +\\n            \'<span class=\\\"chip\\\">\' + esc(c.source) + \'</span></div>\' +\\n            \'<div class=\\\"cc-meta\\\">\' + WB.fmtDate(c.date) + (c.tags || []).map(t => \' · #\' + esc(t)).join(\'\') + \'</div>\' +\\n            \'<div class=\\\"cc-summary\\\">\' + esc(c.summary) + \'</div>\' +\\n            (c.interpretation ? \'<div class=\\\"cc-interp\\\">解读：\' + esc(c.interpretation) + \'</div>\' : \'\') +\\n            (c.quote ? \'<div class=\\\"cc-quote\\\">“\' + esc(c.quote) + \'”</div>\' : \'\') +\\n          \'</div>\';\\n        }).join(\'\') +\\n        (!list.length ? \'<div class=\\\"empty glass card\\\">\' + icon(\'news\', 30) + \'<div>该月暂无时政记录</div></div>\' : \'\') +\\n      \'</div></div>\';\\n\\n    const content = $(\'#content\');\\n    const bind = () => {\\n      const rerender = () => WB.navigate(\'#/study/current\', { month: $(\'[data-month]\', content).value, tag: (content.querySelector(\'[data-tag].on\') || {}).dataset ? content.querySelector(\'[data-tag].on\').dataset.tag : \'\' });\\n      $(\'[data-month]\', content).addEventListener(\'change\', rerender);\\n      $$(\'[data-tag]\', content).forEach(t => t.addEventListener(\'click\', () => {\\n        $$(\'[data-tag]\', content).forEach(x => x.classList.remove(\'on\'));\\n        t.classList.add(\'on\');\\n        rerender();\\n      }));\\n      /* 展开全文 */\\n      $$(\'.current-card\', content).forEach(card => card.addEventListener(\'click\', () => card.classList.toggle(\'expanded\')));\\n\\n      /* 录入 */\\n      $(\'[data-new]\', content).addEventListener(\'click\', () => {\\n        const body = el(\'<div>\' +\\n          \'<div class=\\\"form-row\\\"><label>标题 *</label><input class=\\\"input\\\" data-title></div>\' +\\n          \'<div style=\\\"display:flex;gap:10px\\\"><div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>来源</label><input class=\\\"input\\\" data-source placeholder=\\\"如：人民日报\\\"></div>\' +\\n          \'<div class=\\\"form-row\\\" style=\\\"flex:1\\\"><label>日期</label><input class=\\\"input\\\" type=\\\"date\\\" data-date value=\\\"\' + WB.todayStr() + \'\\\"></div></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>原文摘要</label><textarea class=\\\"textarea\\\" data-summary></textarea></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>个人解读（可选）</label><textarea class=\\\"textarea\\\" data-interp></textarea></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>引用金句（可选）</label><input class=\\\"input\\\" data-quote placeholder=\\\"“...”\\\"></div>\' +\\n          \'<div class=\\\"form-row\\\"><label>标签（逗号分隔）</label><input class=\\\"input\\\" data-tags placeholder=\\\"经济, 科技\\\"></div></div>\');\\n        const foot = el(\'<div><button class=\\\"btn\\\" data-cancel>取消</button><button class=\\\"btn primary\\\" data-ok style=\\\"margin-left:10px\\\">保存</button></div>\');\\n        const m = WB.openModal({ title: \'录入时政\', body, foot, wide: true });\\n        foot.querySelector(\'[data-cancel]\').addEventListener(\'click\', m.close);\\n        foot.querySelector(\'[data-ok]\').addEventListener(\'click\', () => {\\n          const title = body.querySelector(\'[data-title]\').value.trim();\\n          if (!title) { WB.toast(\'标题必填\', \'err\'); return; }\\n          data.currentAffairs.unshift({\\n            id: WB.store.uid(), title,\\n            source: body.querySelector(\'[data-source]\').value.trim() || \'未知来源\',\\n            date: body.querySelector(\'[data-date]\').value || WB.todayStr(),\\n            summary: body.querySelector(\'[data-summary]\').value.trim(),\\n            interpretation: body.querySelector(\'[data-interp]\').value.trim(),\\n            quote: body.querySelector(\'[data-quote]\').value.trim(),\\n            tags: body.querySelector(\'[data-tags]\').value.split(/[,，]/).map(s => s.trim()).filter(Boolean),\\n            createdAt: WB.todayStr(),\\n          });\\n          WB.store.save();\\n          m.close();\\n          WB.toast(\'已录入\');\\n          rerender();\\n        });\\n      });\\n    };\\n    return { html, bind };\\n  };\\n\\n})();\\n\",\"path\":\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\\js\\\\pages-study.js\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 09:45:55');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
