s = re.findall(r\'^\\\\s{4}(\\\\w+)\\\\(\', ops_section, re.M)\\nprint(\\\"\\\\n=== store.js ops 方法 ===\\\")\\nprint(\\\"  \\\", \\\", \\\".join(sorted(set(methods))) if methods else \\\"(未找到 ops 对象)\\\")\\nprint(\\\"\\\\n=== store.js 导出 (WB.store.*) ===\\\")\\nexports = re.findall(r\'WB\\\\.store\\\\.(\\\\w+)\\\\s*=\', s)\\nprint(\\\"  \\\", \\\", \\\".join(sorted(set(exports))))\\n\"},\"effect\":\"write\",\"risk_level\":\"high\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 10:05:15'),
