(825, '40122540-fcbb-4890-9b07-1296c60efc8f', 72379, 'tool.started', 'code', 'moonya', 'pages_work', 'call_00_xHsJVHM0mtrkKDLgvxRs8199', '{\"tool_key\":\"edit_file\",\"display_name\":\"Edit File\",\"arguments\":{\"path\":\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\\js\\\\pages\\\\work.js\",\"command\":\"str_replace\",\"old_str\":\"  /*__MORE__*/\",\"new_str\":\"  /* ---------- 通用确认框 ---------- */\\n  function confirmModal(title, msg, onOk) {\\n    openModal({\\n      title: title,\\n      content: \'<p style=\\\"line-height:1.8;color:var(--text-2)\\\">\' + esc(msg) + \'</p>\',\\n      okText: \'确认\',\\n      cancelText: \'取消\',\\n      onOk: function () { onOk(); return true; }\\n    });\\n  }\\n\\n  /* ---------- 7.3 /work/inbox 收件箱 ---------- */\\n\\n  function inboxCardHtml(item) {\\n    var ribbon = item.urgency || \'mid\';\\n    return \'<div class=\\\"work-inbox-card\' + (item.done ? \' done\' : \'\') + \'\\\" data-id=\\\"\' + esc(item.id) + \'\\\">\' +\\n      \'<div class=\\\"work-inbox-ribbon work-ribbon \' + ribbon + \'\\\"></div>\' +\\n      \'<div class=\\\"work-inbox-actions\\\">\' +\\n      \'<button type=\\\"button\\\" class=\\\"work-inbox-act up\\\" data-act=\\\"upgrade\\\">\' + icon(\'up\', \'\', 16) + \'<span>升级为待办</span></button>\' +\\n      \'<button type=\\\"button\\\" class=\\\"work-inbox-act del\\\" data-act=\\\"del\\\">\' + icon(\'trash\', \'\', 16) + \'<span>删除</span></button>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"work-inbox-card-inner\\\" data-inner=\\\"1\\\">\' +\\n      \'<div class=\\\"work-inbox-text\\\">\' + esc(item.text) + \'</div>\' +\\n      \'<span class=\\\"work-inbox-time\\\">\' + timeText(item.createdAt) + \'</span>\' +\\n      \'</div></div>\';\\n  }\\n\\n  var workInbox = {\\n    title: \'收件箱\',\\n    render: function () {\\n      if (!storeReady()) return \'<div class=\\\"empty-state\\\">数据层未就绪，请确认 store.js 与 app.js 已加载。</div>\';\\n      var list = getInbox();\\n      var undone = list.filter(function (i) { return !i.done; }).length;\\n      var hint = \'\';\\n      try {\\n        if (undone > 0 && localStorage.getItem(\'workbench.inbox.hintDate\') !== todayStr()) {\\n          hint = \'<div class=\\\"work-hint\\\" data-hint=\\\"1\\\">\' + icon(\'inbox\', \'\', 16) +\\n            \'<span>收件箱有 <b>\' + undone + \'</b> 条待整理</span>\' +\\n            \'<button type=\\\"button\\\" class=\\\"close\\\" data-act=\\\"hint-close\\\">\' + icon(\'close\', \'\', 14) + \'</button></div>\';\\n        }\\n      } catch (e) { /* ignore */ }\\n      return \'<div class=\\\"work-page\\\" data-page=\\\"work-inbox\\\">\' +\\n        hint +\\n        \'<div class=\\\"work-bar\\\">\' +\\n        \'<div class=\\\"work-bar-left\\\"><span style=\\\"font-size:0.95rem\\\">未清理 <b style=\\\"color:var(--accent)\\\">\' + undone + \'</b> 条</span></div>\' +\\n        \'<div class=\\\"work-bar-right\\\">\' +\\n        \'<button class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"clear-done\\\" \' + (undone === list.length ? \'\' : \'\') + \'>\' + icon(\'checkSmall\', \'\', 15) + \'一键清空已完成</button>\' +\\n        \'</div></div>\' +\\n        \'<div class=\\\"work-inbox-list\\\">\' +\\n        (list.length ? list.map(inboxCardHtml).join(\'\') :\\n          \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'inbox\', \'\', 34) + \'</div>收件箱是空的，记点东西吧</div>\') +\\n        \'</div>\' +\\n        \'<div class=\\\"work-quick-add glass-card\\\">\' +\\n        icon(\'plus\', \'\', 17) +\\n        \'<input class=\\\"input\\\" data-act=\\\"quick\\\" type=\\\"text\\\" placeholder=\\\"记一下… 回车即存\\\" autocomplete=\\\"off\\\">\' +\\n        \'<span class=\\\"work-quick-tip\\\">Enter 保存</span>\' +\\n        \'</div></div>\';\\n    },\\n    mount: function (root) {\\n      if (!storeReady()) return;\\n      var el = root && root.nodeType === 1 ? root : document;\\n      var self = this;\\n      var openId = null;\\n      var press = null;\\n      var state = { drag: null };\\n\\n      /* 每日首次进入提示：记录已提示日期 */\\n      try {\\n        localStorage.setItem(\'workbench.inbox.hintDate\', todayStr());\\n      } catch (e) { /* ignore */ }\\n\\n      function rerender() {\\n        var cur = $(\'[data-page=\\\"work-inbox\\\"]\', el);\\n        if (!cur) return;\\n        var tmp = document.createElement(\'div\');\\n        tmp.innerHTML = self.render();\\n        var fresh = tmp.firstElementChild;\\n        cur.parentNode.replaceChild(fresh, cur);\\n        openId = null;\\n        if (press) press.destroy();\\n        press = null;\\n        bindSwipes($(\'[data-page=\\\"work-inbox\\\"]\', el));\\n      }\\n\\n      /* ---- 左滑手势（鼠标 / 触屏通用） ---- */\\n      function bindSwipes(scope) {\\n        if (!scope) return;\\n        var inners = $$(\'[data-inner=\\\"1\\\"]\', scope);\\n        inners.forEach(function (inner) {\\n          var card = inner.closest(\'.work-inbox-card\');\\n          var s = null;\\n          inner.addEventListener(\'pointerdown\', function (e) {\\n            if (e.pointerType === \'mouse\' && e.button !== 0) return;\\n            s = {\\n              x: e.clientX, y: e.clientY,\\n              startTx: card.classList.contains(\'open\') ? -152 : 0,\\n              dragging: false, moved: 0\\n            };\\n            inner.setPointerCapture && inner.setPointerCapture(e.pointerId);\\n          });\\n          inner.addEventListener(\'pointermove\', function (e) {\\n            if (!s) return;\\n            var dx = e.clientX - s.x, dy = e.clientY - s.y;\\n            if (!s.dragging) {\\n              if (Math.abs(dx) > 8 && Math.abs(dx) > Math.abs(dy)) s.dragging = true;\\n              else if (Math.abs(dy) > 8) { s = null; return; }\\n            }\\n            if (s.dragging) {\\n              s.moved = dx;\\n              inner.style.transition = \'none\';\\n              inner.style.transform = \'translateX(\' + clamp(s.startTx + dx, -152, 0) + \'px)\';\\n            }\\n          });\\n          function endSwipe(e) {\\n            if (!s) return;\\n            var dx = e.clientX - s.x;\\n            var finalTx;\\n            if (s.dragging) {\\n              finalTx = (s.startTx + dx < -60) ? -152 : 0;\\n              inner.style.transition = \'\';\\n              inner.style.transform = \'translateX(\' + finalTx + \'px)\';\\n              if (finalTx === -152) {\\n                openId = card.getAttribute(\'data-id\');\\n                $$(\'.work-inbox-card.open\', scope).forEach(function (c) {\\n                  if (c !== card) c.classList.remove(\'open\');\\n                });\\n                card.classList.add(\'open\');\\n              } else {\\n                card.classList.remove(\'open\');\\n              }\\n            }\\n            if (!s.dragging && Math.abs(dx) < 6) {\\n              /* 视为点击：打开编辑表单 */\\n              var item = store().inbox.get(card.getAttribute(\'data-id\'));\\n              if (item && !item.done) openInboxForm(item, rerender);\\n            }\\n            s = null;\\n          }\\n          inner.addEventListener(\'pointerup\', endSwipe);\\n          inner.addEventListener(\'pointercancel\', function () {\\n            if (s) {\\n              s = null;\\n              inner.style.transition = \'\';\\n              inner.style.transform = \'translateX(0px)\';\\n              card.classList.remove(\'open\');\\n              openId = null;\\n            }\\n          });\\n        });\\n      }\\n\\n      /* ---- 操作按钮 / 快捷新增 ---- */\\n      el.addEventListener(\'click\', function (e) {\\n        var up = e.target.closest(\'[data-act=\\\"upgrade\\\"]\');\\n        if (up) {\\n          var card = up.closest(\'.work-inbox-card\');\\n          var item = store().inbox.get(card.getAttribute(\'data-id\'));\\n          if (item) openInboxForm(item, rerender);\\n          return;\\n        }\\n        var del = e.target.closest(\'[data-act=\\\"del\\\"]\');\\n        if (del) {\\n          var c2 = del.closest(\'.work-inbox-card\');\\n          var id = c2.getAttribute(\'data-id\');\\n          confirmModal(\'删除\', \'确定删除这条收件箱记录吗？\', function () {\\n            store().inbox.remove(id);\\n            uiToast(\'已删除\', \'success\');\\n            rerender();\\n          });\\n          return;\\n        }\\n        var clear = e.target.closest(\'[data-act=\\\"clear-done\\\"]\');\\n        if (clear) {\\n          var doneList = getInbox().filter(function (i) { return i.done; });\\n          if (!doneList.length) { uiToast(\'没有已完成的记录\', \'warn\'); return; }\\n          confirmModal(\'清空已完成\', \'将删除 \' + doneList.length + \' 条已处理的记录，确定吗？\', function () {\\n            doneList.forEach(function (i) { store().inbox.remove(i.id); });\\n            uiToast(\'已清空\', \'success\');\\n            rerender();\\n          });\\n          return;\\n        }\\n        var hc = e.target.closest(\'[data-act=\\\"hint-close\\\"]\');\\n        if (hc) {\\n          var hint = hc.closest(\'.work-hint\');\\n          if (hint) {\\n            hint.style.transition = \'opacity 260ms cubic-bezier(0.25,0.6,0.3,1),transform 260ms cubic-bezier(0.25,0.6,0.3,1)\';\\n            hint.style.opacity = \'0\';\\n            hint.style.transform = \'translateY(-6px)\';\\n            setTimeout(function () { if (hint.parentNode) hint.parentNode.removeChild(hint); }, 270);\\n          }\\n          return;\\n        }\\n        var quick = e.target.closest(\'[data-act=\\\"quick\\\"]\');\\n        if (quick) quick.focus();\\n      });\\n\\n      el.addEventListener(\'keydown\', function (e) {\\n        var input = e.target.closest(\'[data-act=\\\"quick\\\"]\');\\n        if (!input) return;\\n        if (e.key === \'Enter\') {\\n          e.preventDefault();\\n          var v = input.value.trim();\\n          if (!v) return;\\n          store().inbox.add({ text: v, urgency: \'mid\', done: false });\\n          input.value = \'\';\\n          uiToast(\'已记下，稍后整理\', \'success\');\\n          rerender();\\n        } else if (e.key === \'Escape\') {\\n          input.value = \'\';\\n          input.blur();\\n        }\\n      });\\n\\n      bindSwipes($(\'[data-page=\\\"work-inbox\\\"]\', el));\\n\\n      this._cleanup = function () {\\n        el.removeEventListener(\'click\', this._onClick);\\n        el.removeEventListener(\'keydown\', this._onKey);\\n        if (press) press.destroy();\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  /* 收件箱条目 → 完整待办表单 */\\n  function openInboxForm(item, after) {\\n    var projects = sortProjects(getProjects()).filter(function (p) { return p.status !== \'archived\'; });\\n    var opts = \'<option value=\\\"\\\">无项目</option>\' + projects.map(function (p) {\\n      return \'<option value=\\\"\' + esc(p.id) + \'\\\">\' + esc(p.name) + \'</option>\';\\n    }).join(\'\');\\n    var html = \'<form data-form=\\\"inbox-up\\\">\' +\\n      \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">标题</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"title\\\" type=\\\"text\\\" value=\\\"\' + esc(item.text) + \'\\\" autocomplete=\\\"off\\\"></div>\' +\\n      \'<div class=\\\"work-form-grid\\\">\' +\\n      \'<div class=\\\"work-form-row\\\"><label>截止日期</label><input class=\\\"input\\\" data-f=\\\"due\\\" type=\\\"date\\\" value=\\\"\' + todayStr() + \'\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>所属项目</label><select class=\\\"select\\\" data-f=\\\"projectId\\\">\' + opts + \'</select></div>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>优先级</label><select class=\\\"select\\\" data-f=\\\"priority\\\">\' +\\n      [\'high\', \'mid\', \'low\'].map(function (p) {\\n        return \'<option value=\\\"\' + p + \'\\\"\' + ((PRIO_URGENCY[item.urgency] || \'mid\') === p ? \' selected\' : \'\') + \'>\' + (PRIO_LABEL[p]) + \'</option>\';\\n      }).join(\'\') +\\n      \'</select></div></form>\';\\n    openModal({\\n      title: \'整理为完整待办\',\\n      content: html,\\n      okText: \'升级为待办\',\\n      onOk: function (modal) {\\n        var title = $(\'[data-f=\\\"title\\\"]\', modal).value.trim();\\n        if (!title) { uiToast(\'请输入标题\', \'warn\'); return false; }\\n        store().todos.add({\\n          title: title,\\n          quadrant: \'q2\',\\n          priority: $(\'[data-f=\\\"priority\\\"]\', modal).value,\\n          due: $(\'[data-f=\\\"due\\\"]\', modal).value || todayStr(),\\n          done: false,\\n          projectId: $(\'[data-f=\\\"projectId\\\"]\', modal).value\\n        });\\n        store().inbox.update(item.id, { done: true });\\n        uiToast(\'已升级为今日待办\', \'success\');\\n        if (after) after();\\n        return true;\\n      }\\n    });\\n  }\\n\\n  /* ---------- 7.4 /work/projects 项目列表 ---------- */\\n\\n  var PROJ_COLORS = [\'#b06f47\', \'#6c9170\', \'#c49338\', \'#8a7a6a\', \'#a06a5c\', \'#5f7d8c\'];\\n  var PROJ_STATUS = {\\n    active: { label: \'进行中\', cls: \'tag-success\' },\\n    paused: { label: \'暂停\', cls: \'tag-warn\' },\\n    done: { label: \'已完结\', cls: \'tag-accent\' },\\n    archived: { label: \'已归档\', cls: \'tag-danger\' }\\n  };\\n\\n  function statusTag(status) {\\n    var s = PROJ_STATUS[status] || PROJ_STATUS.active;\\n    return \'<span class=\\\"tag \' + s.cls + \'\\\">\' + s.label + \'</span>\';\\n  }\\n\\n  function projTaskCount(pid) {\\n    var ts = getTodos().filter(function (t) { return t.projectId === pid; });\\n    var undone = ts.filter(function (t) { return !t.done; }).length;\\n    return { undone: undone, total: ts.length };\\n  }\\n\\n  function projCardHtml(p, archived) {\\n    var cnt = projTaskCount(p.id);\\n    var color = p.color || \'#b06f47\';\\n    var ini = (p.name || \'?\').trim().charAt(0) || \'?\';\\n    return \'<div class=\\\"work-proj-card glass-card\' + (archived ? \' is-archived\' : \'\') + \'\\\" data-id=\\\"\' + esc(p.id) + \'\\\" data-name=\\\"\' + esc(p.name || \'\') + \'\\\" data-desc=\\\"\' + esc(p.desc || \'\') + \'\\\">\' +\\n      \'<div class=\\\"work-proj-color\\\" style=\\\"background:\' + color + \'\\\">\' + esc(ini) + \'</div>\' +\\n      \'<div class=\\\"work-proj-main\\\">\' +\\n      \'<div class=\\\"work-proj-name\\\">\' + esc(p.name) +\\n      (archived ? \'<span class=\\\"tag tag-danger\\\">已归档</span>\' : statusTag(p.status)) +\\n      \'</div>\' +\\n      \'<div class=\\\"work-proj-desc\\\">\' + esc(p.desc || \'暂无描述\') + \'</div>\' +\\n      \'<div class=\\\"work-proj-meta\\\">\' +\\n      \'<span class=\\\"work-tag-color\\\" style=\\\"background:\' + color + \'1f;color:\' + color + \'\\\"><span class=\\\"work-tag-dot\\\" style=\\\"background:\' + color + \'\\\"></span>项目</span>\' +\\n      \'<span class=\\\"work-proj-count\\\">任务 \' + cnt.undone + \' / \' + cnt.total + \'</span>\' +\\n      \'<span class=\\\"muted\\\" style=\\\"font-size:0.76rem\\\">创建于 \' + (p.createdAt ? String(p.createdAt).slice(0, 10) : \'—\') + \'</span>\' +\\n      \'</div></div>\' +\\n      (archived\\n        ? \'<button type=\\\"button\\\" class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"restore\\\">恢复</button>\'\\n        : \'<span class=\\\"work-proj-grip\\\" draggable=\\\"true\\\" title=\\\"拖动排序\\\">\' + icon(\'grip\', \'\', 17) + \'</span>\') +\\n      \'</div>\';\\n  }\\n\\n  var workProjects = {\\n    title: \'项目备忘\',\\n    _kw: \'\',\\n    render: function () {\\n      if (!storeReady()) return \'<div class=\\\"empty-state\\\">数据层未就绪，请确认 store.js 与 app.js 已加载。</div>\';\\n      var all = sortProjects(getProjects());\\n      var kw = (this._kw || \'\').trim().toLowerCase();\\n      var active = all.filter(function (p) { return p.status !== \'archived\'; });\\n      var archived = all.filter(function (p) { return p.status === \'archived\'; });\\n      if (kw) {\\n        active = active.filter(function (p) {\\n          return (p.name || \'\').toLowerCase().indexOf(kw) >= 0 || (p.desc || \'\').toLowerCase().indexOf(kw) >= 0;\\n        });\\n        archived = archived.filter(function (p) {\\n          return (p.name || \'\').toLowerCase().indexOf(kw) >= 0 || (p.desc || \'\').toLowerCase().indexOf(kw) >= 0;\\n        });\\n      }\\n      return \'<div class=\\\"work-page\\\" data-page=\\\"work-projects\\\">\' +\\n        \'<div class=\\\"work-bar\\\">\' +\\n        \'<div class=\\\"search-box\\\" style=\\\"flex:1;max-width:380px;margin-bottom:0\\\">\' +\\n        \'<span class=\\\"search-icon\\\">\' + icon(\'search\', \'\', 17) + \'</span>\' +\\n        \'<input class=\\\"input\\\" data-act=\\\"search\\\" type=\\\"text\\\" placeholder=\\\"搜索项目名或描述…\\\" value=\\\"\' + esc(this._kw || \'\') + \'\\\" autocomplete=\\\"off\\\">\' +\\n        \'</div>\' +\\n        \'<button class=\\\"btn btn-primary\\\" data-act=\\\"new-proj\\\">\' + icon(\'plus\', \'\', 16) + \'新建项目</button>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"work-proj-list\\\">\' +\\n        (active.length ? active.map(function (p) { return projCardHtml(p, false); }).join(\'\') :\\n          \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'folder\', \'\', 34) + \'</div>\' +\\n          (kw ? \'没有匹配的项目\' : \'还没有项目，点击右上角新建\') + \'</div>\') +\\n        \'</div>\' +\\n        (archived.length ? \'<div class=\\\"work-archived-head\\\" data-act=\\\"arch-toggle\\\">\' +\\n          \'<span class=\\\"chev\\\">\' + icon(\'chevD\', \'\', 14) + \'</span>已归档项目（\' + archived.length + \'）</div>\' +\\n          \'<div class=\\\"work-proj-list\\\" data-arch=\\\"1\\\" style=\\\"display:none\\\">\' +\\n          archived.map(function (p) { return projCardHtml(p, true); }).join(\'\') +\\n          \'</div>\' : \'\') +\\n        \'</div>\';\\n    },\\n    mount: function (root) {\\n      if (!storeReady()) return;\\n      var el = root && root.nodeType === 1 ? root : document;\\n      var self = this;\\n      var press = null;\\n      var state = { dragId: null, orderHint: null };\\n\\n      function rerender() {\\n        var cur = $(\'[data-page=\\\"work-projects\\\"]\', el);\\n        if (!cur) return;\\n        var tmp = document.createElement(\'div\');\\n        tmp.innerHTML = self.render();\\n        var fresh = tmp.firstElementChild;\\n        cur.parentNode.replaceChild(fresh, cur);\\n        if (press) press.destroy();\\n        press = null;\\n        bindPress();\\n        bindSort();\\n      }\\n\\n      el.addEventListener(\'input\', function (e) {\\n        var inp = e.target.closest(\'[data-act=\\\"search\\\"]\');\\n        if (inp) {\\n          self._kw = inp.value;\\n          rerender();\\n        }\\n      });\\n\\n      el.addEventListener(\'click\', function (e) {\\n        var card = e.target.closest(\'.work-proj-card\');\\n        if (card && !e.target.closest(\'[data-act=\\\"restore\\\"]\') && !e.target.closest(\'.work-proj-grip\')) {\\n          nav(\'/work/projects/\' + encodeURIComponent(card.getAttribute(\'data-id\')));\\n          return;\\n        }\\n        var restore = e.target.closest(\'[data-act=\\\"restore\\\"]\');\\n        if (restore) {\\n          var rc = restore.closest(\'.work-proj-card\');\\n          store().projects.update(rc.getAttribute(\'data-id\'), { status: \'active\' });\\n          uiToast(\'已恢复为进行中\', \'success\');\\n          rerender();\\n          return;\\n        }\\n        var np = e.target.closest(\'[data-act=\\\"new-proj\\\"]\');\\n        if (np) { openProjectForm(null, rerender); return; }\\n        var at = e.target.closest(\'[data-act=\\\"arch-toggle\\\"]\');\\n        if (at) {\\n          var list = $(\'[data-arch=\\\"1\\\"]\', el);\\n          if (list) {\\n            var show = list.style.display === \'none\';\\n            list.style.display = show ? \'flex\' : \'none\';\\n            at.classList.toggle(\'open\', show);\\n          }\\n        }\\n      });\\n\\n      /* 长按：归档 / 删除 */\\n      function bindPress() {\\n        if (press) press.destroy();\\n        press = longPress(el, 520, function (e) {\\n          var card = e.target.closest(\'.work-proj-card\');\\n          if (!card || card.classList.contains(\'is-archived\')) return;\\n          var id = card.getAttribute(\'data-id\');\\n          var p = store().projects.get(id);\\n          if (!p) return;\\n          var rect = card.getBoundingClientRect();\\n          openMenu(rect.left + 40, rect.top + rect.height / 2, [\\n            { label: \'归档项目\', icon: \'archive\', onClick: function () {\\n              store().projects.update(id, { status: \'archived\' });\\n              uiToast(\'已归档\', \'success\');\\n              rerender();\\n            } },\\n            { label: \'删除项目\', icon: \'trash\', danger: true, onClick: function () {\\n              confirmModal(\'删除项目\', \'删除「\' + p.name + \'」将同时解除其下所有待办的项目关联，确定吗？\', function () {\\n                getTodos().forEach(function (t) {\\n                  if (t.projectId === id) store().todos.update(t.id, { projectId: \'\' });\\n                });\\n                store().projects.remove(id);\\n                uiToast(\'已删除\', \'success\');\\n                rerender();\\n              });\\n            } }\\n          ]);\\n        });\\n      }\\n\\n      /* 拖拽排序（手柄） */\\n      function bindSort() {\\n        $$(\'.work-proj-grip\', el).forEach(function (grip) {\\n          grip.addEventListener(\'dragstart\', function (e) {\\n            var card = grip.closest(\'.work-proj-card\');\\n            state.dragId = card.getAttribute(\'data-id\');\\n            e.dataTransfer.effectAllowed = \'move\';\\n            e.dataTransfer.setData(\'text/plain\', state.dragId);\\n            card.classList.add(\'dragging\');\\n            state.orderHint = document.createElement(\'div\');\\n            state.orderHint.className = \'work-proj-sort-hint\';\\n            document.body.appendChild(state.orderHint);\\n          });\\n          grip.addEventListener(\'dragend\', function (e) {\\n            var card = grip.closest(\'.work-proj-card\');\\n            if (card) card.classList.remove(\'dragging\');\\n            if (state.orderHint) { state.orderHint.remove(); state.orderHint = null; }\\n            if (state.dragId) {\\n              persistOrder();\\n              state.dragId = null;\\n            }\\n          });\\n        });\\n        $$(\'.work-proj-card\', el).forEach(function (card) {\\n          card.addEventListener(\'dragover\', function (e) {\\n            if (!state.dragId) return;\\n            e.preventDefault();\\n            e.dataTransfer.dropEffect = \'move\';\\n            if (state.orderHint) {\\n              var r = card.getBoundingClientRect();\\n              state.orderHint.style.left = r.left + \'px\';\\n              state.orderHint.style.width = r.width + \'px\';\\n              state.orderHint.style.top = (r.top + (e.clientY > r.top + r.height / 2 ? r.height - 6 : -6)) + \'px\';\\n              state.orderHint.style.height = \'12px\';\\n            }\\n          });\\n          card.addEventListener(\'drop\', function (e) {\\n            if (!state.dragId || state.dragId === card.getAttribute(\'data-id\')) return;\\n            e.preventDefault();\\n            e.stopPropagation();\\n            var list = sortProjects(getProjects()).filter(function (p) { return p.status !== \'archived\'; });\\n            var from = list.findIndex(function (p) { return p.id === state.dragId; });\\n            var to = list.findIndex(function (p) { return p.id === card.getAttribute(\'data-id\'); });\\n            if (from < 0 || to < 0) return;\\n            var r = card.getBoundingClientRect();\\n            if (e.clientY > r.top + r.height / 2) to += 1;\\n            list.splice(from, 1);\\n            if (to > from) to -= 1;\\n            list.splice(Math.max(0, to), 0, store().projects.get(state.dragId));\\n            list.forEach(function (p, i) { store().projects.update(p.id, { sort: i }); });\\n            uiToast(\'已调整排序\', \'success\');\\n            rerender();\\n          });\\n        });\\n      }\\n\\n      function persistOrder() {\\n        var ids = $$(\'.work-proj-card:not(.is-archived)\', el).map(function (c) { return c.getAttribute(\'data-id\'); });\\n        ids.forEach(function (id, i) { store().projects.update(id, { sort: i }); });\\n      }\\n\\n      bindPress();\\n      bindSort();\\n\\n      this._cleanup = function () {\\n        if (press) press.destroy();\\n        if (state.orderHint) state.orderHint.remove();\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  /* 新建项目表单 */\\n  function openProjectForm(proj, after) {\\n    var p = proj || {};\\n    var color = p.color || PROJ_COLORS[0];\\n    var html = \'<form data-form=\\\"proj\\\">\' +\\n      \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">项目名</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"name\\\" type=\\\"text\\\" value=\\\"\' + esc(p.name || \'\') + \'\\\" placeholder=\\\"项目名称\\\" autocomplete=\\\"off\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>描述</label>\' +\\n      \'<textarea class=\\\"textarea\\\" data-f=\\\"desc\\\" placeholder=\\\"一句话描述（选填）\\\" style=\\\"min-height:64px\\\">\' + esc(p.desc || \'\') + \'</textarea></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>颜色标签</label><div class=\\\"work-color-row\\\">\' +\\n      PROJ_COLORS.map(function (c) {\\n        return \'<span class=\\\"work-color-dot\' + (c === color ? \' active\' : \'\') + \'\\\" data-color=\\\"\' + c + \'\\\" style=\\\"background:\' + c + \'\\\"></span>\';\\n      }).join(\'\') +\\n      \'</div></div>\' +\\n      (p.id ? \'<div class=\\\"work-form-row\\\"><label>状态</label><select class=\\\"select\\\" data-f=\\\"status\\\">\' +\\n        \'<option value=\\\"active\\\"\' + (p.status === \'active\' ? \' selected\' : \'\') + \'>进行中</option>\' +\\n        \'<option value=\\\"paused\\\"\' + (p.status === \'paused\' ? \' selected\' : \'\') + \'>暂停</option>\' +\\n        \'<option value=\\\"done\\\"\' + (p.status === \'done\' ? \' selected\' : \'\') + \'>已完结</option>\' +\\n        \'<option value=\\\"archived\\\"\' + (p.status === \'archived\' ? \' selected\' : \'\') + \'>已归档</option>\' +\\n        \'</select></div>\' : \'\') +\\n      \'</form>\';\\n    var m = openModal({\\n      title: p.id ? \'编辑项目\' : \'新建项目\',\\n      content: html,\\n      okText: p.id ? \'保存\' : \'创建\',\\n      onOk: function (modal) {\\n        var name = $(\'[data-f=\\\"name\\\"]\', modal).value.trim();\\n        if (!name) { uiToast(\'项目名不能为空\', \'warn\'); return false; }\\n        var picked = $(\'.work-color-dot.active\', modal);\\n        var patch = {\\n          name: name,\\n          desc: $(\'[data-f=\\\"desc\\\"]\', modal).value.trim(),\\n          color: picked ? picked.getAttribute(\'data-color\') : color\\n        };\\n        if (p.id) {\\n          patch.status = $(\'[data-f=\\\"status\\\"]\', modal).value;\\n          store().projects.update(p.id, patch);\\n          uiToast(\'已保存\', \'success\');\\n        } else {\\n          patch.status = \'active\';\\n          store().projects.add(patch);\\n          uiToast(\'已创建项目\', \'success\');\\n        }\\n        if (after) after();\\n        return true;\\n      }\\n    });\\n    /* 颜色选择 */\\n    setTimeout(function () {\\n      $$(\'.work-color-dot\', m.el).forEach(function (dot) {\\n        dot.addEventListener(\'click\', function () {\\n          $$(\'.work-color-dot\', m.el).forEach(function (d) { d.classList.remove(\'active\'); });\\n          dot.classList.add(\'active\');\\n        });\\n      });\\n    }, 20);\\n  }\\n\\n  /*__MORE__*/\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 13:19:26'),
