city:.55}\\n.st-form-row{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}\\n.st-form-row label{font-size:0.82rem;color:var(--text-2);font-weight:600}\\n.st-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\\n.st-form-hint{font-size:0.78rem;color:var(--text-3);margin-top:4px;line-height:1.7}\\n.st-mastery-opt{display:flex;align-items:center;gap:12px;padding:12px 14px;border:1px solid var(--border);border-radius:12px;margin-bottom:8px;cursor:pointer;transition:all var(--t-med) var(--ease);background:var(--card)}\\n.st-mastery-opt:hover{border-color:var(--accent)}\\n.st-mastery-opt input{accent-color:var(--accent);width:16px;height:16px;flex-shrink:0}\\n.st-mastery-opt .dot{width:12px;height:12px;border-radius:50%;flex-shrink:0}\\n.st-mastery-opt .nm{font-weight:650;min-width:52px}\\n.st-mastery-opt .ds{font-size:0.82rem;color:var(--text-3)}\\n.st-mastery-opt.sel{border-color:var(--accent);background:var(--accent-soft)}\\n.st-page-fade{animation:st-rise 280ms var(--ease)}\\n@media (max-width:1000px){\\n  .st-entry-grid{grid-template-columns:repeat(2,1fr)}\\n  .st-stats{grid-template-columns:1fr}\\n  .st-wrong-stats{grid-template-columns:repeat(2,1fr)}\\n  .st-tree-layout{flex-direction:column}\\n  .st-tree-pane{width:100%;max-height:280px;position:static}\\n  .st-form-grid{grid-template-columns:1fr}\\n}\\n@media (max-width:640px){.st-entry-grid{grid-template-columns:1fr}}\\n`;\\n      (document.head || document.documentElement).appendChild(st);\\n    } catch (e) { /* 极端环境下样式注入失败不影响功能 */ }\\n  })();\\n\\n  /* ================================================================\\n     1. 考公区总览  /study\\n     ================================================================ */\\n\\n  function overviewStats() {\\n    var wk = weekRange();\\n    var today = todayStr();\\n    var checkins = App.store.checkins.list();\\n    var weekMin = checkins.filter(function (c) {\\n      return c.date && c.date >= wk.start && c.date <= wk.end;\\n    }).reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n    var todayMin = checkins.filter(function (c) { return c.date === today; })\\n      .reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n\\n    // 连续打卡天数\\n    var byDate = {};\\n    checkins.forEach(function (c) { if (c.date && (Number(c.durationMin) || 0) > 0) byDate[c.date] = true; });\\n    var d = new Date();\\n    if (!byDate[dateStr(d)]) d.setDate(d.getDate() - 1);\\n    var streak = 0;\\n    while (byDate[dateStr(d)]) { streak++; d.setDate(d.getDate() - 1); }\\n\\n    // 计划完成率：进行中计划进度均值\\n    var plans = App.store.plans.list().filter(function (p) { return p.status !== \'done\'; });\\n    var rate = plans.length\\n      ? Math.round(plans.reduce(function (s, p) { return s + (Number(p.progress) || 0); }, 0) / plans.length)\\n      : 0;\\n\\n    // 错题待复习\\n    var wrongs = App.store.wrongQuestions.list();\\n    var pending = wrongs.filter(function (w) { return w.status === \'pending\'; }).length;\\n\\n    return {\\n      weekMin: weekMin, streak: streak, rate: rate,\\n      todayMin: todayMin,\\n      knowledge: App.store.knowledge.count(),\\n      questions: App.store.questions.count(),\\n      wrongPending: pending,\\n      activePlans: plans.length,\\n      szMonth: App.store.shizheng.list().filter(function (s) {\\n        return s.date && s.date.slice(0, 7) === today.slice(0, 7);\\n      }).length\\n    };\\n  }\\n\\n  var OVERVIEW_DEF = {\\n    title: \'考公区\',\\n    render: function () {\\n      var s = overviewStats();\\n      var entries = [\\n        { nav: \'/study/knowledge\', ic: \'book\', name: \'知识点树\', sum: \'已收录 \' + s.knowledge + \' 个知识点\', roll: \'st-roll-kn\' },\\n        { nav: \'/study/questions\', ic: \'question\', name: \'题库\', sum: \'题库共 \' + s.questions + \' 道题目\', roll: \'st-roll-q\' },\\n        { nav: \'/study/wrong\', ic: \'wrong\', name: \'错题本\', sum: \'今日待复习：\' + s.wrongPending + \' 题\', roll: \'st-roll-w\' },\\n        { nav: \'/study/plan\', ic: \'plan\', name: \'学习计划\', sum: s.activePlans + \' 个计划进行中\', roll: \'st-roll-p\' },\\n        { nav: \'/study/clock\', ic: \'clock\', name: \'学习打卡\', sum: s.todayMin > 0 ? \'今日已学 \' + fmtHM(s.todayMin) : \'今日尚未打卡\' },\\n        { nav: \'/study/current\', ic: \'shizheng\', name: \'时政积累\', sum: \'本月已积累 \' + s.szMonth + \' 条\', roll: \'st-roll-sz\' }\\n      ];\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\"><h2>考公区</h2><p class=\\\"page-desc\\\">学习概况与六大功能入口</p></div>\\n  <div class=\\\"st-stats\\\">\\n    <div class=\\\"glass-card st-stat-card\\\">\\n      <span class=\\\"st-stat-label\\\">本周累计时长</span>\\n      <div class=\\\"st-stat-num\\\"><span class=\\\"st-roll\\\" data-target=\\\"${Math.round(s.weekMin / 60 * 10) / 10}\\\" data-val=\\\"0\\\">0</span><span class=\\\"st-stat-unit\\\">小时</span></div>\\n      <span class=\\\"st-stat-sub\\\">共 ${s.weekMin} 分钟</span>\\n    </div>\\n    <div class=\\\"glass-card st-stat-card\\\">\\n      <span class=\\\"st-stat-label\\\">连续打卡天数</span>\\n      <div class=\\\"st-stat-num\\\"><span class=\\\"st-roll\\\" data-target=\\\"${s.streak}\\\" data-val=\\\"0\\\">0</span><span class=\\\"st-stat-unit\\\">天</span></div>\\n      <span class=\\\"st-stat-sub\\\">坚持就是胜利</span>\\n    </div>\\n    <div class=\\\"glass-card st-stat-card\\\">\\n      <span class=\\\"st-stat-label\\\">计划完成率</span>\\n      <div class=\\\"st-stat-num\\\"><span class=\\\"st-roll\\\" data-target=\\\"${s.rate}\\\" data-val=\\\"0\\\">0</span><span class=\\\"st-stat-unit\\\">%</span></div>\\n      <span class=\\\"st-stat-sub\\\">${s.activePlans} 个进行中计划</span>\\n    </div>\\n  </div>\\n  <div class=\\\"st-entry-grid\\\">\\n    ${entries.map(function (e) {\\n      return `<div class=\\\"glass-card st-entry-card\\\" data-nav=\\\"${e.nav}\\\">\\n        <span class=\\\"st-entry-icon\\\">${icon(e.ic, 22)}</span>\\n        <div style=\\\"min-width:0\\\">\\n          <div class=\\\"st-entry-name\\\">${e.name}</div>\\n          <div class=\\\"st-entry-summary\\\">${e.sum}</div>\\n        </div>\\n        <span class=\\\"st-entry-arrow\\\">${icon(\'chevron\', 16)}</span>\\n      </div>`;\\n    }).join(\'\')}\\n  </div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      // 数字滚动动画：从 0 滚到目标\\n      el.querySelectorAll(\'.st-roll[data-target]\').forEach(function (r) {\\n        setRoll(r, r.getAttribute(\'data-target\'));\\n      });\\n      // 数据变更时实时刷新\\n      var unsub = App.store.subscribe(function () {\\n        var s = overviewStats();\\n        el.querySelectorAll(\'.st-roll[data-target]\').forEach(function (r) {\\n          var key = r.getAttribute(\'data-roll-key\');\\n          var v = key === \'week\' ? Math.round(s.weekMin / 60 * 10) / 10\\n            : key === \'streak\' ? s.streak : s.rate;\\n          setRoll(r, v);\\n        });\\n      });\\n      el._unsub = unsub;\\n      el.addEventListener(\'click\', function (e) {\\n        var nav = e.target.closest(\'[data-nav]\');\\n        if (nav) { e.preventDefault(); App.navigate(nav.dataset.nav); }\\n      });\\n    },\\n    unmount: function () {\\n      var el = document.getElementById(\'content\');\\n      if (el && el._unsub) { el._unsub(); el._unsub = null; }\\n    }\\n  };\\n\\n  /* ================================================================\\n     2. 知识点树  /study/knowledge\\n     ================================================================ */\\n\\n  function treeState() {\\n    var ui = getUI().knowledgeTree || {};\\n    return {\\n      selected: ui.selected || [\'行测\'],\\n      expanded: ui.expanded || { \'行测\': true, \'行测/判断推理\': true }\\n    };\\n  }\\n\\n  function nodeHTML(node, segs, expanded, selectedKey) {\\n    var key = segs.join(\'/\');\\n    var open = !!expanded[key];\\n    var kids = node.children || [];\\n    var arrow = kids.length\\n      ? \'<button class=\\\"st-node-arrow\\\" data-toggle=\\\"\' + key + \'\\\" title=\\\"展开 / 折叠\\\">\' + icon(\'chevron\', 14) + \'</button>\'\\n      : \'<span class=\\\"st-node-arrow leaf\\\"></span>\';\\n    var kidsHtml = kids.length\\n      ? \'<div class=\\\"st-node-children\\\"><div class=\\\"st-node-inner\\\">\' +\\n        kids.map(function (k) { return nodeHTML(k, segs.concat(k.name), expanded, selectedKey); }).join(\'\') +\\n        \'</div></div>\'\\n      : \'\';\\n    return `<div class=\\\"st-node${open ? \' open\' : \'\'}\\\" data-key=\\\"${key}\\\">\\n      <button class=\\\"st-node-row${selectedKey === key ? \' selected\' : \'\'}\\\" data-select=\\\"${key}\\\">\\n        ${arrow}<span class=\\\"st-node-name\\\">${esc(node.name)}</span>\\n        <span class=\\\"st-node-count\\\">${knowledgeCount(segs)}</span>\\n      </button>${kidsHtml}\\n    </div>`;\\n  }\\n\\n  function treeHTML(ts) {\\n    return \'<div class=\\\"st-tree\\\">\' +\\n      KNOWLEDGE_TREE.map(function (n) { return nodeHTML(n, [n.name], ts.expanded, ts.selected.join(\'/\')); }).join(\'\') +\\n      \'</div>\';\\n  }\\n\\n  function knCardHTML(k) {\\n    var m = Math.min(5, Math.max(1, Number(k.mastery) || 1));\\n    var segs = \'\';\\n    for (var i = 0; i < 5; i++) {\\n      segs += \'<i\' + (i < m ? \' style=\\\"background:\' + MASTERY_COLORS[m - 1] + \'\\\"\' : \'\') + \'></i>\';\\n    }\\n    return `<div class=\\\"glass-card st-kn-card\\\" data-open=\\\"${esc(k.id)}\\\">\\n      <div class=\\\"st-kn-title\\\">${esc(k.title)}</div>\\n      <div class=\\\"st-kn-path\\\">${esc(k.path || \'\')}</div>\\n      <div class=\\\"st-mastery\\\">\\n        <span class=\\\"st-mastery-name\\\">${MASTERY_NAMES[m - 1]}</span>\\n        <div class=\\\"st-mastery-seg\\\">${segs}</div>\\n      </div>\\n      <div class=\\\"st-kn-meta\\\">\\n        <span>${icon(\'clock\', 13)} 下次复习：${fmtDue(k.reviewDate)}</span>\\n        <span>${icon(\'question\', 13)} 关联题目 ${Number(k.questionCount) || 0} 题</span>\\n      </div>\\n    </div>`;\\n  }\\n\\n  var TREE_DEF = {\\n    title: \'知识点树\',\\n    render: function () {\\n      var ts = treeState();\\n      var list = knowledgeForNode(ts.selected);\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\">\\n    <h2>知识点树</h2>\\n    <p class=\\\"page-desc\\\">按科目与模块梳理知识点，掌握程度与复习节奏一目了然</p>\\n  </div>\\n  <div class=\\\"search-box\\\">\\n    <span class=\\\"search-icon\\\">${icon(\'search\', 18)}</span>\\n    <input type=\\\"text\\\" class=\\\"input\\\" id=\\\"st-kn-search\\\" placeholder=\\\"全局检索知识点（标题 / 路径 / 内容）…\\\" autocomplete=\\\"off\\\">\\n  </div>\\n  <div class=\\\"st-tree-layout\\\">\\n    <aside class=\\\"glass-card st-tree-pane\\\" id=\\\"st-tree-pane\\\">${treeHTML(ts)}</aside>\\n    <section class=\\\"st-tree-list\\\" id=\\\"st-tree-list\\\">\\n      <div class=\\\"st-list-title\\\" id=\\\"st-list-title\\\">${esc(ts.selected.join(\' › \'))} · ${list.length} 个知识点</div>\\n      ${list.length ? list.map(knCardHTML).join(\'\') : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'book\', 34) + \'</div><p>该模块暂无知识点，点击卡片可查看详情</p></div>\'}\\n    </section>\\n  </div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var treePane = el.querySelector(\'#st-tree-pane\');\\n      var listBox = el.querySelector(\'#st-tree-list\');\\n      var titleEl = el.querySelector(\'#st-list-title\');\\n      var search = el.querySelector(\'#st-kn-search\');\\n      var debounce = null;\\n\\n      function refreshTree() {\\n        var ts = treeState();\\n        treePane.innerHTML = treeHTML(ts);\\n      }\\n      function refreshList() {\\n        var ts = treeState();\\n        var kw = search.value.trim();\\n        var items;\\n        if (kw) {\\n          items = App.store.knowledge.list().filter(function (k) {\\n            var hay = (k.title + \' \' + (k.path || \'\') + \' \' + (k.content || \'\')).toLowerCase();\\n            return hay.indexOf(kw.toLowerCase()) >= 0;\\n          });\\n          titleEl.textContent = \'检索「\' + kw + 」\'的 \' + items.length + \' 个结果\';\\n        } else {\\n          items = knowledgeForNode(ts.selected);\\n          titleEl.textContent = ts.selected.join(\' › \') + \' · \' + items.length + \' 个知识点\';\\n        }\\n        listBox.innerHTML = items.length\\n          ? items.map(knCardHTML).join(\'\')\\n          : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'book\', 34) + \'</div><p>\' + (kw ? \'没有匹配的知识点\' : \'该模块暂无知识点\') + \'</p></div>\';\\n      }\\n\\n      treePane.addEventListener(\'click\', function (e) {\\n        var tog = e.target.closest(\'[data-toggle]\');\\n        if (tog) {\\n          e.stopPropagation();\\n          var ts = treeState();\\n          ts.expanded[tog.dataset.toggle] = !ts.expanded[tog.dataset.toggle];\\n          setUI({ knowledgeTree: { selected: ts.selected, expanded: ts.expanded } });\\n          refreshTree();\\n          return;\\n        }\\n        var sel = e.target.closest(\'[data-select]\');\\n        if (sel) {\\n          var key = sel.dataset.select.split(\'/\');\\n          var ts2 = treeState();\\n          ts2.selected = key;\\n          setUI({ knowledgeTree: { selected: key, expanded: ts2.expanded } });\\n          refreshTree();\\n          refreshList();\\n        }\\n      });\\n\\n      listBox.addEventListener(\'click\', function (e) {\\n        var card = e.target.closest(\'[data-open]\');\\n        if (card) openKnowledge(card.dataset.open);\\n      });\\n\\n      search.addEventListener(\'input\', function () {\\n        clearTimeout(debounce);\\n        debounce = setTimeout(refreshList, 250);\\n      });\\n\\n      // 知识点掌握度变化后刷新列表（跨页返回时也由 mount 重新渲染）\\n      var unsub = App.store.subscribe(function () { refreshList(); });\\n      el._unsub = unsub;\\n    },\\n    unmount: function () {\\n      var el = document.getElementById(\'content\');\\n      if (el && el._unsub) { el._unsub(); el._unsub = null; }\\n    }\\n  };\\n\\n  /* ================================================================\\n     3. 知识点详情  /study/knowledge/:id（动态 id）\\n     ================================================================ */\\n\\n  function detailIdFromPath(path) {\\n    var seg = String(path || \'\').split(\'/\');\\n    return decodeURIComponent(seg[seg.length - 1] || \'\');\\n  }\\n\\n  function relatedQuestions(k) {\\n    var segs = pathSegs(k);\\n    return App.store.questions.list().filter(function (q) {\\n      if (segs.indexOf(q.module) >= 0) return true;\\n      return (q.tags || []).some(function (t) { return segs.indexOf(t) >= 0; });\\n    });\\n  }\\n\\n  var DETAIL_DEF = {\\n    title: \'知识点详情\',\\n    render: function (path) {\\n      var id = detailIdFromPath(path);\\n      var k = App.store.knowledge.get(id);\\n      if (!k) {\\n        return `\\n<div class=\\\"page st-page\\\">\\n  <div class=\\\"empty-state\\\">\\n    <div class=\\\"empty-icon\\\">${icon(\'book\', 34)}</div>\\n    <p>未找到该知识点（id：${esc(id)}）</p>\\n    <button class=\\\"btn btn-primary\\\" data-nav=\\\"/study/knowledge\\\" style=\\\"margin-top:14px\\\">${icon(\'book\', 16)}返回知识点树</button>\\n  </div>\\n</div>`;\\n      }\\n      var m = Math.min(5, Math.max(1, Number(k.mastery) || 1));\\n      var crumbs = pathSegs(k).concat(k.title);\\n      var rel = relatedQuestions(k);\\n      var common = k.commonPoints || [\\n        \'理解并记住「\' + k.title + \'」的核心结论与方法步骤\',\\n        \'做题时先判断题型，再套用对应方法，避免生搬硬套\',\\n        \'结合历年真题熟悉常见变形与命题角度\'\\n      ];\\n      var pitfalls = k.pitfalls || [\\n        \'只看表面特征，忽略题目中的限定条件\',\\n        \'推理或计算过程跳步，导致结论偏差\',\\n        \'复习间隔过长导致遗忘，需按计划及时回顾\'\\n      ];\\n      return `\\n<div class=\\\"page st-page\\\" id=\\\"st-detail-root\\\">\\n  <div class=\\\"st-detail-head\\\">\\n    <button class=\\\"btn btn-ghost btn-sm\\\" data-nav=\\\"/study/knowledge\\\">${icon(\'chevron\', 14)} 返回</button>\\n    <div class=\\\"st-breadcrumb\\\">\\n      <span>考公区</span><span class=\\\"sep\\\">›</span><span>知识点树</span>\\n      ${crumbs.map(function (c, i) {\\n        return \'<span class=\\\"sep\\\">›</span><span class=\\\"\' + (i === crumbs.length - 1 ? \'cur\' : \'\') + \'\\\">\' + esc(c) + \'</span>\';\\n      }).join(\'\')}\\n    </div>\\n    <button class=\\\"btn btn-ghost btn-sm\\\" id=\\\"st-reading-btn\\\" style=\\\"margin-left:auto\\\">${icon(\'panel\', 14)} 全屏阅读</button>\\n  </div>\\n\\n  <h2 class=\\\"st-detail-title\\\">${esc(k.title)}</h2>\\n  <div class=\\\"st-detail-meta\\\">\\n    <span class=\\\"tag tag-accent\\\">${MASTERY_NAMES[m - 1]}</span>\\n    <span class=\\\"tag\\\">下次复习 ${fmtYMD(k.reviewDate)}</span>\\n    <span class=\\\"tag\\\">关联题目 ${rel.length} 题</span>\\n  </div>\\n\\n  <section class=\\\"glass-card\\\" style=\\\"padding:22px 24px\\\">\\n    <div class=\\\"st-detail-body\\\">${renderRich(k.content)}</div>\\n  </section>\\n\\n  <div class=\\\"collapse st-detail-collapse\\\" id=\\\"st-coll-common\\\">\\n    <div class=\\\"collapse-head\\\" data-collapse=\\\"st-coll-common\\\"><span>常见考法</span><span class=\\\"chevron\\\">${icon(\'chevron\', 16)}</span></div>\\n    <div class=\\\"collapse-body\\\"><div class=\\\"collapse-inner\\\"><div class=\\\"collapse-content\\\"><ul>${common.map(function (x) { return \'<li>\' + esc(x) + \'</li>\'; }).join(\'\')}</ul></div></div></div>\\n  </div>\\n  <div class=\\\"collapse st-detail-collapse\\\" id=\\\"st-coll-pit\\\">\\n    <div class=\\\"collapse-head\\\" data-collapse=\\\"st-coll-pit\\\"><span>易错点</span><span class=\\\"chevron\\\">${icon(\'chevron\', 16)}</span></div>\\n    <div class=\\\"collapse-body\\\"><div class=\\\"collapse-inner\\\"><div class=\\\"collapse-content\\\"><ul>${pitfalls.map(function (x) { return \'<li>\' + esc(x) + \'</li>\'; }).join(\'\')}</ul></div></div></div>\\n  </div>\\n\\n  <div class=\\\"st-info-bar\\\">\\n    <div class=\\\"st-info-item\\\">\\n      <span class=\\\"st-info-label\\\">掌握程度</span>\\n      <span class=\\\"st-info-value\\\"><button class=\\\"st-mastery-pill\\\" id=\\\"st-mastery-pill\\\" style=\\\"background:${MASTERY_COLORS[m - 1]}\\\" data-id=\\\"${esc(k.id)}\\\">${MASTERY_NAMES[m - 1]}</button></span>\\n    </div>\\n    <div class=\\\"st-info-item\\\">\\n      <span class=\\\"st-info-label\\\">下次复习日期（艾宾浩斯）</span>\\n      <span class=\\\"st-info-value\\\" id=\\\"st-review-date\\\">${fmtYMD(k.reviewDate)}</span>\\n    </div>\\n    <div class=\\\"st-info-item\\\" style=\\\"flex:1;min-width:220px\\\">\\n      <span class=\\\"st-info-label\\\">关联题目（点击跳转题库定位）</span>\\n      <div class=\\\"st-rel-list\\\" id=\\\"st-rel-list\\\" style=\\\"max-height:150px;overflow-y:auto\\\">\\n        ${rel.length ? rel.map(function (q) {\\n          return `<div class=\\\"st-rel-q\\\" data-qid=\\\"${esc(q.id)}\\\">${icon(\'question\', 14)}<span class=\\\"t\\\">${esc(q.stem)}</span><span class=\\\"tag\\\">${esc(q.module || \'未分类\')}</span></div>`;\\n        }).join(\'\') : \'<span class=\\\"muted\\\" style=\\\"font-size:0.85rem\\\">暂无关联题目</span>\'}\\n      </div>\\n    </div>\\n  </div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var id = el.querySelector(\'#st-mastery-pill\') ? el.querySelector(\'#st-mastery-pill\').dataset.id : detailIdFromPath(location.hash);\\n\\n      // 折叠区块\\n      el.addEventListener(\'click\', function (e) {\\n        var head = e.target.closest(\'[data-collapse]\');\\n        if (head) {\\n          var box = el.querySelector(\'#\' + head.dataset.collapse);\\n          if (box) box.classList.toggle(\'open\');\\n          return;\\n        }\\n        var nav = e.target.closest(\'[data-nav]\');\\n        if (nav) { e.preventDefault(); App.navigate(nav.dataset.nav); return; }\\n        var rel = e.target.closest(\'[data-qid]\');\\n        if (rel) openQuestion(rel.dataset.qid);\\n      });\\n\\n      // 掌握程度五级选择\\n      var pill = el.querySelector(\'#st-mastery-pill\');\\n      if (pill && id) {\\n        pill.addEventListener(\'click\', function () {\\n          var k = App.store.knowledge.get(id);\\n          if (!k) return;\\n          var opts = MASTERY_NAMES.map(function (n, i) {\\n            var cur = Math.min(5, Math.max(1, Number(k.mastery) || 1));\\n            return `<label class=\\\"st-mastery-opt${i + 1 === cur ? \' sel\' : \'\'}\\\">\\n              <input type=\\\"radio\\\" name=\\\"mastery\\\" value=\\\"${i + 1}\\\"${i + 1 === cur ? \' checked\' : \'\'}>\\n              <span class=\\\"dot\\\" style=\\\"background:${MASTERY_COLORS[i]}\\\"></span>\\n              <span class=\\\"nm\\\">${n}</span><span class=\\\"ds\\\">${MASTERY_HINTS[i]}</span>\\n            </label>`;\\n          }).join(\'\');\\n          var mask = App.openModal(\'<div>\' + opts + \'</div>\', {\\n            title: \'调整掌握程度\',\\n            confirmText: \'保存\',\\n            cancelText: \'取消\',\\n            onConfirm: function (close) {\\n              var checked = mask.querySelector(\'input[name=\\\"mastery\\\"]:checked\');\\n              if (!checked) return;\\n              var level = Number(checked.value);\\n              var reviewDate = reviewDateForLevel(level);\\n              App.store.knowledge.update(id, { mastery: level, reviewDate: reviewDate });\\n              // 更新页面内展示\\n              pill.style.background = MASTERY_COLORS[level - 1];\\n              pill.textContent = MASTERY_NAMES[level - 1];\\n              var rd = el.querySelector(\'#st-review-date\');\\n              if (rd) rd.textContent = fmtYMD(reviewDate);\\n              close();\\n              App.showToast(\'掌握程度已更新为「\' + MASTERY_NAMES[level - 1] + \'」，下次复习 \' + fmtMD(reviewDate), \'success\');\\n            }\\n          });\\n          mask.querySelectorAll(\'.st-mastery-opt\').forEach(function (opt) {\\n            opt.addEventListener(\'click\', function () {\\n              mask.querySelectorAll(\'.st-mastery-opt\').forEach(function (o) { o.classList.remove(\'sel\'); });\\n              opt.classList.add(\'sel\');\\n              opt.querySelector(\'input\').checked = true;\\n            });\\n          });\\n        });\\n      }\\n\\n      // 全屏阅读：隐藏侧边栏\\n      var readBtn = el.querySelector(\'#st-reading-btn\');\\n      var onKey = function (e) {\\n        if (e.key === \'Escape\' && document.body.classList.contains(\'st-reading\')) exitReading();\\n      };\\n      function enterReading() {\\n        document.body.classList.add(\'st-reading\');\\n        readBtn.innerHTML = icon(\'panel\', 14) + \' 退出全屏\';\\n        App.showToast(\'已进入全屏阅读模式\', \'info\');\\n      }\\n      function exitReading() {\\n        document.body.classList.remove(\'st-reading\');\\n        if (readBtn) readBtn.innerHTML = icon(\'panel\', 14) + \' 全屏阅读\';\\n      }\\n      if (readBtn) {\\n        readBtn.addEventListener(\'click\', function () {\\n          if (document.body.classList.contains(\'st-reading\')) exitReading(); else enterReading();\\n        });\\n      }\\n      document.addEventListener(\'keydown\', onKey);\\n      el._onKey = onKey;\\n      el._exitReading = exitReading;\\n    },\\n    unmount: function () {\\n      var el = document.getElementById(\'content\');\\n      if (el && el._onKey) { document.removeEventListener(\'keydown\', el._onKey); el._onKey = null; }\\n      if (el && el._exitReading) el._exitReading();\\n      document.body.classList.remove(\'st-reading\');\\n    }\\n  };\\n\\n  /** 打开知识点详情（动态 id：先注册精确路由再跳转，支持直接改 hash 进入） */\\n  function openKnowledge(id) {\\n    var k = App.store.knowledge.get(id);\\n    if (!k) { App.showToast(\'知识点不存在\', \'warn\'); return; }\\n    var p = \'/study/knowledge/\' + encodeURIComponent(id);\\n    try { App.registerPage(p, DETAIL_DEF); } catch (e) { /* 忽略 */ }\\n    App.navigate(p);\\n  }\\n\\n  /** 为所有已有知识点注册精确详情路由（直接改 hash 也能进入） */\\n  function ensureKnowledgeRoutes() {\\n    try {\\n      App.store.knowledge.list().forEach(function (k) {\\n        App.registerPage(\'/study/knowledge/\' + encodeURIComponent(k.id), DETAIL_DEF);\\n      });\\n    } catch (e) { /* 忽略 */ }\\n  }\\n\\n  /* ================================================================\\n     4. 题库  /study/questions\\n     ================================================================ */\\n\\n  var pendingFocus = \'\'; // 待定位题目 id（跨页跳转用）\\n\\n  function openQuestion(qid) {\\n    pendingFocus = qid;\\n    App.navigate(\'/study/questions\');\\n  }\\n\\n  var QUESTIONS_DEF = {\\n    title: \'题库\',\\n    render: function () {\\n      var questions = App.store.questions.list();\\n      var modules = [\'全部模块\'].concat(ALL_MODULES.filter(function (m) {\\n        return questions.some(function (q) { return q.module === m; });\\n      }));\\n      if (modules.length === 1 && questions.length) modules.push(\'未分类\');\\n      var tags = [\'全部标签\'];\\n      questions.forEach(function (q) { (q.tags || []).forEach(function (t) { if (tags.indexOf(t) < 0) tags.push(t); }); });\\n      var sources = [\'全部来源\'];\\n      questions.forEach(function (q) { if (q.source && sources.indexOf(q.source) < 0) sources.push(q.source); });\\n\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\" style=\\\"display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap\\\">\\n    <div>\\n      <h2>题库</h2>\\n      <p class=\\\"page-desc\\\">共 ${questions.length} 道题目 · 点击卡片展开完整内容</p>\\n    </div>\\n    <button class=\\\"btn btn-primary\\\" id=\\\"st-q-add\\\">${icon(\'plus\', 16)} 录入题目</button>\\n  </div>\\n  <div class=\\\"st-filter-bar\\\">\\n    <select class=\\\"select\\\" id=\\\"st-q-module\\\">${modules.map(function (m) { return \'<option value=\\\"\' + esc(m) + \'\\\">\' + esc(m) + \'</option>\'; }).join(\'\')}</select>\\n    <select class=\\\"select\\\" id=\\\"st-q-tag\\\">${tags.map(function (t) { return \'<option value=\\\"\' + esc(t) + \'\\\">\' + esc(t) + \'</option>\'; }).join(\'\')}</select>\\n    <select class=\\\"select\\\" id=\\\"st-q-source\\\">${sources.map(function (s) { return \'<option value=\\\"\' + esc(s) + \'\\\">\' + esc(s) + \'</option>\'; }).join(\'\')}</select>\\n    <div class=\\\"search-box\\\" style=\\\"margin:0;flex:1;min-width:200px\\\">\\n      <span class=\\\"search-icon\\\">${icon(\'search\', 16)}</span>\\n      <input type=\\\"text\\\" class=\\\"input\\\" id=\\\"st-q-search\\\" placeholder=\\\"搜索题干 / 解析…\\\" autocomplete=\\\"off\\\" style=\\\"padding-left:38px\\\">\\n    </div>\\n  </div>\\n  <div class=\\\"st-q-list\\\" id=\\\"st-q-list\\\"></div>\\n  <div class=\\\"st-import-bar\\\">\\n    <button class=\\\"btn btn-ghost\\\" id=\\\"st-q-import\\\">${icon(\'upload\', 16)} 批量导入题目（文本粘贴）</button>\\n  </div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var listBox = el.querySelector(\'#st-q-list\');\\n      var focusId = pendingFocus; pendingFocus = \'\';\\n\\n      var filters = { module: \'\', tag: \'\', source: \'\', kw: \'\' };\\n\\n      function applyFilters(list) {\\n        return list.filter(function (q) {\\n          if (filters.module && filters.module !== \'全部模块\' && q.module !== filters.module) return false;\\n          if (filters.tag && filters.tag !== \'全部标签\' && (q.tags || []).indexOf(filters.tag) < 0) return false;\\n          if (filters.source && filters.source !== \'全部来源\' && q.source !== filters.source) return false;\\n          if (filters.kw) {\\n            var hay = (q.stem + \' \' + q.module + \' \' + (q.tags || []).join(\' \') + \' \' + (q.analysis || \'\')).toLowerCase();\\n            if (hay.indexOf(filters.kw.toLowerCase()) < 0) return false;\\n          }\\n          return true;\\n        });\\n      }\\n\\n      function answerText(q) {\\n        var opt = (q.options || []).find(function (o) {\\n          return o.indexOf(q.answer + \'.\') === 0 || o.indexOf(q.answer + \'．\') === 0 || o.indexOf(q.answer + \'、\') === 0;\\n        });\\n        return opt ? (q.answer + \'. \' + opt.slice(opt.indexOf(\' \') + 1)) : (\'答案 \' + q.answer);\\n      }\\n\\n      function cardHTML(q) {\\n        var opts = (q.options || []).map(function (o, i) {\\n          return \'<div class=\\\"st-q-option\\\"><b>\' + String.fromCharCode(65 + i) + \'</b><span>\' + esc(o.replace(/^[A-Da-d][.．、]\\\\s*/, \'\')) + \'</span></div>\';\\n        }).join(\'\');\\n        var tags = (q.tags || []).map(function (t) { return \'<span class=\\\"tag\\\">\' + esc(t) + \'</span>\'; }).join(\'\');\\n        return `\\n<div class=\\\"glass-card st-q-card\\\" data-qid=\\\"${esc(q.id)}\\\">\\n  <div class=\\\"st-q-stem\\\">${esc(q.stem)}</div>\\n  <div class=\\\"st-q-meta\\\">\\n    <span class=\\\"tag tag-accent\\\">${esc(q.module || \'未分类\')}</span>\\n    ${tags}\\n    <span class=\\\"tag\\\">${icon(\'file\', 12)} ${esc(q.source || \'未知来源\')}</span>\\n    ${q.createdAt ? \'<span class=\\\"muted\\\" style=\\\"font-size:0.78rem;margin-left:auto\\\">\' + fmtMD(String(q.createdAt).slice(0, 10)) + \'</span>\' : \'\'}\\n  </div>\\n  <div class=\\\"st-q-extra\\\" hidden>\\n    <div class=\\\"st-q-options\\\">${opts}</div>\\n    <div class=\\\"st-q-answer\\\">\\n      <span class=\\\"muted\\\">答案：</span>\\n      <span class=\\\"st-answer-mask\\\">${esc(answerText(q))}</span>\\n      <button class=\\\"btn btn-soft btn-sm\\\" data-action=\\\"answer\\\" data-id=\\\"${esc(q.id)}\\\">查看答案</button>\\n    </div>\\n    <div class=\\\"st-q-analysis\\\" hidden>${icon(\'info\', 14)} ${esc(q.analysis || \'暂无解析\')}</div>\\n    <div class=\\\"st-q-foot\\\">\\n      <button class=\\\"btn btn-ghost btn-sm\\\" data-action=\\\"wrong\\\" data-id=\\\"${esc(q.id)}\\\">${icon(\'wrong\', 14)} 标记为错题</button>\\n      <button class=\\\"btn btn-danger btn-sm\\\" data-action=\\\"del\\\" data-id=\\\"${esc(q.id)}\\\">${icon(\'trash\', 14)} 删除</button>\\n      <button class=\\\"st-q-toggle\\\" data-action=\\\"toggle\\\" data-id=\\\"${esc(q.id)}\\\">展开 ${icon(\'chevron\', 14)}</button>\\n    </div>\\n  </div>\\n</div>`;\\n      }\\n\\n      function renderList() {\\n        var items = applyFilters(App.store.questions.list());\\n        listBox.innerHTML = items.length\\n          ? items.map(cardHTML).join(\'\')\\n          : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'question\', 34) + \'</div><p>没有符合条件的题目，试试调整筛选，或录入新题目</p></div>\';\\n        if (focusId) {\\n          var card = listBox.querySelector(\'[data-qid=\\\"\' + focusId + \'\\\"]\');\\n          if (card) {\\n            card.classList.add(\'expanded\', \'st-focus\');\\n            var ex = card.querySelector(\'.st-q-extra\');\\n            if (ex) ex.hidden = false;\\n            setTimeout(function () { card.scrollIntoView({ behavior: \'smooth\', block: \'center\' }); }, 60);\\n            setTimeout(function () { card.classList.remove(\'st-focus\'); }, 2000);\\n          }\\n          focusId = \'\';\\n        }\\n      }\\n\\n      function toggleCard(card) {\\n        var expanded = card.classList.toggle(\'expanded\');\\n        var ex = card.querySelector(\'.st-q-extra\');\\n        if (ex) ex.hidden = !expanded;\\n      }\\n\\n      listBox.addEventListener(\'click\', function (e) {\\n        var btn = e.target.closest(\'[data-action]\');\\n        if (btn) {\\n          var id = btn.dataset.id;\\n          var action = btn.dataset.action;\\n          if (action === \'toggle\') {\\n            var c = btn.closest(\'.st-q-card\');\\n            if (c) toggleCard(c);\\n          } else if (action === \'answer\') {\\n            var card = btn.closest(\'.st-q-card\');\\n            var maskEl = card.querySelector(\'.st-answer-mask\');\\n            var ana = card.querySelector(\'.st-q-analysis\');\\n            if (maskEl) { maskEl.classList.remove(\'st-answer-mask\'); maskEl.textContent = \'\'; }\\n            var q = App.store.questions.get(id);\\n            if (maskEl && q) maskEl.textContent = answerText(q);\\n            if (ana) ana.hidden = false;\\n            btn.textContent = \'已查看\';\\n            btn.disabled = true;\\n          } else if (action === \'wrong\') {\\n            openWrongModal(id);\\n          } else if (action === \'del\') {\\n            var qq = App.store.questions.get(id);\\n            if (!qq) return;\\n            App.openModal(\'<p>确定删除这道题目吗？关联的错题记录也会一并删除。</p><p class=\\\"muted\\\" style=\\\"font-size:0.85rem\\\">\' + esc(qq.stem) + \'</p>\', {\\n              title: \'删除题目\',\\n              confirmText: \'删除\',\\n              cancelText: \'取消\',\\n              onConfirm: function (close) {\\n                App.store.questions.remove(id);\\n                App.store.wrongQuestions.list().forEach(function (w) {\\n                  if (w.questionId === id) App.store.wrongQuestions.remove(w.id);\\n                });\\n                close();\\n                App.showToast(\'题目已删除\', \'success\');\\n                renderList();\\n              }\\n            });\\n          }\\n          return;\\n        }\\n        var card = e.target.closest(\'.st-q-card\');\\n        if (card && !e.target.closest(\'button\')) toggleCard(card);\\n      });\\n\\n      // 筛选与搜索\\n      el.querySelector(\'#st-q-module\').addEventListener(\'change\', function (e) { filters.module = e.target.value; renderList(); });\\n      el.querySelector(\'#st-q-tag\').addEventListener(\'change\', function (e) { filters.tag = e.target.value; renderList(); });\\n      el.querySelector(\'#st-q-source\').addEventListener(\'change\', function (e) { filters.source = e.target.value; renderList(); });\\n      var searchInput = el.querySelector(\'#st-q-search\');\\n      var debounce = null;\\n      searchInput.addEventListener(\'input\', function () {\\n        clearTimeout(debounce);\\n        debounce = setTimeout(function () { filters.kw = searchInput.value; renderList(); }, 250);\\n      });\\n\\n      // 录入题目\\n      el.querySelector(\'#st-q-add\').addEventListener(\'click\', function () { openAddQuestionModal(renderList); });\\n      // 批量导入\\n      el.querySelector(\'#st-q-import\').addEventListener(\'click\', function () { openImportModal(renderList); });\\n\\n      renderList();\\n    }\\n  };\\n\\n  /** 录入题目弹窗 */\\n  function openAddQuestionModal(onDone) {\\n    var moduleOpts = ALL_MODULES.map(function (m) { return \'<option value=\\\"\' + esc(m) + \'\\\">\' + esc(m) + \'</option>\'; }).join(\'\');\\n    var mask = App.openModal(`\\n<div>\\n  <div class=\\\"st-form-row\\\"><label>所属模块</label>\\n    <select class=\\\"select\\\" id=\\\"f-module\\\">${moduleOpts}</select>\\n  </div>\\n  <div class=\\\"st-form-row\\\"><label>题干 *</label>\\n    <textarea class=\\\"textarea\\\" id=\\\"f-stem\\\" rows=\\\"3\\\" placeholder=\\\"输入题目题干…\\\"></textarea>\\n  </div>\\n  <div class=\\\"st-form-grid\\\">\\n    <div class=\\\"st-form-row\\\"><label>选项 A *</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"f-opt-A\\\" placeholder=\\\"选项内容\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>选项 B *</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"f-opt-B\\\" placeholder=\\\"选项内容\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>选项 C</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"f-opt-C\\\" placeholder=\\\"选填\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>选项 D</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"f-opt-D\\\" placeholder=\\\"选填\\\"></div>\\n  </div>\\n  <div class=\\\"st-form-row\\\"><label>正确答案 *</label>\\n    <select class=\\\"select\\\" id=\\\"f-answer\\\">\\n      <option value=\\\"A\\\">A</option><option value=\\\"B\\\">B</option><option value=\\\"C\\\">C</option><option value=\\\"D\\\">D</option>\\n    </select>\\n  </div>\\n  <div class=\\\"st-form-row\\\"><label>解析</label>\\n    <textarea class=\\\"textarea\\\" id=\\\"f-analysis\\\" rows=\\\"2\\\" placeholder=\\\"答案解析（选填）\\\"></textarea>\\n  </div>\\n  <div class=\\\"st-form-row\\\"><label>标签（逗号分隔）</label>\\n    <input type=\\\"text\\\" class=\\\"input\\\" id=\\\"f-tags\\\" placeholder=\\\"如：逻辑填空, 语境\\\">\\n  </div>\\n  <p class=\\\"st-form-hint\\\">选项与答案中至少填写 A、B 两项；答案需对应已填写的选项。</p>\\n</div>`, {\\n      title: \'录入题目\',\\n      confirmText: \'保存\',\\n      cancelText: \'取消\',\\n      onConfirm: function (close) {\\n        var stem = mask.querySelector(\'#f-stem\').value.trim();\\n        var module = mask.querySelector(\'#f-module\').value;\\n        var opts = [\'A\', \'B\', \'C\', \'D\'].map(function (k) {\\n          var v = mask.querySelector(\'#f-opt-\' + k).value.trim();\\n          return v ? k + \'. \' + v : \'\';\\n        }).filter(Boolean);\\n        var answer = mask.querySelector(\'#f-answer\').value;\\n        if (!stem) { App.showToast(\'请填写题干\', \'warn\'); return; }\\n        if (opts.length < 2) { App.showToast(\'至少填写 A、B 两个选项\', \'warn\'); return; }\\n        var letters = opts.map(function (o) { return o.charAt(0); });\\n        if (letters.indexOf(answer) < 0) { App.showToast(\'答案需对应已填写的选项\', \'warn\'); return; }\\n        var tags = mask.querySelector(\'#f-tags\').value.split(/[,，、\\\\s]+/).filter(Boolean);\\n        App.store.questions.add({\\n          module: module,\\n          stem: stem,\\n          options: opts,\\n          answer: answer,\\n          analysis: mask.querySelector(\'#f-analysis\').value.trim(),\\n          source: \'手动录入\',\\n          tags: tags\\n        });\\n        close();\\n        App.showToast(\'题目已录入\', \'success\');\\n        if (onDone) onDone();\\n      }\\n    });\\n  }\\n\\n  /** 批量导入解析：块间以空行分隔，支持 【模块】 行 */\\n  function parseQuestions(text) {\\n    var lines = String(text || \'\').split(/\\\\r?\\\\n/);\\n    var blocks = [], cur = null;\\n    lines.forEach(function (line) {\\n      var t = line.trim();\\n      if (!t) {\\n        if (cur && cur.lines.length) { blocks.push(cur); cur = null; }\\n        return;\\n      }\\n      if (!cur) cur = { lines: [] };\\n      cur.lines.push(line);\\n    });\\n    if (cur && cur.lines.length) blocks.push(cur);\\n\\n    var items = [], skipped = 0;\\n    blocks.forEach(function (b) {\\n      var q = parseBlock(b.lines);\\n      if (q) items.push(q); else skipped++;\\n    });\\n    return { items: items, skipped: skipped };\\n  }\\n\\n  function parseBlock(lines) {\\n    var optLines = {}, answer = \'\', analysis = \'\', module = \'\', tags = [], stemLines = [];\\n    var isOpt = /^([A-Da-d])[.．、]\\\\s*(.+)$/;\\n    lines.forEach(function (line) {\\n      var t = line.trim();\\n      var m;\\n      if ((m = t.match(/^答案\\\\s*[:：]\\\\s*([A-Da-d])/i))) { answer = m[1].toUpperCase(); return; }\\n      if ((m = t.match(/^解析\\\\s*[:：]\\\\s*(.+)$/i))) { analysis = m[1]; return; }\\n      if ((m = t.match(/^标签\\\\s*[:：]\\\\s*(.+)$/i))) { tags = m[1].split(/[,，、\\\\s]+/).filter(Boolean); return; }\\n      if ((m = t.match(/^模块\\\\s*[:：]\\\\s*(.+)$/i))) { module = m[1].trim(); return; }\\n      if ((m = t.match(/^【(.+?)】/))) { module = m[1].trim(); return; }\\n      if ((m = t.match(isOpt))) { optLines[m[1].toUpperCase()] = m[2].trim(); return; }\\n      stemLines.push(t);\\n    });\\n    var stem = stemLines.join(\' \');\\n    if (!stem || Object.keys(optLines).length < 2) return null;\\n    var opts = [\'A\', \'B\', \'C\', \'D\'].filter(function (k) { return optLines[k]; })\\n      .map(function (k) { return k + \'. \' + optLines[k]; });\\n    if (!answer) answer = \'A\';\\n    if (opts.indexOf(answer + \'.\') < 0 && opts.indexOf(answer + \'．\') < 0) answer = \'A\';\\n    return { module: module || \'未分类\', stem: stem, options: opts, answer: answer, analysis: analysis, source: \'批量导入\', tags: tags };\\n  }\\n\\n  function openImportModal(onDone) {\\n    var mask = App.openModal(`\\n<div>\\n  <p class=\\\"st-form-hint\\\">粘贴题目文本，多道题之间用空行分隔。支持以下格式（字段可省略）：</p>\\n  <pre style=\\\"background:var(--card);border:1px solid var(--border);border-radius:10px;padding:10px 14px;font-size:0.8rem;line-height:1.7;white-space:pre-wrap;color:var(--text-2)\\\">【判断推理】\\n所有天鹅都是白的，这只鸟不是天鹅，所以…\\nA. 演绎推理\\nB. 归纳推理\\nC. 类比推理\\nD. 溯因推理\\n答案：A\\n解析：由一般到个别，属演绎推理。\\n标签：逻辑判断</pre>\\n  <div class=\\\"st-form-row\\\"><label>题目文本</label>\\n    <textarea class=\\\"textarea\\\" id=\\\"f-import-text\\\" rows=\\\"9\\\" placeholder=\\\"在此粘贴题目…\\\"></textarea>\\n  </div>\\n  <p class=\\\"st-form-hint\\\" id=\\\"f-import-preview\\\"></p>\\n</div>`, {\\n      title: \'批量导入题目\',\\n      confirmText: \'导入\',\\n      cancelText: \'取消\',\\n      onConfirm: function (close) {\\n        var text = mask.querySelector(\'#f-import-text\').value;\\n        var r = parseQuestions(text);\\n        if (!r.items.length) { App.showToast(\'未能解析出有效题目，请检查格式\', \'warn\'); return; }\\n        r.items.forEach(function (q) { App.store.questions.add(q); });\\n        close();\\n        App.showToast(\'成功导入 \' + r.items.length + \' 道\' + (r.skipped ? \'，跳过 \' + r.skipped + \' 条\' : \'\'), \'success\');\\n        if (onDone) onDone();\\n      }\\n    });\\n    var ta = mask.querySelector(\'#f-import-text\');\\n    ta.addEventListener(\'input\', function () {\\n      var r = parseQuestions(ta.value);\\n      mask.querySelector(\'#f-import-preview\').textContent = r.items.length\\n        ? \'可解析出 \' + r.items.length + \' 道题目\' + (r.skipped ? \'，另有 \' + r.skipped + \' 条无法识别\' : \'\')\\n        : (ta.value.trim() ? \'暂未解析出有效题目\' : \'\');\\n    });\\n  }\\n\\n  /** 标记为错题弹窗 */\\n  function openWrongModal(qid) {\\n    var q = App.store.questions.get(qid);\\n    if (!q) return;\\n    var exists = App.store.wrongQuestions.list().some(function (w) {\\n      return w.questionId === qid && w.status !== \'archived\';\\n    });\\n    if (exists) { App.showToast(\'该题已在错题本中\', \'warn\'); return; }\\n    var opts = REASON_TAGS.map(function (r, i) {\\n      return `<label class=\\\"st-mastery-opt${i === 0 ? \' sel\' : \'\'}\\\">\\n        <input type=\\\"radio\\\" name=\\\"wrong-reason\\\" value=\\\"${r}\\\"${i === 0 ? \' checked\' : \'\'}>\\n        <span class=\\\"tag ${REASON_TAG_CLASS[r]}\\\">${r}</span>\\n        <span class=\\\"ds\\\" style=\\\"margin-left:auto\\\"></span>\\n      </label>`;\\n    }).join(\'\');\\n    var mask = App.openModal(\'<p class=\\\"st-form-hint\\\">这道题当时为什么错了？记录原因便于针对性复习：</p>\' + opts, {\\n      title: \'加入错题本\',\\n      confirmText: \'加入\',\\n      cancelText: \'取消\',\\n      onConfirm: function (close) {\\n        var checked = mask.querySelector(\'input[name=\\\"wrong-reason\\\"]:checked\');\\n        var reason = checked ? checked.value : \'粗心\';\\n        App.store.wrongQuestions.add({\\n          questionId: qid,\\n          reason: reason,\\n          reviewCount: 0,\\n          consecutive: 0,\\n          lastResult: false,\\n          status: \'pending\',\\n          nextReview: todayStr()\\n        });\\n        close();\\n        App.showToast(\'已加入错题本，记得及时复习\', \'success\');\\n      }\\n    });\\n  }\\n\\n  /* ================================================================\\n     5. 错题本  /study/wrong\\n     ================================================================ */\\n\\n  var WRONG_DEF = {\\n    title: \'错题本\',\\n    render: function () {\\n      var wrongs = App.store.wrongQuestions.list();\\n      var stat = {\\n        total: wrongs.length,\\n        pending: wrongs.filter(function (w) { return w.status === \'pending\'; }).length,\\n        learning: wrongs.filter(function (w) { return w.status === \'learning\'; }).length,\\n        archived: wrongs.filter(function (w) { return w.status === \'archived\'; }).length\\n      };\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\"><h2>错题本</h2><p class=\\\"page-desc\\\">先做题再看答案，连续答对 3 次自动归档</p></div>\\n  <div class=\\\"st-wrong-stats\\\">\\n    <div class=\\\"glass-card st-wrong-stat\\\"><span class=\\\"num\\\">${stat.total}</span><span class=\\\"lbl\\\">总错题数</span></div>\\n    <div class=\\\"glass-card st-wrong-stat\\\"><span class=\\\"num\\\" style=\\\"color:var(--warn)\\\">${stat.pending}</span><span class=\\\"lbl\\\">待复习</span></div>\\n    <div class=\\\"glass-card st-wrong-stat\\\"><span class=\\\"num\\\" style=\\\"color:var(--accent)\\\">${stat.learning}</span><span class=\\\"lbl\\\">掌握中</span></div>\\n    <div class=\\\"glass-card st-wrong-stat\\\"><span class=\\\"num\\\" style=\\\"color:var(--success)\\\">${stat.archived}</span><span class=\\\"lbl\\\">已归档</span></div>\\n  </div>\\n  <div class=\\\"search-tabs\\\" id=\\\"st-wrong-tabs\\\">\\n    ${[\'全部\', \'待复习\', \'掌握中\', \'已归档\'].map(function (t, i) {\\n      return \'<button class=\\\"search-tab\' + (i === 0 ? \' active\' : \'\') + \'\\\" data-tab=\\\"\' + t + \'\\\">\' + t + \'</button>\';\\n    }).join(\'\')}\\n  </div>\\n  <div class=\\\"st-wrong-list\\\" id=\\\"st-wrong-list\\\"></div>\\n  <div class=\\\"st-wrong-review\\\" id=\\\"st-wrong-review\\\" hidden></div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var listBox = el.querySelector(\'#st-wrong-list\');\\n      var reviewBox = el.querySelector(\'#st-wrong-review\');\\n      var tabsBox = el.querySelector(\'#st-wrong-tabs\');\\n      var tab = \'全部\';\\n      var reviewQueue = [], reviewIdx = -1;\\n\\n      function linked(w) {\\n        return App.store.questions.get(w.questionId);\\n      }\\n      function itemHTML(w) {\\n        var q = linked(w);\\n        var due = fmtDue(w.nextReview);\\n        var overdue = w.status !== \'archived\' && w.nextReview && w.nextReview < todayStr();\\n        return `\\n<div class=\\\"st-wrong-item\\\" data-review=\\\"${esc(w.id)}\\\" data-status=\\\"${w.status}\\\">\\n  <span class=\\\"st-wrong-stem\\\">${q ? esc(q.stem) : \'<span class=\\\"muted\\\">（原题已删除）</span>\'}</span>\\n  <div class=\\\"st-wrong-meta\\\">\\n    ${w.reason ? \'<span class=\\\"tag \' + (REASON_TAG_CLASS[w.reason] || \'\') + \'\\\">\' + esc(w.reason) + \'</span>\' : \'\'}\\n    <span>复习 ${Number(w.reviewCount) || 0} 次</span>\\n    <span>${w.lastResult === true ? \'✅\' : w.lastResult === false && w.reviewCount ? \'❌\' : \'—\'}</span>\\n    <span class=\\\"${overdue ? \'tag tag-danger\' : \'\'}\\\" style=\\\"${overdue ? \'\' : \'color:var(--text-3)\'}\\\">下次复习 ${due}</span>\\n    <span class=\\\"tag ${w.status === \'pending\' ? \'tag-warn\' : w.status === \'learning\' ? \'tag-accent\' : \'tag-success\'}\\\">\\n      ${w.status === \'pending\' ? \'待复习\' : w.status === \'learning\' ? \'掌握中\' : \'已归档\'}\\n    </span>\\n  </div>\\n</div>`;\\n      }\\n\\n      function filtered() {\\n        var list = App.store.wrongQuestions.list();\\n        if (tab === \'全部\') return list;\\n        return list.filter(function (w) { return w.status === (tab === \'待复习\' ? \'pending\' : tab === \'掌握中\' ? \'learning\' : \'archived\'); });\\n      }\\n\\n      function renderList() {\\n        var items = filtered();\\n        listBox.innerHTML = items.length\\n          ? items.map(itemHTML).join(\'\')\\n          : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'wrong\', 34) + \'</div><p>\' + (tab === \'全部\' ? \'错题本是空的，做题时记得把错题加进来\' : \'该分类下暂无错题\') + \'</p></div>\';\\n      }\\n\\n      tabsBox.addEventListener(\'click\', function (e) {\\n        var btn = e.target.closest(\'[data-tab]\');\\n        if (!btn) return;\\n        tab = btn.dataset.tab;\\n        tabsBox.querySelectorAll(\'.search-tab\').forEach(function (t) { t.classList.toggle(\'active\', t === btn); });\\n        renderList();\\n      });\\n\\n      // —— 复习模式 ——\\n      function enterReview(id) {\\n        var all = App.store.wrongQuestions.list().filter(function (w) { return w.status !== \'archived\'; })\\n          .sort(function (a, b) { return (a.nextReview || \'\').localeCompare(b.nextReview || \'\'); });\\n        reviewQueue = all;\\n        reviewIdx = all.findIndex(function (w) { return w.id === id; });\\n        if (reviewIdx < 0) { App.showToast(\'该题无需复习\', \'info\'); return; }\\n        listBox.hidden = true;\\n        tabsBox.hidden = true;\\n        reviewBox.hidden = false;\\n        renderReview();\\n      }\\n\\n      function exitReview() {\\n        reviewBox.hidden = true;\\n        listBox.hidden = false;\\n        tabsBox.hidden = false;\\n        renderList();\\n        reviewBox.innerHTML = \'\';\\n      }\\n\\n      function renderReview() {\\n        var w = reviewQueue[reviewIdx];\\n        if (!w) {\\n          reviewBox.innerHTML = `\\n<div class=\\\"glass-card\\\" style=\\\"padding:34px;text-align:center\\\" class=\\\"st-review-enter\\\">\\n  <div class=\\\"empty-icon\\\" style=\\\"font-size:2.2rem\\\">🎉</div>\\n  <h3 style=\\\"margin:10px 0 6px\\\">本组复习完成</h3>\\n  <p class=\\\"muted\\\" style=\\\"margin-bottom:18px\\\">错题本中已没有待复习的题目</p>\\n  <button class=\\\"btn btn-primary\\\" data-review-exit>返回错题本</button>\\n</div>`;\\n          return;\\n        }\\n        var q = linked(w);\\n        if (!q) {\\n          App.store.wrongQuestions.remove(w.id);\\n          reviewIdx++;\\n          renderReview();\\n          return;\\n        }\\n        reviewBox.innerHTML = `\\n<div class=\\\"glass-card\\\" style=\\\"padding:22px 24px\\\" class=\\\"st-review-enter\\\">\\n  <div style=\\\"display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px\\\">\\n    <span class=\\\"tag tag-accent\\\">${esc(w.reason || \'未分类\')}</span>\\n    <span class=\\\"muted\\\" style=\\\"font-size:0.82rem\\\">复习第 ${(Number(w.reviewCount) || 0) + 1} 次 · 连续答对 ${Number(w.consecutive) || 0} 次</span>\\n    <button class=\\\"btn btn-ghost btn-sm\\\" data-review-exit style=\\\"margin-left:auto\\\">退出复习</button>\\n  </div>\\n  <h3 style=\\\"font-size:1.05rem;line-height:1.7;margin-bottom:14px\\\">${esc(q.stem)}</h3>\\n  <div class=\\\"st-q-options\\\" id=\\\"st-review-options\\\">\\n    ${(q.options || []).map(function (o, i) {\\n      return `<button class=\\\"st-option-btn\\\" data-opt=\\\"${String.fromCharCode(65 + i)}\\\">\\n        <b>${String.fromCharCode(65 + i)}.</b><span>${esc(o.replace(/^[A-Da-d][.．、]\\\\s*/, \'\'))}</span>\\n      </button>`;\\n    }).join(\'\')}\\n  </div>\\n  <div id=\\\"st-review-result\\\"></div>\\n</div>`;\\n        reviewBox.querySelectorAll(\'[data-review-exit]\').forEach(function (b) {\\n          b.addEventListener(\'click\', exitReview);\\n        });\\n        // 先做题再看答案\\n        reviewBox.querySelectorAll(\'.st-option-btn\').forEach(function (btn) {\\n          btn.addEventListener(\'click\', function () {\\n            if (reviewBox.dataset.locked === \'1\') return;\\n            reviewBox.dataset.locked = \'1\';\\n            reviewBox.querySelectorAll(\'.st-option-btn\').forEach(function (b) { b.classList.remove(\'selected\'); });\\n            btn.classList.add(\'selected\');\\n            var letter = btn.dataset.opt;\\n            submitReview(w.id, letter, btn);\\n          });\\n        });\\n      }\\n\\n      function submitReview(id, letter, btn) {\\n        var w = App.store.wrongQuestions.get(id);\\n        var q = linked(w);\\n        if (!w || !q) return;\\n        var correct = String(letter).toUpperCase() === String(q.answer).toUpperCase();\\n        var updated = applyReviewResult(w, correct);\\n        var archived = updated.status === \'archived\';\\n\\n        // 标注选项对错\\n        reviewBox.querySelectorAll(\'.st-option-btn\').forEach(function (b) {\\n          if (b.dataset.opt === String(q.answer).toUpperCase()) b.classList.add(\'correct\');\\n          if (b.dataset.opt === letter && !correct) b.classList.add(\'wrong\');\\n        });\\n\\n        var banner = correct\\n          ? \'<div class=\\\"st-result-banner st-result-ok\\\">\' + icon(\'success\', 18) + \'答对了！\' + (archived ? \' 连续 3 次正确，已自动归档 🎉\' : \'\') + \'</div>\'\\n          : \'<div class=\\\"st-result-banner st-result-no\\\">\' + icon(\'error\', 18) + \'答错了，别灰心，看看解析再复习一次</div>\';\\n        var confetti = archived\\n          ? \'<div class=\\\"st-confetti\\\">\' + [0, 1, 2, 3, 4, 5, 6, 7].map(function (i) {\\n            var colors = [\'#b06f47\', \'#6c9170\', \'#c49338\', \'#7d8ca3\', \'#a37d92\', \'#8a9a6b\'];\\n            return \'<i style=\\\"background:\' + colors[i % colors.length] + \';--dx:\' + ((i - 3.5) * 26) + \'px;animation-delay:\' + (i * 40) + \'ms\\\"></i>\';\\n          }).join(\'\') + \'</div>\'\\n          : \'\';\\n        var statusTag = archived ? \'<span class=\\\"tag tag-success\\\">已归档</span>\' : \'<span class=\\\"tag \' + (updated.status === \'pending\' ? \'tag-warn\' : \'tag-accent\') + \'\\\">\' + (updated.status === \'pending\' ? \'待复习\' : \'掌握中\') + \'</span>\';\\n\\n        var resultHtml = `\\n<div class=\\\"st-review-enter\\\">\\n  ${confetti}\\n  ${banner}\\n  <div class=\\\"st-q-analysis\\\" style=\\\"margin-top:12px\\\">${icon(\'info\', 14)} ${esc(q.analysis || \'暂无解析\')}</div>\\n  <div style=\\\"display:flex;gap:16px;align-items:center;margin-top:14px;flex-wrap:wrap;font-size:0.9rem;color:var(--text-2)\\\">\\n    <span>正确答案：<b style=\\\"color:var(--success)\\\">${esc(q.answer)}</b></span>\\n    <span>${statusTag}</span>\\n    <span>下次复习：${archived ? \'已归档\' : fmtMD(updated.nextReview)}</span>\\n  </div>\\n  <div style=\\\"display:flex;gap:10px;margin-top:18px;flex-wrap:wrap\\\">\\n    <button class=\\\"btn btn-primary\\\" id=\\\"st-review-next\\\">${icon(\'refresh\', 16)} 下一题</button>\\n    <button class=\\\"btn btn-ghost\\\" data-review-exit>返回错题本</button>\\n  </div>\\n</div>`;\\n        var box = reviewBox.querySelector(\'#st-review-result\');\\n        box.innerHTML = resultHtml;\\n        var bannerEl = box.querySelector(\'.st-result-banner\');\\n        if (bannerEl) bannerEl.classList.add(\'st-burst\');\\n        box.querySelectorAll(\'[data-review-exit]\').forEach(function (b) { b.addEventListener(\'click\', exitReview); });\\n        var next = box.querySelector(\'#st-review-next\');\\n        if (next) {\\n          next.addEventListener(\'click\', function () {\\n            reviewIdx++;\\n            reviewBox.dataset.locked = \'\';\\n            renderReview();\\n          });\\n        }\\n      }\\n\\n      /** 应用复习结果：连续答对 3 次归档，答错降级并重算艾宾浩斯间隔 */\\n      function applyReviewResult(w, correct) {\\n        var reviewCount = (Number(w.reviewCount) || 0) + 1;\\n        var consecutive = correct ? (Number(w.consecutive) || 0) + 1 : 0;\\n        var status, nextReview;\\n        if (!correct) {\\n          status = \'pending\';\\n          nextReview = addDaysStr(todayStr(), 1); // 降级：回到间隔起点\\n        } else if (consecutive >= 3) {\\n          status = \'archived\';\\n          nextReview = \'\';\\n        } else {\\n          status = \'learning\';\\n          nextReview = addDaysStr(todayStr(), EB_DAYS[Math.min(consecutive, 4)]);\\n        }\\n        return App.store.wrongQuestions.update(w.id, {\\n          reviewCount: reviewCount,\\n          consecutive: consecutive,\\n          lastResult: !!correct,\\n          status: status,\\n          nextReview: nextReview\\n        });\\n      }\\n\\n      listBox.addEventListener(\'click\', function (e) {\\n        var item = e.target.closest(\'[data-review]\');\\n        if (!item) return;\\n        var w = App.store.wrongQuestions.get(item.dataset.review);\\n        if (!w) return;\\n        if (w.status === \'archived\') { App.showToast(\'该题已归档，无需再复习\', \'info\'); return; }\\n        enterReview(w.id);\\n      });\\n\\n      renderList();\\n    }\\n  };\\n\\n  /* ================================================================\\n     6. 学习计划  /study/plan （别名 /study/plans）\\n     ================================================================ */\\n\\n  function planTargetMin(p) {\\n    var mods = p.modules || {};\\n    return Object.keys(mods).reduce(function (s, k) { return s + (Number(mods[k]) || 0) * 60; }, 0);\\n  }\\n  function planActualMin(p) {\\n    if (!p.start || !p.end) return 0;\\n    return App.store.checkins.list().filter(function (c) {\\n      return c.date && c.date >= p.start && c.date <= p.end;\\n    }).reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n  }\\n  function planProgress(p) {\\n    var t = planTargetMin(p);\\n    if (!t) return Math.min(100, Math.max(0, Number(p.progress) || 0));\\n    return Math.min(100, Math.round(planActualMin(p) / t * 100));\\n  }\\n  function moduleActual(p, name) {\\n    return App.store.checkins.list().filter(function (c) {\\n      return c.date && c.date >= p.start && c.date <= p.end && (c.modules || []).indexOf(name) >= 0;\\n    }).reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n  }\\n\\n  var PLAN_DEF = {\\n    title: \'学习计划\',\\n    render: function () {\\n      var view = (getUI().planView || \'week\') === \'month\' ? \'month\' : \'week\';\\n      var today = todayStr();\\n      var period = view === \'week\' ? weekRange() : monthRange(today.slice(0, 7));\\n      var plans = App.store.plans.list();\\n      var active = plans.filter(function (p) { return p.type === view && p.status !== \'done\'; });\\n      var history = plans.filter(function (p) { return p.type === view && p.status === \'done\'; });\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\"><h2>学习计划</h2><p class=\\\"page-desc\\\">设定模块目标，用数据对比实际投入</p></div>\\n  <div class=\\\"st-plan-toolbar\\\">\\n    <div class=\\\"segmented\\\" id=\\\"st-plan-seg\\\">\\n      <button class=\\\"seg-btn${view === \'week\' ? \' active\' : \'\'}\\\" data-view=\\\"week\\\">周计划</button>\\n      <button class=\\\"seg-btn${view === \'month\' ? \' active\' : \'\'}\\\" data-view=\\\"month\\\">月计划</button>\\n    </div>\\n    <span class=\\\"st-plan-period\\\" id=\\\"st-plan-period\\\">${fmtMD(period.start)} — ${fmtMD(period.end)}</span>\\n  </div>\\n  <div id=\\\"st-plan-list\\\">\\n    ${active.length ? active.map(planCardHTML).join(\'\') : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'plan\', 34) + \'</div><p>暂无进行中的\' + (view === \'week\' ? \'周\' : \'月\') + \'计划，点击右下角新建</p></div>\'}\\n  </div>\\n  <section class=\\\"glass-card\\\" style=\\\"padding:18px 20px;margin-top:18px\\\">\\n    <div style=\\\"display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:6px\\\">\\n      <h3 style=\\\"font-size:1rem\\\">${view === \'week\' ? \'本周\' : \'本月\'}实际投入 vs 目标</h3>\\n      <span class=\\\"st-chart-note\\\">\\n        <span class=\\\"st-legend\\\"><i style=\\\"background:var(--success)\\\"></i>实际</span>\\n        <span class=\\\"st-legend\\\"><i style=\\\"border:1.5px dashed var(--warn);background:transparent;border-radius:4px\\\"></i>目标均线</span>\\n      </span>\\n    </div>\\n    <div class=\\\"st-chart\\\" id=\\\"st-plan-chart\\\"></div>\\n  </section>\\n  ${history.length ? `\\n  <div style=\\\"margin-top:22px\\\">\\n    <h3 style=\\\"font-size:0.9rem;color:var(--text-3);margin-bottom:10px\\\">历史计划（已完成归档）</h3>\\n    ${history.map(function (p) {\\n      return `<div class=\\\"st-history-row\\\"><span class=\\\"tag tag-success\\\">已完成</span><span class=\\\"t\\\">${esc(p.title)}</span><span class=\\\"muted\\\">${fmtMD(p.start)} — ${fmtMD(p.end)}</span></div>`;\\n    }).join(\'\')}\\n  </div>` : \'\'}\\n  <button class=\\\"btn btn-primary st-fab\\\" id=\\\"st-plan-new\\\">${icon(\'plus\', 16)} 新建计划</button>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var view = (getUI().planView || \'week\') === \'month\' ? \'month\' : \'week\';\\n\\n      // 到期自动标记完成 / 进度实时计算\\n      var today = todayStr();\\n      App.store.plans.list().forEach(function (p) {\\n        var prog = planProgress(p);\\n        if (prog !== Number(p.progress)) App.store.plans.update(p.id, { progress: prog });\\n        if (p.status !== \'done\' && p.end && p.end < today && prog >= 100) {\\n          App.store.plans.update(p.id, { status: \'done\', completedAt: today });\\n        }\\n      });\\n\\n      function rerender() {\\n        App.refresh();\\n      }\\n\\n      el.querySelector(\'#st-plan-seg\').addEventListener(\'click\', function (e) {\\n        var btn = e.target.closest(\'[data-view]\');\\n        if (!btn) return;\\n        setUI({ planView: btn.dataset.view });\\n        rerender();\\n      });\\n\\n      // 计划卡片展开明细\\n      el.querySelector(\'#st-plan-list\').addEventListener(\'click\', function (e) {\\n        var card = e.target.closest(\'[data-plan-id]\');\\n        if (!card) return;\\n        var detail = card.querySelector(\'.st-plan-detail\');\\n        if (detail) detail.hidden = !detail.hidden;\\n      });\\n\\n      // 新建计划\\n      el.querySelector(\'#st-plan-new\').addEventListener(\'click\', function () { openNewPlanModal(rerender); });\\n\\n      renderChart(el.querySelector(\'#st-plan-chart\'), view);\\n      // 图表柱高过渡动画\\n      requestAnimationFrame(function () {\\n        el.querySelectorAll(\'.st-chart-bar\').forEach(function (b) {\\n          var h = b.getAttribute(\'data-h\');\\n          if (h) b.style.height = h + \'%\';\\n        });\\n      });\\n    }\\n  };\\n\\n  function planCardHTML(p) {\\n    var target = planTargetMin(p);\\n    var actual = planActualMin(p);\\n    var prog = planProgress(p);\\n    var today = todayStr();\\n    var overdue = p.end && p.end < today && prog < 100;\\n    var done = prog >= 100;\\n    var mods = Object.keys(p.modules || {}).sort(function (a, b) { return (Number(p.modules[b]) || 0) - (Number(p.modules[a]) || 0); });\\n    var total = mods.reduce(function (s, m) { return s + (Number(p.modules[m]) || 0); }, 0);\\n    var segs = total > 0 ? mods.map(function (m) {\\n      var w = Math.round((Number(p.modules[m]) || 0) / total * 100);\\n      return \'<i style=\\\"width:\' + w + \'%;background:\' + moduleColor(m) + \'\\\" title=\\\"\' + esc(m) + \' \' + p.modules[m] + \'h\\\"></i>\';\\n    }).join(\'\') : \'<i style=\\\"width:100%;background:var(--ring-track)\\\"></i>\';\\n    var statusTag = done\\n      ? \'<span class=\\\"tag tag-success\\\">已完成</span>\'\\n      : overdue ? \'<span class=\\\"tag tag-danger\\\">已超期</span>\' : \'<span class=\\\"tag tag-accent\\\">进行中</span>\';\\n    var detailRows = mods.map(function (m) {\\n      var am = moduleActual(p, m);\\n      var tm = (Number(p.modules[m]) || 0) * 60;\\n      var pct = tm > 0 ? Math.min(100, Math.round(am / tm * 100)) : 0;\\n      return `<div class=\\\"st-mod-row\\\">\\n        <span class=\\\"name\\\"><i style=\\\"display:inline-block;width:10px;height:10px;border-radius:3px;background:${moduleColor(m)};margin-right:6px\\\"></i>${esc(m)}</span>\\n        <span class=\\\"track\\\"><span class=\\\"fill\\\" style=\\\"width:${pct}%;background:${moduleColor(m)}\\\"></span></span>\\n        <span class=\\\"val\\\">实际 ${fmtHM(am)} / 目标 ${p.modules[m]}h</span>\\n      </div>`;\\n    }).join(\'\');\\n    return `\\n<div class=\\\"glass-card st-plan-card${overdue ? \' overdue\' : \'\'}\\\" data-plan-id=\\\"${esc(p.id)}\\\">\\n  <div class=\\\"st-plan-head\\\">\\n    <span class=\\\"st-plan-title\\\">${esc(p.title || \'未命名计划\')}</span>\\n    ${statusTag}\\n    <span class=\\\"st-plan-dates\\\">${fmtMD(p.start)} — ${fmtMD(p.end)}</span>\\n    <span class=\\\"st-plan-progress\\\">${prog}%</span>\\n  </div>\\n  <div class=\\\"st-stack-bar\\\">${segs}</div>\\n  <div class=\\\"st-plan-detail\\\" hidden>\\n    <div class=\\\"divider\\\" style=\\\"margin:10px 0\\\"></div>\\n    ${detailRows}\\n    <div class=\\\"st-mod-row\\\" style=\\\"margin-top:4px\\\">\\n      <span class=\\\"name\\\">合计</span>\\n      <span class=\\\"track\\\"><span class=\\\"fill\\\" style=\\\"width:${Math.min(100, prog)}%;background:var(--accent)\\\"></span></span>\\n      <span class=\\\"val\\\">实际 ${fmtHM(actual)} / 目标 ${fmtHM(target)}</span>\\n    </div>\\n  </div>\\n</div>`;\\n  }\\n\\n  function openNewPlanModal(onDone) {\\n    var rows = ALL_MODULES.map(function (m) {\\n      return `<div class=\\\"st-form-row\\\"><label>${esc(m)}（小时）</label>\\n        <input type=\\\"number\\\" class=\\\"input\\\" min=\\\"0\\\" step=\\\"0.5\\\" value=\\\"0\\\" data-mod=\\\"${esc(m)}\\\"></div>`;\\n    }).join(\'\');\\n    var mask = App.openModal(`\\n<div>\\n  <div class=\\\"st-form-row\\\"><label>计划类型</label>\\n    <div class=\\\"segmented\\\" id=\\\"np-type\\\">\\n      <button class=\\\"seg-btn active\\\" data-type=\\\"week\\\">周计划（本周一至周日）</button>\\n      <button class=\\\"seg-btn\\\" data-type=\\\"month\\\">月计划（本月 1 日至月末）</button>\\n    </div>\\n  </div>\\n  <div class=\\\"st-form-grid\\\">\\n    ${rows}\\n    <div class=\\\"st-form-row\\\"><label>自定义模块（选填）</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"np-custom-name\\\" placeholder=\\\"模块名\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>自定义模块小时</label><input type=\\\"number\\\" class=\\\"input\\\" id=\\\"np-custom-hours\\\" min=\\\"0\\\" step=\\\"0.5\\\" value=\\\"0\\\"></div>\\n  </div>\\n  <p class=\\\"st-form-hint\\\">至少为 1 个模块设定大于 0 的目标小时数；时长将按周 / 月自动统计实际投入。</p>\\n</div>`, {\\n      title: \'新建计划\',\\n      confirmText: \'创建\',\\n      cancelText: \'取消\',\\n      onConfirm: function (close) {\\n        var type = \'week\';\\n        var seg = mask.querySelector(\'#np-type\');\\n        seg.querySelectorAll(\'.seg-btn\').forEach(function (b) {\\n          b.addEventListener(\'click\', function () {\\n            type = b.dataset.type;\\n            seg.querySelectorAll(\'.seg-btn\').forEach(function (x) { x.classList.toggle(\'active\', x === b); });\\n          });\\n        });\\n        var mods = {};\\n        mask.querySelectorAll(\'input[data-mod]\').forEach(function (inp) {\\n          var v = Number(inp.value);\\n          if (v > 0) mods[inp.dataset.mod] = v;\\n        });\\n        var cn = mask.querySelector(\'#np-custom-name\').value.trim();\\n        var ch = Number(mask.querySelector(\'#np-custom-hours\').value);\\n        if (cn && ch > 0) mods[cn] = ch;\\n        if (!Object.keys(mods).length) { App.showToast(\'请至少为一个模块设定目标时长\', \'warn\'); return; }\\n        var today = new Date();\\n        var start, end, title;\\n        if (type === \'week\') {\\n          var wk = weekRange();\\n          start = wk.start; end = wk.end;\\n          title = \'第 \' + isoWeek(today) + \' 周学习计划\';\\n        } else {\\n          var mr = monthRange(todayStr().slice(0, 7));\\n          start = mr.start; end = mr.end;\\n          title = today.getFullYear() + \' 年 \' + (today.getMonth() + 1) + \' 月学习计划\';\\n        }\\n        App.store.plans.add({ type: type, title: title, start: start, end: end, modules: mods, progress: 0, status: \'active\' });\\n        close();\\n        App.showToast(\'计划已创建\', \'success\');\\n        if (onDone) onDone();\\n      }\\n    });\\n  }\\n\\n  /** 柱状图：周视图按天、月视图按周聚合，纯 CSS 实现 */\\n  function renderChart(box, view) {\\n    var today = todayStr();\\n    var period = view === \'week\' ? weekRange() : monthRange(today.slice(0, 7));\\n    var checkins = App.store.checkins.list();\\n    var units = [];\\n    if (view === \'week\') {\\n      var d = parseDate(period.start);\\n      for (var i = 0; i < 7; i++) {\\n        var ds = addDaysStr(period.start, i);\\n        var names = [\'周一\', \'周二\', \'周三\', \'周四\', \'周五\', \'周六\', \'周日\'];\\n        units.push({ label: names[i] + \'\\\\n\' + fmtMD(ds), date: ds });\\n        d.setDate(d.getDate() + 1);\\n      }\\n    } else {\\n      var days = diffDays(period.start, period.end) + 1;\\n      var nWeeks = Math.ceil(days / 7);\\n      for (var w = 0; w < nWeeks; w++) {\\n        var ws = addDaysStr(period.start, w * 7);\\n        var we = addDaysStr(period.start, Math.min((w + 1) * 7 - 1, days - 1));\\n        units.push({ label: \'第\' + (w + 1) + \'周\', date: ws, end: we });\\n      }\\n    }\\n    var active = App.store.plans.list().find(function (p) { return p.type === view && p.status !== \'done\'; });\\n    var targetTotal = active ? planTargetMin(active) : 0;\\n    var targetPerUnit = targetTotal / units.length;\\n\\n    var values = units.map(function (u) {\\n      var sum = checkins.filter(function (c) {\\n        return c.date && c.date >= u.date && c.date <= (u.end || u.date);\\n      }).reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n      return { label: u.label, actual: sum };\\n    });\\n    var maxV = Math.max(60, targetPerUnit, values.reduce(function (m, v) { return Math.max(m, v.actual); }, 0));\\n    var targetPct = targetPerUnit > 0 ? Math.round(targetPerUnit / maxV * 100) : 0;\\n\\n    if (!targetTotal && values.every(function (v) { return v.actual === 0; })) {\\n      box.innerHTML = \'<div class=\\\"empty-state\\\" style=\\\"width:100%;padding:30px 10px\\\">\' + icon(\'plan\', 30) + \'<p>暂无学习数据，先新建一个计划并开始打卡吧</p></div>\';\\n      return;\\n    }\\n\\n    box.innerHTML = `\\n  ${targetPct > 0 ? \'<div class=\\\"st-target-line\\\" style=\\\"bottom:\' + targetPct + \'%\\\" title=\\\"目标均线\\\"></div>\' : \'\'}\\n  ${values.map(function (v) {\\n    var h = v.actual > 0 ? Math.max(4, Math.round(v.actual / maxV * 100)) : 0;\\n    var gh = targetPct > 0 ? Math.max(2, targetPct) : 0;\\n    return `<div class=\\\"st-chart-col\\\">\\n      <div class=\\\"st-chart-bar-wrap\\\">\\n        <div class=\\\"st-chart-bar actual\\\" data-h=\\\"${h}\\\" style=\\\"height:0\\\" title=\\\"${fmtHM(v.actual)}\\\"></div>\\n        ${gh > 0 ? \'<div class=\\\"st-chart-bar ghost\\\" data-h=\\\"\' + gh + \'\\\" style=\\\"height:0\\\" title=\\\"目标 \' + fmtHM(targetPerUnit) + \'\\\"></div>\' : \'\'}\\n      </div>\\n      <span class=\\\"st-chart-x\\\">${esc(v.label.replace(\'\\\\n\', \'<br>\'))}</span>\\n    </div>`;\\n  }).join(\'\')}`;\\n  }\\n\\n  /* ================================================================\\n     7. 学习打卡  /study/clock （别名 /study/checkin）\\n     ================================================================ */\\n\\n  function clockState() {\\n    var s = App.store.settings.studyClock || {};\\n    return {\\n      running: !!s.running,\\n      startedAt: Number(s.startedAt) || 0,\\n      accumulated: Number(s.accumulated) || 0,\\n      modules: Array.isArray(s.modules) ? s.modules : []\\n    };\\n  }\\n  function saveClockState(st) {\\n    App.store.updateSettings({ studyClock: st });\\n  }\\n  /** 基于时间戳计算已计时长（切走页面后台继续计；不跨天累计） */\\n  function clockElapsed(st) {\\n    var ms = st.accumulated || 0;\\n    if (st.running && st.startedAt) {\\n      var now = Date.now();\\n      if (dateStr(new Date(st.startedAt)) === dateStr(new Date(now))) {\\n        ms += Math.max(0, now - st.startedAt);\\n      } else {\\n        var dayStart = new Date(now); dayStart.setHours(0, 0, 0, 0);\\n        ms += Math.max(0, dayStart.getTime() - st.startedAt);\\n      }\\n    }\\n    return Math.max(0, ms);\\n  }\\n  function todayLearnedMin() {\\n    return App.store.checkins.list().filter(function (c) { return c.date === todayStr(); })\\n      .reduce(function (s, c) { return s + (Number(c.durationMin) || 0); }, 0);\\n  }\\n  function streakDays() {\\n    var byDate = {};\\n    App.store.checkins.list().forEach(function (c) {\\n      if (c.date && (Number(c.durationMin) || 0) > 0) byDate[c.date] = true;\\n    });\\n    var d = new Date();\\n    if (!byDate[dateStr(d)]) d.setDate(d.getDate() - 1);\\n    var n = 0;\\n    while (byDate[dateStr(d)]) { n++; d.setDate(d.getDate() - 1); }\\n    return n;\\n  }\\n\\n  var CLOCK_DEF = {\\n    title: \'学习打卡\',\\n    render: function () {\\n      var st = clockState();\\n      var goal = Number(getUI().goalMinutes) || DEFAULT_GOAL_MIN;\\n      var learned = todayLearnedMin();\\n      var pct = Math.min(100, Math.round(learned / goal * 100));\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\"><h2>学习打卡</h2><p class=\\\"page-desc\\\">正计时学习，切走页面也会继续计时</p></div>\\n  <div class=\\\"st-clock-head\\\">\\n    <div class=\\\"ring st-clock-ring\\\" id=\\\"st-clock-ring\\\" style=\\\"--p:${pct}\\\">\\n      <div class=\\\"ring-value\\\">\\n        <div class=\\\"ring-num\\\" id=\\\"st-clock-pct\\\">${pct}%</div>\\n        <div class=\\\"ring-label\\\">今日进度</div>\\n      </div>\\n    </div>\\n    <div class=\\\"st-clock-info\\\">\\n      <div class=\\\"st-clock-goal\\\">今日目标 ${Math.round(goal / 60)}h / 已学 <span id=\\\"st-clock-learned\\\">${fmtHM(learned)}</span></div>\\n      <div class=\\\"st-clock-learned\\\">本次计时：<b id=\\\"st-clock-session\\\">0 分钟</b></div>\\n      <div class=\\\"st-clock-streak\\\">${icon(\'success\', 14)} 已连续打卡 ${streakDays()} 天</div>\\n    </div>\\n  </div>\\n  <section class=\\\"glass-card st-timer-card\\\">\\n    <div class=\\\"st-timer-display\\\" id=\\\"st-timer-display\\\">00:00:00</div>\\n    <div class=\\\"st-timer-state\\\" id=\\\"st-timer-state\\\">准备就绪</div>\\n    <div class=\\\"st-timer-controls\\\">\\n      <button class=\\\"btn btn-primary\\\" id=\\\"st-timer-start\\\">${icon(\'play\', 16)} 开始</button>\\n      <button class=\\\"btn btn-ghost\\\" id=\\\"st-timer-pause\\\" disabled>${icon(\'pause\', 16)} 暂停</button>\\n      <button class=\\\"btn btn-ghost\\\" id=\\\"st-timer-reset\\\" disabled>${icon(\'refresh\', 16)} 重置</button>\\n    </div>\\n  </section>\\n  <section class=\\\"glass-card\\\" style=\\\"padding:18px 20px\\\">\\n    <h3 style=\\\"font-size:0.95rem;margin-bottom:10px\\\">本次计时归入模块（可多选）</h3>\\n    <div class=\\\"st-module-chips\\\" id=\\\"st-module-chips\\\">\\n      ${CLOCK_MODULES.map(function (m) {\\n        return \'<button class=\\\"st-module-chip\\\" data-mod=\\\"\' + esc(m) + \'\\\">\' + esc(m) + \'</button>\';\\n      }).join(\'\')}\\n    </div>\\n  </section>\\n  <section class=\\\"glass-card st-clock-submit\\\" style=\\\"margin-top:16px\\\">\\n    <h3 style=\\\"font-size:0.95rem\\\">今日总结</h3>\\n    <textarea class=\\\"textarea\\\" id=\\\"st-clock-summary\\\" rows=\\\"3\\\" placeholder=\\\"今天学了什么？收获与困惑都可以写在这里…\\\"></textarea>\\n    <div style=\\\"display:flex;justify-content:flex-end\\\">\\n      <button class=\\\"btn btn-primary\\\" id=\\\"st-clock-submit\\\">${icon(\'check\', 16)} 提交打卡</button>\\n    </div>\\n  </section>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var goal = Number(getUI().goalMinutes) || DEFAULT_GOAL_MIN;\\n      var st = clockState();\\n      // 跨天保护：开始时间不是今天的运行中计时自动截断并暂停\\n      if (st.running && st.startedAt && dateStr(new Date(st.startedAt)) !== todayStr()) {\\n        var clamped = clockElapsed(st);\\n        st = { running: false, startedAt: 0, accumulated: clamped, modules: st.modules };\\n        saveClockState(st);\\n      }\\n\\n      var display = el.querySelector(\'#st-timer-display\');\\n      var stateText = el.querySelector(\'#st-timer-state\');\\n      var startBtn = el.querySelector(\'#st-timer-start\');\\n      var pauseBtn = el.querySelector(\'#st-timer-pause\');\\n      var resetBtn = el.querySelector(\'#st-timer-reset\');\\n      var learnedEl = el.querySelector(\'#st-clock-learned\');\\n      var sessionEl = el.querySelector(\'#st-clock-session\');\\n      var pctEl = el.querySelector(\'#st-clock-pct\');\\n      var ring = el.querySelector(\'#st-clock-ring\');\\n      var chipsBox = el.querySelector(\'#st-module-chips\');\\n      var summaryInput = el.querySelector(\'#st-clock-summary\');\\n      var submitBtn = el.querySelector(\'#st-clock-submit\');\\n\\n      // 模块多选\\n      chipsBox.querySelectorAll(\'.st-module-chip\').forEach(function (chip) {\\n        if (st.modules.indexOf(chip.dataset.mod) >= 0) chip.classList.add(\'active\');\\n        chip.addEventListener(\'click\', function () {\\n          chip.classList.toggle(\'active\');\\n          var sel = [];\\n          chipsBox.querySelectorAll(\'.st-module-chip.active\').forEach(function (c) { sel.push(c.dataset.mod); });\\n          st.modules = sel;\\n          saveClockState(st);\\n        });\\n      });\\n\\n      function refresh() {\\n        var elapsed = clockElapsed(st);\\n        display.textContent = fmtClock(elapsed);\\n        sessionEl.textContent = fmtHM(elapsed / 60000);\\n        stateText.textContent = st.running ? \'学习中…（后台继续计时）\' : (elapsed > 0 ? \'已暂停，可继续或提交打卡\' : \'准备就绪\');\\n        startBtn.disabled = st.running;\\n        pauseBtn.disabled = !st.running;\\n        resetBtn.disabled = !st.running && elapsed === 0;\\n        var learned = todayLearnedMin() + (elapsed / 60000);\\n        learnedEl.textContent = fmtHM(learned);\\n        var pct = Math.min(100, Math.round(learned / goal * 100));\\n        pctEl.textContent = pct + \'%\';\\n        if (ring) ring.style.setProperty(\'--p\', pct);\\n      }\\n\\n      startBtn.addEventListener(\'click\', function () {\\n        if (st.running) return;\\n        st.running = true;\\n        st.startedAt = Date.now();\\n        saveClockState(st);\\n        refresh();\\n        App.showToast(\'开始计时，加油！\', \'info\');\\n      });\\n      pauseBtn.addEventListener(\'click\', function () {\\n        if (!st.running) return;\\n        st.accumulated = clockElapsed(st);\\n        st.running = false;\\n        st.startedAt = 0;\\n        saveClockState(st);\\n        refresh();\\n      });\\n      resetBtn.addEventListener(\'click\', function () {\\n        st = { running: false, startedAt: 0, accumulated: 0, modules: st.modules };\\n        saveClockState(st);\\n        refresh();\\n      });\\n      submitBtn.addEventListener(\'click\', function () {\\n        var mins = Math.floor(clockElapsed(st) / 60000);\\n        if (mins < 1) { App.showToast(\'本次计时不足 1 分钟，先学一会儿再打卡吧\', \'warn\'); return; }\\n        var summary = summaryInput.value.trim();\\n        var modules = st.modules.slice();\\n        var today = todayStr();\\n        var existing = App.store.checkins.list().find(function (c) { return c.date === today; });\\n        if (existing) {\\n          var union = (existing.modules || []).slice();\\n          modules.forEach(function (m) { if (union.indexOf(m) < 0) union.push(m); });\\n          App.store.checkins.update(existing.id, {\\n            durationMin: (Number(existing.durationMin) || 0) + mins,\\n            modules: union,\\n            summary: summary || existing.summary || \'\'\\n          });\\n        } else {\\n          App.store.checkins.add({ date: today, durationMin: mins, modules: modules, summary: summary });\\n        }\\n        // 重置计时\\n        st = { running: false, startedAt: 0, accumulated: 0, modules: modules };\\n        saveClockState(st);\\n        summaryInput.value = \'\';\\n        refresh();\\n        App.showToast(\'打卡成功，已记录 \' + mins + \' 分钟\', \'success\');\\n      });\\n\\n      var timer = setInterval(refresh, 500);\\n      el._timer = timer;\\n      refresh();\\n    },\\n    unmount: function () {\\n      var el = document.getElementById(\'content\');\\n      if (el && el._timer) { clearInterval(el._timer); el._timer = null; }\\n    }\\n  };\\n\\n  /* ================================================================\\n     8. 时政积累  /study/current （别名 /study/shizheng）\\n     ================================================================ */\\n\\n  var SHIZHENG_DEF = {\\n    title: \'时政积累\',\\n    render: function () {\\n      var ui = getUI();\\n      var ym = ui.szMonth || todayStr().slice(0, 7);\\n      var tag = ui.szTag || \'\';\\n      var list = App.store.shizheng.list();\\n      var tags = [\'全部\'].concat(SHIZHENG_TAGS);\\n      list.forEach(function (s) {\\n        (s.tags || []).forEach(function (t) { if (tags.indexOf(t) < 0) tags.push(t); });\\n      });\\n      var items = list.filter(function (s) {\\n        if ((s.date || \'\').slice(0, 7) !== ym) return false;\\n        if (tag && (s.tags || []).indexOf(tag) < 0) return false;\\n        return true;\\n      }).sort(function (a, b) { return (b.date || \'\').localeCompare(a.date || \'\'); });\\n      var ymParts = ym.split(\'-\');\\n      return `\\n<div class=\\\"page st-page st-page-fade\\\">\\n  <div class=\\\"page-head\\\" style=\\\"display:flex;align-items:flex-end;justify-content:space-between;gap:12px;flex-wrap:wrap\\\">\\n    <div><h2>时政积累</h2><p class=\\\"page-desc\\\">按月归档，30 天前的条目自动标记「建议回顾」</p></div>\\n    <button class=\\\"btn btn-primary\\\" id=\\\"st-sz-add\\\">${icon(\'plus\', 16)} 录入时政</button>\\n  </div>\\n  <div class=\\\"st-month-nav\\\">\\n    <button class=\\\"btn btn-ghost btn-sm\\\" id=\\\"st-sz-prev\\\">${icon(\'chevron\', 14)}</button>\\n    <span class=\\\"st-month-label\\\" id=\\\"st-sz-month-label\\\">${ymParts[0]} 年 ${Number(ymParts[1])} 月</span>\\n    <button class=\\\"btn btn-ghost btn-sm\\\" id=\\\"st-sz-next\\\">${icon(\'chevron\', 14)}</button>\\n  </div>\\n  <div class=\\\"st-tag-chips\\\" id=\\\"st-sz-tags\\\">\\n    ${tags.map(function (t) {\\n      return \'<button class=\\\"st-module-chip\' + (t === (tag || \'全部\') ? \' active\' : \'\') + \'\\\" data-tag=\\\"\' + esc(t) + \'\\\">\' + esc(t) + \'</button>\';\\n    }).join(\'\')}\\n  </div>\\n  <div class=\\\"st-sz-list\\\" id=\\\"st-sz-list\\\">\\n    ${items.length ? items.map(szCardHTML).join(\'\') : \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'shizheng\', 34) + \'</div><p>该月暂无时政记录，点击右上角录入</p></div>\'}\\n  </div>\\n</div>`;\\n    },\\n    mount: function (el) {\\n      var listBox = el.querySelector(\'#st-sz-list\');\\n      var monthLabel = el.querySelector(\'#st-sz-month-label\');\\n      var ui = getUI();\\n      var ym = ui.szMonth || todayStr().slice(0, 7);\\n      var tag = ui.szTag || \'\';\\n\\n      function setYM(v) {\\n        ym = v;\\n        setUI({ szMonth: v, szTag: tag });\\n        rerender();\\n      }\\n      function rerender() {\\n        App.refresh();\\n      }\\n      el.querySelector(\'#st-sz-prev\').addEventListener(\'click\', function () { setYM(shiftYM(ym, -1)); });\\n      el.querySelector(\'#st-sz-next\').addEventListener(\'click\', function () { setYM(shiftYM(ym, 1)); });\\n\\n      el.querySelector(\'#st-sz-tags\').addEventListener(\'click\', function (e) {\\n        var btn = e.target.closest(\'[data-tag]\');\\n        if (!btn) return;\\n        tag = btn.dataset.tag === \'全部\' ? \'\' : btn.dataset.tag;\\n        setUI({ szMonth: ym, szTag: tag });\\n        rerender();\\n      });\\n\\n      // 展开 / 收起卡片\\n      listBox.addEventListener(\'click\', function (e) {\\n        var card = e.target.closest(\'[data-sz-id]\');\\n        if (card) {\\n          card.classList.toggle(\'expanded\');\\n          var full = card.querySelector(\'.st-sz-full\');\\n          if (full) full.hidden = !full.hidden;\\n        }\\n      });\\n\\n      // 录入时政\\n      el.querySelector(\'#st-sz-add\').addEventListener(\'click\', function () {\\n        openAddShizhengModal(function (date) {\\n          if (date) setYM(String(date).slice(0, 7));\\n          else rerender();\\n        });\\n      });\\n\\n      // 列表切换月份淡入\\n      listBox.style.animation = \'none\';\\n      void listBox.offsetWidth;\\n      listBox.style.animation = \'st-rise 280ms var(--ease)\';\\n    }\\n  };\\n\\n  function szCardHTML(s) {\\n    var today = todayStr();\\n    var review = s.date && s.date < addDaysStr(today, -30);\\n    var tags = (s.tags || []).map(function (t) { return \'<span class=\\\"tag\\\">\' + esc(t) + \'</span>\'; }).join(\'\');\\n    return `\\n<div class=\\\"glass-card st-sz-card\\\" data-sz-id=\\\"${esc(s.id)}\\\">\\n  <div class=\\\"st-sz-title\\\">\\n    <span>${esc(s.title)}</span>\\n    ${review ? \'<span class=\\\"tag tag-warn\\\">建议回顾</span>\' : \'\'}\\n    <span class=\\\"tag tag-accent\\\" style=\\\"margin-left:auto\\\">${icon(\'chevron\', 12)}</span>\\n  </div>\\n  <div class=\\\"st-sz-meta\\\">\\n    <span>${icon(\'file\', 13)} ${esc(s.source || \'未知来源\')}</span>\\n    <span>${icon(\'calendar\', 13)} ${fmtYMD(s.date)}</span>\\n    ${tags}\\n  </div>\\n  <div class=\\\"st-sz-summary\\\">${esc(s.summary || \'\')}</div>\\n  ${s.insight ? \'<div class=\\\"st-sz-insight\\\">我的解读：\' + esc(s.insight) + \'</div>\' : \'\'}\\n  ${s.quote ? \'<div class=\\\"st-sz-quote\\\">\' + esc(s.quote) + \'</div>\' : \'\'}\\n  <div class=\\\"st-sz-full\\\" hidden style=\\\"margin-top:12px\\\">\\n    <div class=\\\"divider\\\" style=\\\"margin-bottom:12px\\\"></div>\\n    <div class=\\\"st-form-hint\\\">${esc(s.summary || \'\')}</div>\\n    ${s.insight ? \'<div class=\\\"st-sz-insight\\\" style=\\\"margin-top:12px\\\">我的解读：\' + esc(s.insight) + \'</div>\' : \'\'}\\n    ${s.quote ? \'<div class=\\\"st-sz-quote\\\" style=\\\"margin-top:12px\\\">\' + esc(s.quote) + \'</div>\' : \'\'}\\n  </div>\\n</div>`;\\n  }\\n\\n  function openAddShizhengModal(onDone) {\\n    var mask = App.openModal(`\\n<div>\\n  <div class=\\\"st-form-grid\\\">\\n    <div class=\\\"st-form-row\\\"><label>标题 *</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"sz-title\\\" placeholder=\\\"时政事件 / 政策标题\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>来源</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"sz-source\\\" placeholder=\\\"如：人民日报\\\"></div>\\n  </div>\\n  <div class=\\\"st-form-grid\\\">\\n    <div class=\\\"st-form-row\\\"><label>日期 *</label><input type=\\\"date\\\" class=\\\"input\\\" id=\\\"sz-date\\\" value=\\\"${todayStr()}\\\"></div>\\n    <div class=\\\"st-form-row\\\"><label>标签（逗号分隔）</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"sz-tags\\\" placeholder=\\\"如：经济, 科技\\\"></div>\\n  </div>\\n  <div class=\\\"st-form-row\\\"><label>原文摘要 *</label><textarea class=\\\"textarea\\\" id=\\\"sz-summary\\\" rows=\\\"3\\\" placeholder=\\\"摘录原文要点…\\\"></textarea></div>\\n  <div class=\\\"st-form-row\\\"><label>个人解读</label><textarea class=\\\"textarea\\\" id=\\\"sz-insight\\\" rows=\\\"2\\\" placeholder=\\\"这条时政怎么用？联系哪些考点…（选填）\\\"></textarea></div>\\n  <div class=\\\"st-form-row\\\"><label>引用金句</label><input type=\\\"text\\\" class=\\\"input\\\" id=\\\"sz-quote\\\" placeholder=\\\"可引用的原话（选填）\\\"></div>\\n</div>`, {\\n      title: \'录入时政\',\\n      confirmText: \'保存\',\\n      cancelText: \'取消\',\\n      onConfirm: function (close) {\\n        var title = mask.querySelector(\'#sz-title\').value.trim();\\n        var date = mask.querySelector(\'#sz-date\').value;\\n        var summary = mask.querySelector(\'#sz-summary\').value.trim();\\n        if (!title) { App.showToast(\'请填写标题\', \'warn\'); return; }\\n        if (!date) { App.showToast(\'请选择日期\', \'warn\'); return; }\\n        if (!summary) { App.showToast(\'请填写原文摘要\', \'warn\'); return; }\\n        var tags = mask.querySelector(\'#sz-tags\').value.split(/[,，、\\\\s]+/).filter(Boolean);\\n        App.store.shizheng.add({\\n          title: title,\\n          source: mask.querySelector(\'#sz-source\').value.trim(),\\n          date: date,\\n          summary: summary,\\n          insight: mask.querySelector(\'#sz-insight\').value.trim(),\\n          quote: mask.querySelector(\'#sz-quote\').value.trim(),\\n          tags: tags\\n        });\\n        close();\\n        App.showToast(\'时政已收录\', \'success\');\\n        if (onDone) onDone(date);\\n      }\\n    });\\n  }\\n\\n  /* ================================================================\\n     注册页面\\n     ================================================================ */\\n\\n  App.registerPage(\'/study\', OVERVIEW_DEF);\\n  App.registerPage(\'/study/knowledge\', TREE_DEF);\\n  App.registerPage(\'/study/knowledge/:id\', DETAIL_DEF); // 字面量契约路径\\n  ensureKnowledgeRoutes(); // 同时为每个知识点 id 注册精确路由（支持直接改 hash 进入）\\n  App.registerPage(\'/study/questions\', QUESTIONS_DEF);\\n  App.registerPage(\'/study/wrong\', WRONG_DEF);\\n  App.registerPage(\'/study/plan\', PLAN_DEF);\\n  App.registerPage(\'/study/plans\', PLAN_DEF); // 与侧边栏 / 搜索一致\\n  App.registerPage(\'/study/clock\', CLOCK_DEF);\\n  App.registerPage(\'/study/checkin\', CLOCK_DEF); // 与首页「开始打卡」一致\\n  App.registerPage(\'/study/current\', SHIZHENG_DEF);\\n  App.registerPage(\'/study/shizheng\', SHIZHENG_DEF); // 与侧边栏 / 搜索一致\\n})();\\n\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 13:31:10');
