(955, '40122540-fcbb-4890-9b07-1296c60efc8f', 130099, 'tool.completed', 'code', 'moonya', 'skeleton', 'call_00_DkjxqOH7AYiZgHMav5Eh5744', '{\"tool_key\":\"edit_file\",\"ok\":false,\"content\":\"未知 command: ，支持 view/str_replace/insert\",\"error\":{\"code\":\"background_command_failed\",\"message\":\"未知 command: ，支持 view/str_replace/insert\"},\"stage\":null,\"status\":null,\"error_code\":\"background_command_failed\",\"command_fingerprint\":null,\"operation_receipt\":null}', '2026-08-03 13:35:54');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
(956, '40122540-fcbb-4890-9b07-1296c60efc8f', 130100, 'tool.started', 'code', 'moonya', 'pages_work', 'call_00_V7WuzfGoBO4awRXiLdZU0081', '{\"tool_key\":\"create_file\",\"display_name\":\"Create File\",\"arguments\":{\"content\":\"/* ==========================================================================\\n   work.js —— 工作区板块（纯 JavaScript，无框架）\\n   --------------------------------------------------------------------------\\n   依赖骨架契约（js/app.js 顶部注释）：\\n     App.registerPage(path, { title, render(path), mount(el, path), unmount() })\\n     App.navigate(path) / App.refresh()\\n     App.store（localStorage 持久化数据层，见 js/store.js）\\n     App.showToast(msg, type) / App.icon(name, size) / App.escapeHtml / App.uid\\n   注意：\\n     - 骨架 router 只做「精确匹配」，未注册路径统一走 \'*\' 兜底页；\\n       因此项目详情 \'/work/projects/:id\' 采用「hashchange 时按需\\n       App.registerPage 精确路径 + App.refresh()」的方式接入完整路由生命周期。\\n     - 骨架 App.openModal 的回调语义为「先关闭弹窗再调用 onConfirm」，\\n       无法在表单校验失败时阻止关闭，故本文件自实现 openModal（复用\\n       style.css 的 modal 系列类），Toast 则直接复用 App.showToast。\\n     - 侧边栏与全局搜索引用 \'/work/logs\'，任务路径为 \'/work/log\'，\\n       两个路径注册到同一页面实现。\\n\\n   数据模型（与 store.js seed 对齐）：\\n     todos:    { id, title, quadrant:\'q1\'..\'q4\', priority, due, done, projectId,\\n                 completedAt?, createdAt }\\n     inbox:    { id, text, urgency, done, createdAt }\\n     projects: { id, name, desc, color, status, sort?, notes?[], files?[], createdAt }\\n     logs:     { id, date:\'yyyy-MM-dd\', content, autoGen?, createdAt }\\n     meetings: { id, title, datetime, attendees[], summary, agenda, decisions,\\n                 todos?[{text,done,linked}], createdAt }\\n   ========================================================================== */\\n(function () {\\n  \'use strict\';\\n\\n  /* ======================= 1. 通用工具 ======================= */\\n\\n  function $(sel, root) { return (root || document).querySelector(sel); }\\n  function $$(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }\\n\\n  function esc(s) {\\n    if (window.App && typeof App.escapeHtml === \'function\') return App.escapeHtml(s);\\n    return String(s == null ? \'\' : s)\\n      .replace(/&/g, \'&amp;\').replace(/</g, \'&lt;\').replace(/>/g, \'&gt;\')\\n      .replace(/\\\"/g, \'&quot;\').replace(/\'/g, \'&#39;\');\\n  }\\n\\n  function pad2(n) { return String(n).padStart(2, \'0\'); }\\n\\n  /** yyyy-MM-dd（本地时区） */\\n  function dateStr(d) {\\n    return d.getFullYear() + \'-\' + pad2(d.getMonth() + 1) + \'-\' + pad2(d.getDate());\\n  }\\n\\n  function todayStr() { return dateStr(new Date()); }\\n\\n  function daysFromNow(n) {\\n    var d = new Date();\\n    d.setDate(d.getDate() + n);\\n    return dateStr(d);\\n  }\\n\\n  /** \'yyyy-MM-dd\' 的友好显示：今天 / 明天 / 昨天 / M月D日 */\\n  function dueText(s) {\\n    if (!s) return \'\';\\n    var t = todayStr();\\n    if (s === t) return \'今天\';\\n    if (s === daysFromNow(1)) return \'明天\';\\n    if (s === daysFromNow(-1)) return \'昨天\';\\n    var p = s.split(\'-\');\\n    return (p[1] ? parseInt(p[1], 10) : 0) + \'月\' + (p[2] ? parseInt(p[2], 10) : 0) + \'日\';\\n  }\\n\\n  /** 录入时间友好显示 */\\n  function timeText(isoOrDate) {\\n    if (!isoOrDate) return \'\';\\n    var t = isoOrDate;\\n    var d = new Date(t.indexOf(\'T\') >= 0 ? t : t.replace(/-/g, \'/\'));\\n    if (isNaN(d.getTime())) return String(t);\\n    var now = new Date();\\n    var hm = pad2(d.getHours()) + \':\' + pad2(d.getMinutes());\\n    var ds = dateStr(d);\\n    if (ds === dateStr(now)) return \'今天 \' + hm;\\n    if (ds === daysFromNow(-1)) return \'昨天 \' + hm;\\n    return (d.getMonth() + 1) + \'月\' + d.getDate() + \'日 \' + hm;\\n  }\\n\\n  /** ISO 时间 → HH:mm（本地） */\\n  function hmOf(iso) {\\n    var d = new Date(iso);\\n    if (isNaN(d.getTime())) return \'\';\\n    return pad2(d.getHours()) + \':\' + pad2(d.getMinutes());\\n  }\\n\\n  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }\\n\\n  function debounce(fn, ms) {\\n    var timer = null;\\n    return function () {\\n      var args = arguments, self = this;\\n      clearTimeout(timer);\\n      timer = setTimeout(function () { fn.apply(self, args); }, ms);\\n    };\\n  }\\n\\n  /** 当前 hash 路径（与 router.parsePath 一致的规范化） */\\n  function currentHashPath() {\\n    var p = (location.hash || \'\').replace(/^#/, \'\');\\n    if (!p || p === \'/\') p = \'/home\';\\n    if (p.charAt(0) !== \'/\') p = \'/\' + p;\\n    if (p.length > 1) {\\n      while (p.length > 1 && p.charAt(p.length - 1) === \'/\') p = p.slice(0, -1);\\n    }\\n    return p;\\n  }\\n\\n  function routerCurrent() {\\n    try {\\n      if (window.WorkbenchRouter && typeof window.WorkbenchRouter.current === \'function\') {\\n        return window.WorkbenchRouter.current() || currentHashPath();\\n      }\\n    } catch (e) { /* ignore */ }\\n    return currentHashPath();\\n  }\\n\\n  /* ======================= 2. 图标 ======================= */\\n\\n  /* 骨架符号表中已有的图标名（index.html SVG 符号表） */\\n  var APP_ICON_NAMES = {\\n    check: 1, inbox: 1, folder: 1, calendar: 1, todo: 1, clock: 1, pen: 1,\\n    trash: 1, plus: 1, close: 1, chevron: 1, search: 1, gear: 1, file: 1,\\n    download: 1, upload: 1, warn: 1, info: 1, success: 1, error: 1,\\n    refresh: 1, users: 1, log: 1, meeting: 1, work: 1\\n  };\\n\\n  /* 符号表之外的补充图标（自绘，风格与骨架一致） */\\n  var EXTRA_ICONS = {\\n    grip: \'<g fill=\\\"currentColor\\\" stroke=\\\"none\\\"><circle cx=\\\"9\\\" cy=\\\"5.5\\\" r=\\\"1.1\\\"/><circle cx=\\\"15\\\" cy=\\\"5.5\\\" r=\\\"1.1\\\"/><circle cx=\\\"9\\\" cy=\\\"12\\\" r=\\\"1.1\\\"/><circle cx=\\\"15\\\" cy=\\\"12\\\" r=\\\"1.1\\\"/><circle cx=\\\"9\\\" cy=\\\"18.5\\\" r=\\\"1.1\\\"/><circle cx=\\\"15\\\" cy=\\\"18.5\\\" r=\\\"1.1\\\"/></g>\',\\n    back: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M14.5 5.5 8 12l6.5 6.5\\\"/></g>\',\\n    chevL: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M14.5 6.5 9 12l5.5 5.5\\\"/></g>\',\\n    chevR: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M9.5 6.5 15 12l-5.5 5.5\\\"/></g>\',\\n    archive: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M4 8.5h16v11a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1z\\\"/><path d=\\\"M3 4.5h18v4H3z\\\"/><path d=\\\"M9.5 12h5\\\"/></g>\',\\n    up: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M12 19V5.5\\\"/><path d=\\\"M5.5 12 12 5.5 18.5 12\\\"/></g>\',\\n    link: \'<g fill=\\\"none\\\" stroke=\\\"currentColor\\\" stroke-width=\\\"1.7\\\" stroke-linecap=\\\"round\\\" stroke-linejoin=\\\"round\\\"><path d=\\\"M10.5 13.5 13.5 10.5a3 3 0 0 1 4.2 4.2l-3 3a3 3 0 0 1-4.2-4.2\\\"/><path d=\\\"M13.5 10.5 10.5 13.5a3 3 0 0 0 4.2 4.2l3-3a3 3 0 0 0-4.2-4.2\\\"/></g>\'\\n  };\\n\\n  /** 统一图标入口：优先骨架符号表，缺失用自绘补充 */\\n  function icon(name, size) {\\n    var s = size || 18;\\n    if (APP_ICON_NAMES[name] && window.App && typeof App.icon === \'function\') {\\n      try {\\n        var svg = App.icon(name, s);\\n        if (svg && svg.indexOf(\'<svg\') >= 0) return svg;\\n      } catch (e) { /* fallthrough */ }\\n    }\\n    if (EXTRA_ICONS[name]) {\\n      return \'<svg class=\\\"icon\\\" width=\\\"\' + s + \'\\\" height=\\\"\' + s + \'\\\" viewBox=\\\"0 0 24 24\\\" aria-hidden=\\\"true\\\">\' +\\n        EXTRA_ICONS[name] + \'</svg>\';\\n    }\\n    return \'\';\\n  }\\n\\n  /* ======================= 3. 页面级样式注入 ======================= */\\n\\n  var STYLE = \'\' +\\n    \'.work-page{animation:work-slide-in 280ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'@keyframes work-slide-in{from{opacity:0;transform:translateX(26px)}to{opacity:1;transform:none}}\' +\\n\\n    /* ---- 总览 ---- */\\n    \'.work-ov-head{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;margin-bottom:18px;flex-wrap:wrap}\' +\\n    \'.work-ov-head h2{font-size:1.5rem;font-weight:700}\' +\\n    \'.work-ov-date{color:var(--text-3);font-size:0.9rem;margin-top:2px}\' +\\n    \'.work-ov-stats{display:flex;gap:10px}\' +\\n    \'.work-ov-stat{padding:8px 16px;border-radius:12px;background:var(--card);border:1px solid var(--border);font-size:0.88rem;color:var(--text-2)}\' +\\n    \'.work-ov-stat b{color:var(--accent);font-size:1.05rem;margin-right:4px}\' +\\n    \'.work-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}\' +\\n    \'@media(max-width:980px){.work-grid{grid-template-columns:repeat(2,1fr)}}\' +\\n    \'@media(max-width:560px){.work-grid{grid-template-columns:1fr}}\' +\\n    \'.work-card{position:relative;padding:22px 18px;border-radius:var(--radius-lg);cursor:pointer;display:flex;flex-direction:column;gap:10px;overflow:hidden;transform:translateY(0);transition:transform 280ms cubic-bezier(0.25,0.6,0.3,1),box-shadow 280ms cubic-bezier(0.25,0.6,0.3,1),background-color 300ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-lg);background:var(--card-hover)}\' +\\n    \'.work-card:active{transform:translateY(-1px)}\' +\\n    \'.work-card-icon{width:46px;height:46px;border-radius:13px;display:grid;place-items:center;color:#fff;background:var(--accent);box-shadow:0 6px 16px var(--accent-shadow)}\' +\\n    \'.work-card:nth-child(2) .work-card-icon{background:var(--success);box-shadow:0 6px 16px rgba(108,145,112,0.32)}\' +\\n    \'.work-card:nth-child(3) .work-card-icon{background:var(--warn);box-shadow:0 6px 16px rgba(196,147,56,0.32)}\' +\\n    \'.work-card:nth-child(4) .work-card-icon{background:#8a7a6a;box-shadow:0 6px 16px rgba(138,122,106,0.32)}\' +\\n    \'.work-card-name{font-weight:650;font-size:1rem}\' +\\n    \'.work-card-desc{color:var(--text-3);font-size:0.82rem;line-height:1.5}\' +\\n    \'.work-card-badge{position:absolute;top:14px;right:14px;min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:var(--accent);color:#fff;font-size:0.72rem;display:inline-flex;align-items:center;justify-content:center;font-weight:600;transition:transform 240ms cubic-bezier(0.34,1.2,0.4,1)}\' +\\n    \'.work-card-badge.pulse{transform:scale(1.18)}\' +\\n\\n    /* ---- 今日待办 ---- */\\n    \'.work-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;flex-wrap:wrap}\' +\\n    \'.work-bar-left{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\' +\\n    \'.work-bar-right{display:flex;align-items:center;gap:10px}\' +\\n    \'.work-quad-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;align-items:start}\' +\\n    \'@media(max-width:820px){.work-quad-grid{grid-template-columns:1fr}}\' +\\n    \'.work-quad{background:var(--card);-webkit-backdrop-filter:blur(16px) saturate(1.15);backdrop-filter:blur(16px) saturate(1.15);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow);padding:14px 14px 10px;min-height:150px;transition:border-color 260ms cubic-bezier(0.25,0.6,0.3,1),box-shadow 260ms cubic-bezier(0.25,0.6,0.3,1),background-color 300ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-quad.drag-over{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}\' +\\n    \'.work-quad.drop-flash{border-color:var(--accent);box-shadow:0 0 0 4px var(--accent-soft),var(--shadow)}\' +\\n    \'.work-quad-head{display:flex;align-items:center;gap:8px;margin-bottom:10px;padding:0 4px}\' +\\n    \'.work-quad-chip{width:9px;height:9px;border-radius:3px;flex-shrink:0}\' +\\n    \'.work-quad-title{font-weight:650;font-size:0.92rem}\' +\\n    \'.work-quad-count{margin-left:auto;font-size:0.76rem;color:var(--text-3);background:var(--card-hover);padding:1px 8px;border-radius:999px}\' +\\n    \'.work-quad-body{min-height:60px}\' +\\n    \'.work-todo-row{display:flex;align-items:center;gap:9px;padding:8px 10px;margin-bottom:8px;border-radius:10px;background:var(--card-strong);border:1px solid var(--border);transition:opacity 300ms cubic-bezier(0.25,0.6,0.3,1),transform 300ms cubic-bezier(0.25,0.6,0.3,1),max-height 300ms cubic-bezier(0.25,0.6,0.3,1),background-color 200ms cubic-bezier(0.25,0.6,0.3,1);max-height:80px;overflow:hidden;user-select:none}\' +\\n    \'.work-todo-row:hover{background:var(--card-hover)}\' +\\n    \'.work-todo-row.dragging{opacity:0.35;transform:scale(0.98)}\' +\\n    \'.work-todo-row.leaving{opacity:0;transform:translateX(34px);max-height:0;margin-bottom:0;padding-top:0;padding-bottom:0;border-width:0}\' +\\n    \'.work-todo-row .work-todo-check{width:17px;height:17px;accent-color:var(--success);cursor:pointer;flex-shrink:0}\' +\\n    \'.work-todo-title{flex:1;min-width:0;font-size:0.92rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color 260ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-todo-row.done .work-todo-title{color:var(--text-3);text-decoration:line-through}\' +\\n    \'.work-prio{width:8px;height:8px;border-radius:50%;flex-shrink:0}\' +\\n    \'.work-prio.high{background:var(--danger)}.work-prio.mid{background:var(--warn)}.work-prio.low{background:var(--text-3)}\' +\\n    \'.work-due{font-size:0.78rem;color:var(--text-3);flex-shrink:0;white-space:nowrap}\' +\\n    \'.work-due.today{color:var(--accent);font-weight:600}\' +\\n    \'.work-due.overdue{color:var(--danger)}\' +\\n    \'.work-drag-handle{cursor:grab;color:var(--text-3);display:grid;place-items:center;flex-shrink:0;border-radius:6px;padding:2px;touch-action:none}\' +\\n    \'.work-drag-handle:active{cursor:grabbing}\' +\\n    \'.work-done-fold{margin:6px 4px 2px;border-top:1px dashed var(--border-strong);padding-top:6px}\' +\\n    \'.work-done-fold summary{cursor:pointer;font-size:0.8rem;color:var(--text-3);user-select:none;list-style:none;display:flex;align-items:center;gap:6px}\' +\\n    \'.work-done-fold summary::-webkit-details-marker{display:none}\' +\\n    \'.work-done-fold .chev{transition:transform 240ms cubic-bezier(0.25,0.6,0.3,1);color:var(--text-3)}\' +\\n    \'.work-done-fold[open] .chev{transform:rotate(180deg)}\' +\\n    \'.work-quick-add{position:sticky;bottom:14px;margin-top:18px;display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:var(--radius);background:var(--card-strong);-webkit-backdrop-filter:blur(20px) saturate(1.2);backdrop-filter:blur(20px) saturate(1.2);border:1px solid var(--border-strong);box-shadow:var(--shadow-lg);z-index:10}\' +\\n    \'.work-quick-add .input{border:none;background:transparent;box-shadow:none;padding:6px 4px}\' +\\n    \'.work-quick-add .input:focus{box-shadow:none}\' +\\n    \'.work-quick-add .work-quick-tip{font-size:0.72rem;color:var(--text-3);flex-shrink:0}\' +\\n    \'.work-quad-empty{padding:22px 10px;text-align:center;color:var(--text-3);font-size:0.82rem}\' +\\n\\n    /* ---- 收件箱 ---- */\\n    \'.work-inbox-list{display:flex;flex-direction:column;gap:10px}\' +\\n    \'.work-inbox-card{position:relative;border-radius:var(--radius);overflow:hidden;border:1px solid var(--border);background:var(--card-strong);box-shadow:var(--shadow);transition:background-color 300ms cubic-bezier(0.25,0.6,0.3,1),border-color 300ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-inbox-ribbon{position:absolute;left:0;top:0;bottom:0;width:4px}\' +\\n    \'.work-ribbon.high{background:var(--danger)}.work-ribbon.mid{background:var(--warn)}.work-ribbon.low{background:var(--text-3)}\' +\\n    \'.work-inbox-actions{position:absolute;right:0;top:0;bottom:0;display:flex;align-items:stretch;gap:0;z-index:1}\' +\\n    \'.work-inbox-act{width:76px;border:none;color:#fff;font-size:0.78rem;cursor:pointer;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;transition:filter 200ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-inbox-act:hover{filter:brightness(1.1)}\' +\\n    \'.work-inbox-act.up{background:var(--success)}\' +\\n    \'.work-inbox-act.del{background:var(--danger)}\' +\\n    \'.work-inbox-card-inner{position:relative;z-index:2;display:flex;align-items:flex-start;gap:12px;padding:13px 16px 13px 20px;background:var(--card-strong);transition:transform 280ms cubic-bezier(0.25,0.6,0.3,1);cursor:pointer;user-select:none;touch-action:pan-y}\' +\\n    \'.work-inbox-card.open .work-inbox-card-inner{transform:translateX(-152px)}\' +\\n    \'.work-inbox-text{flex:1;min-width:0;font-size:0.94rem;line-height:1.6;word-break:break-word}\' +\\n    \'.work-inbox-card.done .work-inbox-text{color:var(--text-3);text-decoration:line-through}\' +\\n    \'.work-inbox-time{font-size:0.76rem;color:var(--text-3);flex-shrink:0;padding-top:2px}\' +\\n    \'.work-hint{display:flex;align-items:center;gap:10px;padding:11px 16px;margin-bottom:14px;border-radius:12px;background:var(--warn-soft);border:1px solid rgba(196,147,56,0.25);color:var(--warn);font-size:0.88rem;animation:work-hint-in 300ms cubic-bezier(0.34,1.2,0.4,1)}\' +\\n    \'@keyframes work-hint-in{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}\' +\\n    \'.work-hint .close{width:24px;height:24px;display:grid;place-items:center;border:none;background:transparent;color:inherit;cursor:pointer;margin-left:auto;border-radius:6px}\' +\\n    \'.work-hint .close:hover{background:rgba(196,147,56,0.18)}\' +\\n\\n    /* ---- 项目列表 ---- */\\n    \'.work-proj-list{display:flex;flex-direction:column;gap:12px}\' +\\n    \'.work-proj-card{display:flex;align-items:center;gap:14px;padding:16px 18px;border-radius:var(--radius);cursor:pointer;transition:transform 280ms cubic-bezier(0.25,0.6,0.3,1),box-shadow 280ms cubic-bezier(0.25,0.6,0.3,1),background-color 300ms cubic-bezier(0.25,0.6,0.3,1),opacity 260ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-proj-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-lg)}\' +\\n    \'.work-proj-card.dragging{opacity:0.4}\' +\\n    \'.work-proj-color{width:38px;height:38px;border-radius:11px;flex-shrink:0;display:grid;place-items:center;color:#fff;font-weight:700;font-size:1rem}\' +\\n    \'.work-proj-main{flex:1;min-width:0}\' +\\n    \'.work-proj-name{font-weight:650;font-size:0.98rem;display:flex;align-items:center;gap:8px;overflow:hidden}\' +\\n    \'.work-proj-name>span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\' +\\n    \'.work-proj-desc{color:var(--text-3);font-size:0.84rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px}\' +\\n    \'.work-proj-meta{display:flex;align-items:center;gap:8px;margin-top:6px;flex-wrap:wrap}\' +\\n    \'.work-proj-count{font-size:0.78rem;color:var(--text-2);background:var(--card-hover);padding:1px 9px;border-radius:999px}\' +\\n    \'.work-proj-grip{margin-left:auto;color:var(--text-3);cursor:grab;padding:6px;border-radius:8px;flex-shrink:0;touch-action:none}\' +\\n    \'.work-proj-grip:active{cursor:grabbing}\' +\\n    \'.work-proj-sort-hint{position:fixed;border:1.5px dashed var(--accent);border-radius:var(--radius);background:var(--accent-soft);opacity:0.6;pointer-events:none;z-index:50;transition:top 120ms linear,height 120ms linear}\' +\\n    \'.work-archived-head{display:flex;align-items:center;gap:8px;margin:22px 0 10px;font-size:0.86rem;color:var(--text-3);cursor:pointer;user-select:none}\' +\\n    \'.work-archived-head .chev{transition:transform 240ms cubic-bezier(0.25,0.6,0.3,1);color:var(--text-3)}\' +\\n    \'.work-archived-head.open .chev{transform:rotate(180deg)}\' +\\n\\n    /* ---- 项目详情 ---- */\\n    \'.work-detail-head{display:flex;align-items:center;gap:12px;margin-bottom:16px}\' +\\n    \'.work-detail-head h2{flex:1;min-width:0;font-size:1.3rem;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\' +\\n    \'.work-info-card{padding:16px 18px;margin-bottom:16px;display:flex;flex-direction:column;gap:8px}\' +\\n    \'.work-info-row{display:flex;align-items:flex-start;gap:10px;font-size:0.9rem}\' +\\n    \'.work-info-row .lbl{color:var(--text-3);font-size:0.82rem;width:56px;flex-shrink:0;padding-top:2px}\' +\\n    \'.work-info-row .val{min-width:0;word-break:break-word}\' +\\n    \'.work-tabs{position:relative;display:flex;gap:2px;margin-bottom:16px;border-bottom:1px solid var(--border)}\' +\\n    \'.work-tab{padding:10px 18px;border:none;background:transparent;color:var(--text-2);font-size:0.95rem;cursor:pointer;position:relative;z-index:1;transition:color 240ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-tab.active{color:var(--accent);font-weight:600}\' +\\n    \'.work-tab-indicator{position:absolute;bottom:-1px;left:0;height:2.5px;border-radius:2px;background:var(--accent);transition:transform 300ms cubic-bezier(0.25,0.6,0.3,1),width 300ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-note-item{padding:13px 16px;border-radius:var(--radius-sm);background:var(--card);border:1px solid var(--border);margin-bottom:9px;cursor:pointer;transition:background-color 260ms cubic-bezier(0.25,0.6,0.3,1),border-color 260ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-note-item:hover{background:var(--card-hover);border-color:var(--accent-soft)}\' +\\n    \'.work-note-head{display:flex;align-items:center;gap:8px}\' +\\n    \'.work-note-title{font-weight:600;font-size:0.93rem;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\' +\\n    \'.work-note-time{font-size:0.76rem;color:var(--text-3);flex-shrink:0}\' +\\n    \'.work-note-body{max-height:0;overflow:hidden;transition:max-height 320ms cubic-bezier(0.25,0.6,0.3,1);font-size:0.9rem;color:var(--text-2);line-height:1.8;white-space:pre-wrap}\' +\\n    \'.work-note-item.open .work-note-body{max-height:600px;margin-top:10px}\' +\\n    \'.work-note-item .chev{transition:transform 260ms cubic-bezier(0.25,0.6,0.3,1);color:var(--text-3);flex-shrink:0}\' +\\n    \'.work-note-item.open .chev{transform:rotate(180deg)}\' +\\n    \'.work-file-item{display:flex;align-items:center;gap:12px;padding:12px 16px;border-radius:var(--radius-sm);background:var(--card);border:1px solid var(--border);margin-bottom:9px;cursor:pointer;transition:background-color 260ms cubic-bezier(0.25,0.6,0.3,1),border-color 260ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-file-item:hover{background:var(--card-hover);border-color:var(--accent-soft)}\' +\\n    \'.work-file-icon{width:38px;height:38px;border-radius:10px;background:var(--accent-soft);color:var(--accent);display:grid;place-items:center;flex-shrink:0}\' +\\n    \'.work-file-main{flex:1;min-width:0}\' +\\n    \'.work-file-name{font-size:0.92rem;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\' +\\n    \'.work-file-meta{font-size:0.76rem;color:var(--text-3);margin-top:2px}\' +\\n    \'.work-fab{position:sticky;bottom:14px;display:flex;justify-content:flex-end;gap:10px;margin-top:16px;z-index:10}\' +\\n    \'.work-fab .btn{box-shadow:var(--shadow-lg)}\' +\\n\\n    /* ---- 工作日志 ---- */\\n    \'.work-log-layout{display:grid;grid-template-columns:1fr 230px;gap:16px;align-items:start}\' +\\n    \'@media(max-width:860px){.work-log-layout{grid-template-columns:1fr}}\' +\\n    \'.work-log-picker{display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:16px}\' +\\n    \'.work-log-picker .date-main{font-size:1.12rem;font-weight:650;min-width:200px;text-align:center;line-height:1.4}\' +\\n    \'.work-log-picker .date-sub{display:block;font-size:0.8rem;color:var(--text-3);font-weight:400;margin-top:2px}\' +\\n    \'.work-log-body{min-height:200px;padding:16px 18px;white-space:pre-wrap;line-height:1.9;font-size:0.95rem}\' +\\n    \'.work-log-edit{width:100%;min-height:220px;border:none;background:transparent;resize:vertical;font-family:inherit;font-size:0.95rem;line-height:1.9;color:var(--text);outline:none;padding:4px}\' +\\n    \'.work-toolbar{display:flex;gap:10px;margin-top:14px;flex-wrap:wrap}\' +\\n    \'.work-timeline{position:relative;padding:6px 0 6px 18px}\' +\\n    \'.work-timeline::before{content:\\\"\\\";position:absolute;left:5px;top:8px;bottom:8px;width:2px;background:var(--border-strong);border-radius:2px}\' +\\n    \'.work-tl-node{position:relative;padding:0 0 18px 14px}\' +\\n    \'.work-tl-node::before{content:\\\"\\\";position:absolute;left:-16px;top:5px;width:10px;height:10px;border-radius:50%;background:var(--success);border:2px solid var(--bg-0);box-shadow:0 0 0 2px var(--success-soft)}\' +\\n    \'.work-tl-time{font-size:0.76rem;color:var(--success);font-weight:600}\' +\\n    \'.work-tl-text{font-size:0.84rem;color:var(--text-2);margin-top:2px;line-height:1.5;word-break:break-word}\' +\\n    \'.work-tl-empty{color:var(--text-3);font-size:0.82rem;line-height:1.7}\' +\\n\\n    /* ---- 会议记录 ---- */\\n    \'.work-meet-list{display:flex;flex-direction:column;gap:12px}\' +\\n    \'.work-meet-card{border-radius:var(--radius);overflow:hidden;transition:background-color 300ms cubic-bezier(0.25,0.6,0.3,1),border-color 300ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-meet-head{display:flex;align-items:flex-start;gap:12px;padding:15px 18px;cursor:pointer;user-select:none}\' +\\n    \'.work-meet-title{font-weight:650;font-size:0.98rem;flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\' +\\n    \'.work-meet-sub{display:flex;align-items:center;gap:14px;margin-top:5px;flex-wrap:wrap}\' +\\n    \'.work-meet-dt{font-size:0.8rem;color:var(--text-2);display:flex;align-items:center;gap:5px}\' +\\n    \'.work-meet-avatars{display:flex;align-items:center}\' +\\n    \'.work-avatar{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;color:#fff;font-size:0.72rem;font-weight:600;flex-shrink:0;border:2px solid var(--card-strong);margin-left:-6px}\' +\\n    \'.work-avatar:first-child{margin-left:0}\' +\\n    \'.work-meet-summary{font-size:0.84rem;color:var(--text-2);margin-top:7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.6}\' +\\n    \'.work-meet-body{max-height:0;overflow:hidden;transition:max-height 340ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-meet-card.open .work-meet-body{max-height:900px}\' +\\n    \'.work-meet-body-inner{padding:2px 18px 18px;border-top:1px solid var(--border)}\' +\\n    \'.work-meet-sec{margin-top:12px}\' +\\n    \'.work-meet-sec h4{font-size:0.82rem;color:var(--accent);margin-bottom:6px;display:flex;align-items:center;gap:6px}\' +\\n    \'.work-meet-sec p,.work-meet-sec li{font-size:0.9rem;color:var(--text-2);line-height:1.7}\' +\\n    \'.work-meet-sec ul{padding-left:18px}\' +\\n    \'.work-meet-todo{display:flex;align-items:center;gap:9px;padding:7px 10px;border-radius:9px;background:var(--card);margin-bottom:6px;font-size:0.9rem}\' +\\n    \'.work-meet-todo .txt{flex:1;min-width:0;color:var(--text-2)}\' +\\n    \'.work-meet-todo.done .txt{color:var(--text-3);text-decoration:line-through}\' +\\n    \'.work-meet-todo .link-btn{font-size:0.76rem;padding:3px 10px;border-radius:8px;border:1px solid var(--border-strong);background:transparent;color:var(--success);cursor:pointer;flex-shrink:0;transition:all 220ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-meet-todo .link-btn:hover{background:var(--success-soft);border-color:transparent}\' +\\n    \'.work-meet-todo .linked{font-size:0.76rem;color:var(--text-3);flex-shrink:0}\' +\\n    \'.work-meet-head .chev{color:var(--text-3);transition:transform 260ms cubic-bezier(0.25,0.6,0.3,1);flex-shrink:0;margin-top:2px}\' +\\n    \'.work-meet-card.open .work-meet-head .chev{transform:rotate(180deg)}\' +\\n\\n    /* ---- 长按菜单 / 表单 ---- */\\n    \'.work-menu{position:fixed;z-index:400;min-width:168px;padding:6px;border-radius:12px;background:var(--card-strong);-webkit-backdrop-filter:blur(22px) saturate(1.2);backdrop-filter:blur(22px) saturate(1.2);border:1px solid var(--border-strong);box-shadow:var(--shadow-lg);animation:work-menu-in 220ms cubic-bezier(0.34,1.2,0.4,1)}\' +\\n    \'@keyframes work-menu-in{from{opacity:0;transform:scale(0.94) translateY(-4px)}to{opacity:1;transform:none}}\' +\\n    \'.work-menu-item{display:flex;align-items:center;gap:9px;width:100%;padding:9px 12px;border:none;background:transparent;border-radius:8px;color:var(--text);font-size:0.9rem;cursor:pointer;text-align:left;transition:background 180ms cubic-bezier(0.25,0.6,0.3,1),color 180ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-menu-item:hover{background:var(--card-hover)}\' +\\n    \'.work-menu-item.danger{color:var(--danger)}\' +\\n    \'.work-menu-item.danger:hover{background:var(--danger-soft)}\' +\\n    \'.work-menu-item .icon{color:var(--text-3)}\' +\\n    \'.work-menu-item.danger .icon{color:var(--danger)}\' +\\n    \'.work-form-row{margin-bottom:13px}\' +\\n    \'.work-form-row label{display:block;font-size:0.82rem;color:var(--text-2);margin-bottom:5px}\' +\\n    \'.work-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}\' +\\n    \'@media(max-width:560px){.work-form-grid{grid-template-columns:1fr}}\' +\\n    \'.work-form-row .required::after{content:\\\" *\\\";color:var(--danger)}\' +\\n    \'.work-color-row{display:flex;gap:8px;flex-wrap:wrap}\' +\\n    \'.work-color-dot{width:26px;height:26px;border-radius:8px;cursor:pointer;border:2px solid transparent;transition:transform 220ms cubic-bezier(0.25,0.6,0.3,1),border-color 220ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'.work-color-dot:hover{transform:scale(1.12)}\' +\\n    \'.work-color-dot.active{border-color:var(--text);transform:scale(1.12)}\' +\\n    \'.work-tag-dot{width:8px;height:8px;border-radius:50%;display:inline-block;flex-shrink:0}\' +\\n    \'.work-tag-color{display:inline-flex;align-items:center;gap:5px;padding:2px 10px;border-radius:999px;font-size:0.78rem;border:1px solid transparent}\' +\\n    \'.work-preview{width:100%;min-height:200px;max-height:44vh;overflow:auto;padding:14px 16px;border-radius:10px;border:1px solid var(--border);background:var(--card);font-size:0.9rem;line-height:1.85;white-space:pre-wrap;color:var(--text)}\' +\\n    \'.work-picker-row{display:flex;gap:10px;align-items:center;margin-bottom:12px}\' +\\n    \'.work-picker-row label{font-size:0.82rem;color:var(--text-2);flex-shrink:0}\' +\\n    \'.work-picker-row .input{flex:1}\' +\\n    \'.work-tabpanel{animation:work-panel-in 260ms cubic-bezier(0.25,0.6,0.3,1)}\' +\\n    \'@keyframes work-panel-in{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}\' +\\n    \'.work-file-input{display:none}\';\\n\\n  if (!document.getElementById(\'work-page-style\')) {\\n    var styleEl = document.createElement(\'style\');\\n    styleEl.id = \'work-page-style\';\\n    styleEl.textContent = STYLE;\\n    (document.head || document.documentElement).appendChild(styleEl);\\n  }\\n\\n  /* ======================= 4. 数据层访问 ======================= */\\n\\n  function storeReady() {\\n    return !!(window.App && window.App.store &&\\n      window.App.store.todos && window.App.store.inbox &&\\n      window.App.store.projects && window.App.store.logs &&\\n      window.App.store.meetings);\\n  }\\n\\n  function getTodos() { return window.App.store.todos.list(); }\\n  function getInbox() { return window.App.store.inbox.list(); }\\n  function getProjects() { return window.App.store.projects.list(); }\\n  function getLogs() { return window.App.store.logs.list(); }\\n  function getMeetings() { return window.App.store.meetings.list(); }\\n\\n  function sortProjects(list) {\\n    return list\\n      .map(function (p, i) { return { p: p, order: (p.sort == null ? 10000 + i : p.sort) }; })\\n      .sort(function (a, b) { return a.order - b.order; })\\n      .map(function (x) { return x.p; });\\n  }\\n\\n  var QUADRANTS = [\\n    { id: \'q1\', label: \'重要紧急\', color: \'#bd5c4c\', soft: \'rgba(189,92,76,0.14)\' },\\n    { id: \'q2\', label: \'重要不紧急\', color: \'#6c9170\', soft: \'rgba(108,145,112,0.14)\' },\\n    { id: \'q3\', label: \'紧急不重要\', color: \'#c49338\', soft: \'rgba(196,147,56,0.14)\' },\\n    { id: \'q4\', label: \'不重要不紧急\', color: \'#8a857c\', soft: \'rgba(138,133,124,0.16)\' }\\n  ];\\n\\n  function quadInfo(id) {\\n    for (var i = 0; i < QUADRANTS.length; i++) if (QUADRANTS[i].id === id) return QUADRANTS[i];\\n    return QUADRANTS[0];\\n  }\\n\\n  var PRIO_LABEL = { high: \'高\', mid: \'中\', low: \'低\' };\\n  var PRIO_URGENCY = { high: \'high\', mid: \'mid\', low: \'low\' };\\n\\n  var PROJ_COLORS = [\'#b06f47\', \'#6c9170\', \'#c49338\', \'#8a7a6a\', \'#a06a5c\', \'#5f7d8c\'];\\n  var PROJ_STATUS = {\\n    active: { label: \'进行中\', cls: \'tag-success\' },\\n    paused: { label: \'暂停\', cls: \'tag-warn\' },\\n    done: { label: \'已完结\', cls: \'tag-accent\' },\\n    archived: { label: \'已归档\', cls: \'tag-danger\' }\\n  };\\n\\n  var AVATAR_COLORS = [\'#b06f47\', \'#6c9170\', \'#c49338\', \'#a06a5c\', \'#5f7d8c\', \'#8a7a6a\'];\\n\\n  /* ======================= 5. 通用 UI 助手 ======================= */\\n\\n  function uiToast(msg, type) {\\n    if (window.App && typeof App.showToast === \'function\') {\\n      try { App.showToast(msg, type || \'info\'); return; } catch (e) { /* fallthrough */ }\\n    }\\n  }\\n\\n  /* ---- 自实现模态框（复用 style.css 的 modal 系列类） ---- */\\n  var modalStack = [];\\n  var modalEscCleanup = null;\\n\\n  function openModal(opts) {\\n    var root = document.getElementById(\'modal-root\') || $(\'.modal-root\');\\n    if (!root) {\\n      root = document.createElement(\'div\');\\n      root.className = \'modal-root\';\\n      root.id = \'modal-root\';\\n      document.body.appendChild(root);\\n    }\\n    var mask = document.createElement(\'div\');\\n    mask.className = \'modal-mask\';\\n    var modal = document.createElement(\'div\');\\n    modal.className = \'modal\';\\n    modal.setAttribute(\'role\', \'dialog\');\\n    modal.setAttribute(\'aria-modal\', \'true\');\\n    modal.innerHTML =\\n      \'<div class=\\\"modal-head\\\"><h3>\' + esc(opts.title || \'提示\') + \'</h3>\' +\\n      \'<button class=\\\"modal-close\\\" data-act=\\\"close\\\" type=\\\"button\\\" aria-label=\\\"关闭\\\">\' + icon(\'close\', 16) + \'</button></div>\' +\\n      \'<div class=\\\"modal-body\\\">\' + (opts.content || \'\') + \'</div>\' +\\n      (opts.footer === false ? \'\' :\\n        \'<div class=\\\"modal-foot\\\">\' +\\n        (opts.hideCancel ? \'\' : \'<button class=\\\"btn btn-ghost\\\" data-act=\\\"cancel\\\" type=\\\"button\\\">\' + esc(opts.cancelText || \'取消\') + \'</button>\') +\\n        \'<button class=\\\"btn btn-primary\\\" data-act=\\\"ok\\\" type=\\\"button\\\">\' + esc(opts.okText || \'确定\') + \'</button>\' +\\n        \'</div>\');\\n    mask.appendChild(modal);\\n    root.appendChild(mask);\\n\\n    var closed = false;\\n    function close() {\\n      if (closed) return;\\n      closed = true;\\n      mask.classList.add(\'closing\');\\n      setTimeout(function () { if (mask.parentNode) mask.parentNode.removeChild(mask); }, 230);\\n      modalStack = modalStack.filter(function (m) { return m !== mask; });\\n      if (!modalStack.length && modalEscCleanup) {\\n        document.removeEventListener(\'keydown\', modalEscCleanup);\\n        modalEscCleanup = null;\\n      }\\n      if (opts.onClose) opts.onClose();\\n    }\\n\\n    function confirm() {\\n      var r = opts.onOk ? opts.onOk(mask) : true;\\n      if (r !== false) close();\\n    }\\n    function cancel() {\\n      if (opts.onCancel) opts.onCancel();\\n      close();\\n    }\\n\\n    mask.addEventListener(\'click\', function (e) {\\n      var actEl = e.target.closest(\'[data-act]\');\\n      if (actEl) {\\n        e.stopPropagation();\\n        var act = actEl.getAttribute(\'data-act\');\\n        if (act === \'ok\') confirm();\\n        else cancel();\\n        return;\\n      }\\n      if (e.target === mask && opts.maskClosable !== false) cancel();\\n    });\\n\\n    /* Enter 提交 / Escape 取消（表单内） */\\n    mask.addEventListener(\'keydown\', function (e) {\\n      if (e.key === \'Escape\') { e.stopPropagation(); cancel(); return; }\\n      if (e.key === \'Enter\') {\\n        var t = e.target;\\n        if (t && (t.tagName === \'INPUT\' || t.tagName === \'SELECT\') && !t.disabled) {\\n          e.preventDefault();\\n          confirm();\\n        }\\n      }\\n    });\\n\\n    if (!modalStack.length) {\\n      modalEscCleanup = function (e) {\\n        if (e.key === \'Escape\') {\\n          var top = modalStack[modalStack.length - 1];\\n          if (top) top.dispatchEvent(new CustomEvent(\'work-modal-esc\'));\\n        }\\n      };\\n      document.addEventListener(\'keydown\', modalEscCleanup);\\n    }\\n    mask.addEventListener(\'work-modal-esc\', function () { cancel(); });\\n\\n    modalStack.push(mask);\\n    setTimeout(function () {\\n      var first = modal.querySelector(\'input:not([type=hidden]),select,textarea\');\\n      if (first) { try { first.focus(); } catch (e) { /* ignore */ } }\\n    }, 30);\\n    return { close: close, el: modal, mask: mask };\\n  }\\n\\n  function confirmModal(title, msg, onOk, okText) {\\n    return openModal({\\n      title: title,\\n      content: \'<p style=\\\"line-height:1.8;color:var(--text-2)\\\">\' + msg + \'</p>\',\\n      okText: okText || \'确认\',\\n      onOk: function () { if (onOk) onOk(); return true; }\\n    });\\n  }\\n\\n  /* ---- 长按浮出菜单 ---- */\\n  var menuEl = null;\\n  var menuDocHandler = null;\\n\\n  function openMenu(x, y, items) {\\n    closeMenu();\\n    menuEl = document.createElement(\'div\');\\n    menuEl.className = \'work-menu\';\\n    items.forEach(function (it) {\\n      var b = document.createElement(\'button\');\\n      b.type = \'button\';\\n      b.className = \'work-menu-item\' + (it.danger ? \' danger\' : \'\');\\n      b.innerHTML = icon(it.icon || \'dot\', 16) + \'<span>\' + esc(it.label) + \'</span>\';\\n      b.addEventListener(\'click\', function () {\\n        closeMenu();\\n        if (it.onClick) it.onClick();\\n      });\\n      menuEl.appendChild(b);\\n    });\\n    document.body.appendChild(menuEl);\\n    var r = menuEl.getBoundingClientRect();\\n    var vw = window.innerWidth, vh = window.innerHeight;\\n    menuEl.style.left = clamp(x, 8, vw - r.width - 8) + \'px\';\\n    menuEl.style.top = clamp(y, 8, vh - r.height - 8) + \'px\';\\n\\n    menuDocHandler = function (e) {\\n      if (menuEl && !menuEl.contains(e.target)) closeMenu();\\n    };\\n    setTimeout(function () { document.addEventListener(\'click\', menuDocHandler, true); }, 10);\\n    document.addEventListener(\'scroll\', closeMenu, true);\\n  }\\n\\n  function closeMenu() {\\n    if (menuEl) {\\n      if (menuEl.parentNode) menuEl.parentNode.removeChild(menuEl);\\n      menuEl = null;\\n    }\\n    if (menuDocHandler) {\\n      document.removeEventListener(\'click\', menuDocHandler, true);\\n      menuDocHandler = null;\\n    }\\n    document.removeEventListener(\'scroll\', closeMenu, true);\\n  }\\n\\n  /* ======================= 6. 页面刷新与路由辅助 ======================= */\\n\\n  var activeWorkPage = null; // 当前挂载的工作区页面定义\\n\\n  function nav(path) {\\n    if (window.App && typeof App.navigate === \'function\') {\\n      try { App.navigate(path); return; } catch (e) { /* fallthrough */ }\\n    }\\n    location.hash = \'#\' + path;\\n  }\\n\\n  /** 局部刷新当前工作区页面（保留滚动位置，事件委托挂在 #content 上不受影响） */\\n  function refreshWorkPage() {\\n    if (!activeWorkPage) return;\\n    var el = document.getElementById(\'content\');\\n    if (!el) return;\\n    var cur = el.querySelector(\'[data-page]\');\\n    if (!cur) return;\\n    var path = routerCurrent();\\n    var html = \'\';\\n    try { html = activeWorkPage.render(path); } catch (e) { return; }\\n    var tmp = document.createElement(\'div\');\\n    tmp.innerHTML = html;\\n    var fresh = tmp.firstElementChild;\\n    if (!fresh) return;\\n    cur.replaceWith(fresh);\\n    if (activeWorkPage.afterRender) {\\n      try { activeWorkPage.afterRender(el, path); } catch (e) { /* ignore */ }\\n    }\\n  }\\n\\n  /** 长按手势（事件委托版本：绑定在容器上，内部 DOM 替换不影响） */\\n  function bindLongPress(el, selector, ms, onFire) {\\n    var timer = null, sx = 0, sy = 0, firedAt = 0;\\n    function start(e) {\\n      var target = e.target.closest ? e.target.closest(selector) : null;\\n      if (!target || !el.contains(target)) return;\\n      /* 拖拽手柄等交互元素不触发长按 */\\n      if (target.closest(\'.work-drag-handle\') || target.closest(\'.work-proj-grip\') ||\\n        target.closest(\'input,select,textarea,button\')) return;\\n      var pt = e.touches ? e.touches[0] : e;\\n      sx = pt.clientX; sy = pt.clientY;\\n      timer = setTimeout(function () {\\n        timer = null;\\n        firedAt = Date.now();\\n        onFire(e, target);\\n      }, ms || 520);\\n    }\\n    function move(e) {\\n      if (!timer) return;\\n      var pt = e.touches ? e.touches[0] : e;\\n      if (Math.abs(pt.clientX - sx) > 9 || Math.abs(pt.clientY - sy) > 9) cancel();\\n    }\\n    function cancel() { if (timer) { clearTimeout(timer); timer = null; } }\\n    el.addEventListener(\'pointerdown\', start);\\n    el.addEventListener(\'pointermove\', move);\\n    el.addEventListener(\'pointerup\', cancel);\\n    el.addEventListener(\'pointercancel\', cancel);\\n    return {\\n      /** 最近是否刚触发过长按（用于抑制随后的 click） */\\n      justFired: function (withinMs) { return Date.now() - firedAt < (withinMs || 600); },\\n      destroy: function () {\\n        el.removeEventListener(\'pointerdown\', start);\\n        el.removeEventListener(\'pointermove\', move);\\n        el.removeEventListener(\'pointerup\', cancel);\\n        el.removeEventListener(\'pointercancel\', cancel);\\n      }\\n    };\\n  }\\n\\n  /*__PART2__*/\\n\",\"path\":\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\\js\\\\pages\\\\work.js\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 13:35:54'),
