tion () { return function () {}; };\\nstore.summary = function () { return {}; };\\n\\nglobal.window = {\\n  App: {\\n    version: \'0.1.0\',\\n    registerPage: function (p) { registered.push(p); },\\n    navigate: function () {}, refresh: function () {},\\n    store: store,\\n    escapeHtml: function (s) { return String(s == null ? \'\' : s); },\\n    icon: function () { return \'<svg></svg>\'; },\\n    uid: function () { return \'id-x\'; },\\n    showToast: function () {},\\n    openModal: function () { return makeEl(); },\\n    formatDate: function () { return \'\'; },\\n    closeModal: function () {}\\n  }\\n};\\nglobal.document = {\\n  getElementById: function () { return null; },\\n  createElement: function () { return makeEl(); },\\n  head: { appendChild: function () {} },\\n  documentElement: { appendChild: function () {}, style: {} },\\n  addEventListener: function () {},\\n  body: { classList: { add: function () {}, remove: function () {}, contains: function () { return false; } }, style: {} }\\n};\\n\\nvar studyFile = \'D:\\\\\\\\Project\\\\\\\\Project\\\\\\\\ccee\\\\\\\\web1\\\\\\\\js\\\\\\\\pages\\\\\\\\study.js\';\\nrequire(studyFile); // 若语法或顶层逻辑出错会抛出\\n\\nvar expected = [\\n  \'/study\', \'/study/knowledge\', \'/study/knowledge/:id\',\\n  \'/study/knowledge/seed-know-1\', \'/study/knowledge/seed-know-2\',\\n  \'/study/questions\', \'/study/wrong\', \'/study/plan\', \'/study/plans\',\\n  \'/study/clock\', \'/study/checkin\', \'/study/current\', \'/study/shizheng\'\\n];\\nvar missing = expected.filter(function (p) { return registered.indexOf(p) < 0; });\\nconsole.log(\'registered(\' + registered.length + \'): \' + registered.join(\', \'));\\nif (missing.length) {\\n  console.error(\'MISSING: \' + missing.join(\', \'));\\n  process.exit(1);\\n}\\nconsole.log(\'PASS: all \' + expected.length + \' routes registered, study.js loads without error\');\\n\",\"path\":\"C:\\\\Users\\\\Administrator\\\\AppData\\\\Local\\\\Temp\\\\study-harness.js\"},\"effect\":