(983, '40122540-fcbb-4890-9b07-1296c60efc8f', 130462, 'agent.turn.completed', 'code', 'moonya', 'pages_work', NULL, '{\"turn_id\":\"pages_work-turn-18\",\"status\":\"completed\",\"reasoning_content\":\"第二段追加成功。现在第三段：项目列表、项目详情（动态路由）、工作日志、会议记录、注册逻辑。\",\"content\":\"第二段完成。追加第三段：项目列表、项目详情（动态路由）、工作日志、会议记录与注册逻辑：\",\"content_discarded\":false,\"summary\":\"第二段完成。追加第三段：项目列表、项目详情（动态路由）、工作日志、会议记录与注册逻辑：\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":18,\"round\":18,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"},\"round\":18,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"}', '2026-08-03 13:38:18'),
(984, '40122540-fcbb-4890-9b07-1296c60efc8f', 130463, 'agent.turn.completed', 'code', 'moonya', 'pages_study', NULL, '{\"turn_id\":\"pages_study-turn-18\",\"status\":\"completed\",\"reasoning_content\":\"Now run in act phase: node --check + node harness.\",\"content\":\"运行语法检查与桩环境加载测试（act 阶段）。\",\"content_discarded\":false,\"summary\":\"运行语法检查与桩环境加载测试（act 阶段）。\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":18,\"round\":18,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"},\"round\":18,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"}', '2026-08-03 13:38:18'),
(985, '40122540-fcbb-4890-9b07-1296c60efc8f', 130464, 'tool.started', 'code', 'moonya', 'skeleton', 'call_00_9bk2LnHhheZXmJvN0Sdx0524', '{\"tool_key\":\"python_executor\",\"display_name\":\"Python 执行器\",\"arguments\":{\"code\":\"import subprocess, os, textwrap\\n\\nbase = r\\\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\"\\nnode = r\\\"D:\\\\nodejs\\\\node.exe\\\"\\n\\ntest_js = textwrap.dedent(r\'\'\'\\n    const fs = require(\'fs\');\\n    global.window = {};\\n    const mem = {};\\n    global.localStorage = {\\n      getItem: (k) => (k in mem ? mem[k] : null),\\n      setItem: (k, v) => { mem[k] = String(v); },\\n      removeItem: (k) => { delete mem[k]; }\\n    };\\n    eval(fs.readFileSync(\'js/store.js\', \'utf8\'));\\n    const S = global.window.WorkbenchStore;\\n    let failures = 0;\\n    const assert = (cond, msg) => { if (!cond) { console.error(\'FAIL: \' + msg); failures++; } else { console.log(\'PASS: \' + msg); } };\\n\\n    assert(S.todos && S.todos.count() > 0, \'todos 集合存在且有种子数据\');\\n    assert(S.essays && S.essays.count() > 0, \'essays 集合存在且有种子数据\');\\n    assert(S.questions && S.questions.count() === 3, \'questions 种子为 3 条\');\\n\\n    const added = S.todos.add({ title: \'test-todo\', quadrant: \'q1\', priority: \'high\', done: false });\\n    assert(added.id && added.createdAt, \'add 自动补 id 与 createdAt\');\\n    assert(S.todos.get(added.id).title === \'test-todo\', \'get 按 id 查询\');\\n    S.todos.update(added.id, { done: true });\\n    assert(S.todos.get(added.id).done === true, \'update 合并更新\');\\n    assert(S.todos.remove(added.id) === true, \'remove 删除成功\');\\n    assert(S.todos.get(added.id) === null, \'删除后查询为 null\');\\n    assert(S.todos.query(t => t.priority === \'high\').length >= 1, \'query 过滤查询\');\\n\\n    S.updateSettings({ theme: \'dark\' });\\n    assert(S.settings.theme === \'dark\', \'updateSettings 持久化 theme\');\\n    S.updateSettings({ fontSize: 17 });\\n    assert(S.settings.fontSize === 17, \'updateSettings 持久化 fontSize\');\\n    // 设置持久化到 localStorage\\n    const persisted = JSON.parse(mem[\'workbench.data.v1\']);\\n    assert(persisted.settings.theme === \'dark\' && persisted.settings.fontSize === 17, \'localStorage 持久化设置\');\\n\\n    const exported = S.exportJSON();\\n    assert(exported.app === \'个人工作台\' && exported.data.todos.length > 0, \'exportJSON 结构完整\');\\n    assert(S.validateImport({ data: {} }).ok === false, \'空 data 校验失败\');\\n    assert(S.validateImport({ data: { todos: [1, 2] } }).ok === true, \'合法 data 校验通过\');\\n    assert(S.validateImport(\'not json\').ok === false, \'非对象校验失败\');\\n\\n    const imported = S.importJSON({ app: \'个人工作台\', version: \'0.1.0\', settings: { theme: \'light\', fontSize: 16 }, data: { todos: [{ id: \'x1\', title: \'import-item\' }], essays: [] } });\\n    assert(imported.ok === true, \'importJSON 成功\');\\n    assert(S.todos.count() === 1 && S.todos.get(\'x1\').title === \'import-item\', \'导入替换 todos 数据\');\\n    assert(S.essays.count() === 0, \'导入清空 essays（文件内为空数组）\');\\n    assert(S.settings.theme === \'light\' && S.settings.fontSize === 16, \'导入更新设置\');\\n\\n    let notified = 0;\\n    const unsub = S.subscribe(() => { notified++; });\\n    S.ideas.add({ text: \'notify\' });\\n    assert(notified === 1, \'subscribe 收到变更通知\');\\n    unsub();\\n    S.ideas.add({ text: \'no-notify\' });\\n    assert(notified === 1, \'unsubscribe 后不再通知\');\\n\\n    S.clearAll();\\n    assert(S.todos.count() === 6, \'clearAll 恢复初始示例数据(6条)\');\\n    assert(S.settings.theme === \'light\', \'clearAll 保留外观设置\');\\n\\n    const sum = S.summary();\\n    assert(sum.todos === 6 && sum.ideas === 3, \'summary 统计正确\');\\n\\n    console.log(failures === 0 ? \'SMOKE_ALL_PASS\' : \'SMOKE_HAS_FAILURES=\' + failures);\\n    process.exitCode = failures === 0 ? 0 : 1;\\n\'\'\')\\n\\ntest_path = os.path.join(base, \'_smoke_test.js\')\\nwith open(test_path, \'w\', encoding=\'utf-8\') as f:\\n    f.write(test_js)\\n\\ntry:\\n    r = subprocess.run([node, \'_smoke_test.js\'], capture_output=True, text=True, encoding=\'utf-8\', errors=\'replace\', cwd=base, timeout=60)\\n    print(r.stdout)\\n    if r.stderr.strip():\\n        print(\\\"STDERR:\\\", r.stderr.strip()[:800])\\n    print(\\\"exit code:\\\", r.returncode)\\nfinally:\\n    if os.path.exists(test_path):\\n        os.remove(test_path)\\n    print(\\\"临时测试文件已清理:\\\", not os.path.exists(test_path))\\n\"},\"effect\":\"write\",\"risk_level\":\"high\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 13:38:18'),
(986, '40122540-fcbb-4890-9b07-1296c60efc8f', 130465, 'approval.required', 'code', 'moonya', 'skeleton', 'call_00_9bk2LnHhheZXmJvN0Sdx0524', '{\"id\":\"8f6d65c0-6963-482c-b6d5-ce1655098305\",\"status\":\"pending\",\"expires_at\":null,\"reason\":\"工具风险级别为 high\",\"tool_key\":\"python_executor\",\"arguments\":{\"code\":\"import subprocess, os, textwrap\\n\\nbase = r\\\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\"\\nnode = r\\\"D:\\\\nodejs\\\\node.exe\\\"\\n\\ntest_js = textwrap.dedent(r\'\'\'\\n    const fs = require(\'fs\');\\n    global.window = {};\\n    const mem = {};\\n    global.localStorage = {\\n      getItem: (k) => (k in mem ? mem[k] : null),\\n      setItem: (k, v) => { mem[k] = String(v); },\\n      removeItem: (k) => { delete mem[k]; }\\n    };\\n    eval(fs.readFileSync(\'js/store.js\', \'utf8\'));\\n    const S = global.window.WorkbenchStore;\\n    let failures = 0;\\n    const assert = (cond, msg) => { if (!cond) { console.error(\'FAIL: \' + msg); failures++; } else { console.log(\'PASS: \' + msg); } };\\n\\n    assert(S.todos && S.todos.count() > 0, \'todos 集合存在且有种子数据\');\\n    assert(S.essays && S.essays.count() > 0, \'essays 集合存在且有种子数据\');\\n    assert(S.questions && S.questions.count() === 3, \'questions 种子为 3 条\');\\n\\n    const added = S.todos.add({ title: \'test-todo\', quadrant: \'q1\', priority: \'high\', done: false });\\n    assert(added.id && added.createdAt, \'add 自动补 id 与 createdAt\');\\n    assert(S.todos.get(added.id).title === \'test-todo\', \'get 按 id 查询\');\\n    S.todos.update(added.id, { done: true });\\n    assert(S.todos.get(added.id).done === true, \'update 合并更新\');\\n    assert(S.todos.remove(added.id) === true, \'remove 删除成功\');\\n    assert(S.todos.get(added.id) === null, \'删除后查询为 null\');\\n    assert(S.todos.query(t => t.priority === \'high\').length >= 1, \'query 过滤查询\');\\n\\n    S.updateSettings({ theme: \'dark\' });\\n    assert(S.settings.theme === \'dark\', \'updateSettings 持久化 theme\');\\n    S.updateSettings({ fontSize: 17 });\\n    assert(S.settings.fontSize === 17, \'updateSettings 持久化 fontSize\');\\n    // 设置持久化到 localStorage\\n    const persisted = JSON.parse(mem[\'workbench.data.v1\']);\\n    assert(persisted.settings.theme === \'dark\' && persisted.settings.fontSize === 17, \'localStorage 持久化设置\');\\n\\n    const exported = S.exportJSON();\\n    assert(exported.app === \'个人工作台\' && exported.data.todos.length > 0, \'exportJSON 结构完整\');\\n    assert(S.validateImport({ data: {} }).ok === false, \'空 data 校验失败\');\\n    assert(S.validateImport({ data: { todos: [1, 2] } }).ok === true, \'合法 data 校验通过\');\\n    assert(S.validateImport(\'not json\').ok === false, \'非对象校验失败\');\\n\\n    const imported = S.importJSON({ app: \'个人工作台\', version: \'0.1.0\', settings: { theme: \'light\', fontSize: 16 }, data: { todos: [{ id: \'x1\', title: \'import-item\' }], essays: [] } });\\n    assert(imported.ok === true, \'importJSON 成功\');\\n    assert(S.todos.count() === 1 && S.todos.get(\'x1\').title === \'import-item\', \'导入替换 todos 数据\');\\n    assert(S.essays.count() === 0, \'导入清空 essays（文件内为空数组）\');\\n    assert(S.settings.theme === \'light\' && S.settings.fontSize === 16, \'导入更新设置\');\\n\\n    let notified = 0;\\n    const unsub = S.subscribe(() => { notified++; });\\n    S.ideas.add({ text: \'notify\' });\\n    assert(notified === 1, \'subscribe 收到变更通知\');\\n    unsub();\\n    S.ideas.add({ text: \'no-notify\' });\\n    assert(notified === 1, \'unsubscribe 后不再通知\');\\n\\n    S.clearAll();\\n    assert(S.todos.count() === 6, \'clearAll 恢复初始示例数据(6条)\');\\n    assert(S.settings.theme === \'light\', \'clearAll 保留外观设置\');\\n\\n    const sum = S.summary();\\n    assert(sum.todos === 6 && sum.ideas === 3, \'summary 统计正确\');\\n\\n    console.log(failures === 0 ? \'SMOKE_ALL_PASS\' : \'SMOKE_HAS_FAILURES=\' + failures);\\n    process.exitCode = failures === 0 ? 0 : 1;\\n\'\'\')\\n\\ntest_path = os.path.join(base, \'_smoke_test.js\')\\nwith open(test_path, \'w\', encoding=\'utf-8\') as f:\\n    f.write(test_js)\\n\\ntry:\\n    r = subprocess.run([node, \'_smoke_test.js\'], capture_output=True, text=True, encoding=\'utf-8\', errors=\'replace\', cwd=base, timeout=60)\\n    print(r.stdout)\\n    if r.stderr.strip():\\n        print(\\\"STDERR:\\\", r.stderr.strip()[:800])\\n    print(\\\"exit code:\\\", r.returncode)\\nfinally:\\n    if os.path.exists(test_path):\\n        os.remove(test_path)\\n    print(\\\"临时测试文件已清理:\\\", not os.path.exists(test_path))\\n\"}}', '2026-08-03 13:38:18'),
(987, '40122540-fcbb-4890-9b07-1296c60efc8f', 130473, 'approval.decided', 'code', 'moonya', 'skeleton', 'call_00_9bk2LnHhheZXmJvN0Sdx0524', '{\"approval_id\":\"8f6d65c0-6963-482c-b6d5-ce1655098305\",\"status\":\"allowed\"}', '2026-08-03 13:38:55');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
(988, '40122540-fcbb-4890-9b07-1296c60efc8f', 130474, 'tool.completed', 'code', 'moonya', 'skeleton', 'call_00_9bk2LnHhheZXmJvN0Sdx0524', '{\"tool_key\":\"python_executor\",\"ok\":true,\"content\":\"PASS: todos 集合存在且有种子数据\\r\\nPASS: essays 集合存在且有种子数据\\r\\nPASS: questions 种子为 3 条\\r\\nPASS: add 自动补 id 与 createdAt\\r\\nPASS: get 按 id 查询\\r\\nPASS: update 合并更新\\r\\nPASS: remove 删除成功\\r\\nPASS: 删除后查询为 null\\r\\nPASS: query 过滤查询\\r\\nPASS: updateSettings 持久化 theme\\r\\nPASS: updateSettings 持久化 fontSize\\r\\nPASS: localStorage 持久化设置\\r\\nPASS: exportJSON 结构完整\\r\\nPASS: 空 data 校验失败\\r\\nPASS: 合法 data 校验通过\\r\\nPASS: 非对象校验失败\\r\\nPASS: importJSON 成功\\r\\nPASS: 导入替换 todos 数据\\r\\nPASS: 导入清空 essays（文件内为空数组）\\r\\nPASS: 导入更新设置\\r\\nPASS: subscribe 收到变更通知\\r\\nPASS: unsubscribe 后不再通知\\r\\nPASS: clearAll 恢复初始示例数据(6条)\\r\\nPASS: clearAll 保留外观设置\\r\\nPASS: summary 统计正确\\r\\nSMOKE_ALL_PASS\\r\\n\\r\\nexit code: 0\\r\\n临时测试文件已清理: True\\r\\n\",\"error\":null,\"stage\":\"execute\",\"status\":\"success\",\"error_code\":\"\",\"command_fingerprint\":\"\",\"operation_receipt\":null}', '2026-08-03 13:38:55');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
(989, '40122540-fcbb-4890-9b07-1296c60efc8f', 130475, 'tool.started', 'code', 'moonya', 'pages_work', 'call_00_svy4efiTiKJSr5d5LeWq6473', '{\"tool_key\":\"edit_file\",\"display_name\":\"Edit File\",\"arguments\":{\"command\":\"str_replace\",\"new_str\":\"  /* ---------- 7.4 /work/projects 项目列表 ---------- */\\n\\n  function statusTag(status) {\\n    var s = PROJ_STATUS[status] || PROJ_STATUS.active;\\n    return \'<span class=\\\"tag \' + s.cls + \'\\\">\' + s.label + \'</span>\';\\n  }\\n\\n  function projTaskCount(pid) {\\n    var ts = getTodos().filter(function (t) { return t.projectId === pid; });\\n    var undone = ts.filter(function (t) { return !t.done; }).length;\\n    return { undone: undone, total: ts.length };\\n  }\\n\\n  function projCardHtml(p, archived) {\\n    var cnt = projTaskCount(p.id);\\n    var color = p.color || \'#b06f47\';\\n    var ini = (p.name || \'?\').trim().charAt(0) || \'?\';\\n    return \'<div class=\\\"work-proj-card glass-card\' + (archived ? \' is-archived\' : \'\') + \'\\\" data-id=\\\"\' + esc(p.id) + \'\\\" data-name=\\\"\' + esc(p.name || \'\') + \'\\\" data-desc=\\\"\' + esc(p.desc || \'\') + \'\\\">\' +\\n      \'<div class=\\\"work-proj-color\\\" style=\\\"background:\' + color + \'\\\">\' + esc(ini) + \'</div>\' +\\n      \'<div class=\\\"work-proj-main\\\">\' +\\n      \'<div class=\\\"work-proj-name\\\"><span>\' + esc(p.name) + \'</span>\' +\\n      (archived ? \'<span class=\\\"tag tag-danger\\\">已归档</span>\' : statusTag(p.status)) +\\n      \'</div>\' +\\n      \'<div class=\\\"work-proj-desc\\\">\' + esc(p.desc || \'暂无描述\') + \'</div>\' +\\n      \'<div class=\\\"work-proj-meta\\\">\' +\\n      \'<span class=\\\"work-tag-color\\\" style=\\\"background:\' + color + \'1f;color:\' + color + \'\\\"><span class=\\\"work-tag-dot\\\" style=\\\"background:\' + color + \'\\\"></span>项目</span>\' +\\n      \'<span class=\\\"work-proj-count\\\">任务 \' + cnt.undone + \' / \' + cnt.total + \'</span>\' +\\n      \'<span class=\\\"muted\\\" style=\\\"font-size:0.76rem\\\">创建于 \' + (p.createdAt ? String(p.createdAt).slice(0, 10) : \'—\') + \'</span>\' +\\n      \'</div></div>\' +\\n      (archived\\n        ? \'<button type=\\\"button\\\" class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"restore\\\">恢复</button>\'\\n        : \'<span class=\\\"work-proj-grip\\\" draggable=\\\"true\\\" title=\\\"拖动排序\\\">\' + icon(\'grip\', 17) + \'</span>\') +\\n      \'</div>\';\\n  }\\n\\n  var workProjects = {\\n    title: \'项目备忘\',\\n    _kw: \'\',\\n    render: function () {\\n      var all = sortProjects(getProjects());\\n      var kw = (this._kw || \'\').trim().toLowerCase();\\n      var active = all.filter(function (p) { return p.status !== \'archived\'; });\\n      var archived = all.filter(function (p) { return p.status === \'archived\'; });\\n      function match(p) {\\n        return !kw ||\\n          (p.name || \'\').toLowerCase().indexOf(kw) >= 0 ||\\n          (p.desc || \'\').toLowerCase().indexOf(kw) >= 0;\\n      }\\n      active = active.filter(match);\\n      archived = archived.filter(match);\\n      return \'<div class=\\\"page work-page\\\" data-page=\\\"work-projects\\\">\' +\\n        \'<div class=\\\"work-bar\\\">\' +\\n        \'<div class=\\\"search-box\\\" style=\\\"flex:1;max-width:380px;margin-bottom:0\\\">\' +\\n        \'<span class=\\\"search-icon\\\">\' + icon(\'search\', 17) + \'</span>\' +\\n        \'<input class=\\\"input\\\" data-act=\\\"search\\\" type=\\\"text\\\" placeholder=\\\"搜索项目名或描述…\\\" value=\\\"\' + esc(this._kw || \'\') + \'\\\" autocomplete=\\\"off\\\">\' +\\n        \'</div>\' +\\n        \'<button class=\\\"btn btn-primary\\\" data-act=\\\"new-proj\\\">\' + icon(\'plus\', 16) + \'新建项目</button>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"work-proj-list\\\">\' +\\n        (active.length ? active.map(function (p) { return projCardHtml(p, false); }).join(\'\') :\\n          \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'folder\', 34) + \'</div>\' +\\n          (kw ? \'没有匹配的项目\' : \'还没有项目，点击右上角新建\') + \'</div>\') +\\n        \'</div>\' +\\n        (archived.length ? \'<div class=\\\"work-archived-head\\\" data-act=\\\"arch-toggle\\\">\' +\\n          \'<span class=\\\"chev\\\">\' + icon(\'chevron\', 14) + \'</span>已归档项目（\' + archived.length + \'）</div>\' +\\n          \'<div class=\\\"work-proj-list\\\" data-arch=\\\"1\\\" style=\\\"display:none\\\">\' +\\n          archived.map(function (p) { return projCardHtml(p, true); }).join(\'\') +\\n          \'</div>\' : \'\') +\\n        \'</div>\';\\n    },\\n    mount: function (el) {\\n      if (this._cleanup) this._cleanup();\\n      var self = this;\\n      activeWorkPage = self;\\n      var dragState = { id: null, hint: null };\\n\\n      var press = bindLongPress(el, \'.work-proj-card\', 520, function (e, card) {\\n        if (card.classList.contains(\'is-archived\')) return;\\n        var id = card.getAttribute(\'data-id\');\\n        var p = window.App.store.projects.get(id);\\n        if (!p) return;\\n        var rect = card.getBoundingClientRect();\\n        openMenu(rect.left + 40, rect.top + rect.height / 2, [\\n          { label: \'归档项目\', icon: \'archive\', onClick: function () {\\n            window.App.store.projects.update(id, { status: \'archived\' });\\n            uiToast(\'已归档\', \'success\');\\n            refreshWorkPage();\\n          } },\\n          { label: \'删除项目\', icon: \'trash\', danger: true, onClick: function () {\\n            confirmModal(\'删除项目\', \'删除「\' + esc(p.name) + \'」将同时解除其下所有待办的项目关联，确定吗？\', function () {\\n              getTodos().forEach(function (t) {\\n                if (t.projectId === id) window.App.store.todos.update(t.id, { projectId: \'\' });\\n              });\\n              window.App.store.projects.remove(id);\\n              uiToast(\'已删除\', \'success\');\\n              refreshWorkPage();\\n            });\\n          } }\\n        ]);\\n      });\\n\\n      function onClick(e) {\\n        if (press.justFired(600)) return;\\n        var card = e.target.closest(\'.work-proj-card\');\\n        if (card && !e.target.closest(\'[data-act=\\\"restore\\\"]\') && !e.target.closest(\'.work-proj-grip\')) {\\n          nav(\'/work/projects/\' + encodeURIComponent(card.getAttribute(\'data-id\')));\\n          return;\\n        }\\n        var restore = e.target.closest(\'[data-act=\\\"restore\\\"]\');\\n        if (restore) {\\n          var rc = restore.closest(\'.work-proj-card\');\\n          window.App.store.projects.update(rc.getAttribute(\'data-id\'), { status: \'active\' });\\n          uiToast(\'已恢复为进行中\', \'success\');\\n          refreshWorkPage();\\n          return;\\n        }\\n        var np = e.target.closest(\'[data-act=\\\"new-proj\\\"]\');\\n        if (np) { openProjectForm(null); return; }\\n        var at = e.target.closest(\'[data-act=\\\"arch-toggle\\\"]\');\\n        if (at) {\\n          var list = $(\'[data-arch=\\\"1\\\"]\', el);\\n          if (list) {\\n            var show = list.style.display === \'none\';\\n            list.style.display = show ? \'flex\' : \'none\';\\n            at.classList.toggle(\'open\', show);\\n          }\\n        }\\n      }\\n\\n      function onInput(e) {\\n        var inp = e.target.closest(\'[data-act=\\\"search\\\"]\');\\n        if (inp) {\\n          self._kw = inp.value;\\n          refreshWorkPage();\\n        }\\n      }\\n\\n      /* 拖拽排序（手柄） */\\n      function onDragStart(e) {\\n        var grip = e.target.closest(\'.work-proj-grip\');\\n        if (!grip) return;\\n        var card = grip.closest(\'.work-proj-card\');\\n        dragState.id = card.getAttribute(\'data-id\');\\n        e.dataTransfer.effectAllowed = \'move\';\\n        try { e.dataTransfer.setData(\'text/plain\', dragState.id); } catch (err) { /* ignore */ }\\n        card.classList.add(\'dragging\');\\n        dragState.hint = document.createElement(\'div\');\\n        dragState.hint.className = \'work-proj-sort-hint\';\\n        document.body.appendChild(dragState.hint);\\n      }\\n      function onDragEnd(e) {\\n        var card = e.target.closest(\'.work-proj-card\');\\n        if (card) card.classList.remove(\'dragging\');\\n        if (dragState.hint) { dragState.hint.remove(); dragState.hint = null; }\\n        if (dragState.id) { persistOrder(); dragState.id = null; }\\n      }\\n      function onCardDragOver(e) {\\n        var card = e.target.closest(\'.work-proj-card:not(.is-archived)\');\\n        if (!card || !dragState.id || card.getAttribute(\'data-id\') === dragState.id) return;\\n        e.preventDefault();\\n        try { e.dataTransfer.dropEffect = \'move\'; } catch (err) { /* ignore */ }\\n        if (dragState.hint) {\\n          var r = card.getBoundingClientRect();\\n          var after = e.clientY > r.top + r.height / 2;\\n          dragState.hint.style.left = r.left + \'px\';\\n          dragState.hint.style.width = r.width + \'px\';\\n          dragState.hint.style.height = \'10px\';\\n          dragState.hint.style.top = (after ? r.bottom - 5 : r.top - 5) + \'px\';\\n        }\\n      }\\n      function onCardDrop(e) {\\n        var card = e.target.closest(\'.work-proj-card:not(.is-archived)\');\\n        if (!card || !dragState.id) return;\\n        e.preventDefault();\\n        e.stopPropagation();\\n        var targetId = card.getAttribute(\'data-id\');\\n        if (targetId === dragState.id) return;\\n        var list = sortProjects(getProjects()).filter(function (p) { return p.status !== \'archived\'; });\\n        var from = list.findIndex(function (p) { return p.id === dragState.id; });\\n        var to = list.findIndex(function (p) { return p.id === targetId; });\\n        if (from < 0 || to < 0) return;\\n        var moved = list.splice(from, 1)[0];\\n        var r = card.getBoundingClientRect();\\n        if (e.clientY > r.top + r.height / 2) to += 1;\\n        if (to > from) to -= 1;\\n        list.splice(Math.max(0, to), 0, moved);\\n        list.forEach(function (p, i) { window.App.store.projects.update(p.id, { sort: i }); });\\n        uiToast(\'已调整排序\', \'success\');\\n        dragState.id = null;\\n        refreshWorkPage();\\n      }\\n      function persistOrder() {\\n        var ids = $$(\'.work-proj-card:not(.is-archived)\', el).map(function (c) { return c.getAttribute(\'data-id\'); });\\n        ids.forEach(function (id, i) { window.App.store.projects.update(id, { sort: i }); });\\n      }\\n\\n      el.addEventListener(\'click\', onClick);\\n      el.addEventListener(\'input\', onInput);\\n      el.addEventListener(\'dragstart\', onDragStart);\\n      el.addEventListener(\'dragend\', onDragEnd);\\n      el.addEventListener(\'dragover\', onCardDragOver);\\n      el.addEventListener(\'drop\', onCardDrop);\\n\\n      this._cleanup = function () {\\n        el.removeEventListener(\'click\', onClick);\\n        el.removeEventListener(\'input\', onInput);\\n        el.removeEventListener(\'dragstart\', onDragStart);\\n        el.removeEventListener(\'dragend\', onDragEnd);\\n        el.removeEventListener(\'dragover\', onCardDragOver);\\n        el.removeEventListener(\'drop\', onCardDrop);\\n        if (press) press.destroy();\\n        if (dragState.hint) dragState.hint.remove();\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  /* 新建 / 编辑项目表单 */\\n  function openProjectForm(proj) {\\n    var p = proj || {};\\n    var color = p.color || PROJ_COLORS[0];\\n    var html = \'<form data-form=\\\"proj\\\" onsubmit=\\\"return false\\\">\' +\\n      \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">项目名</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"name\\\" type=\\\"text\\\" value=\\\"\' + esc(p.name || \'\') + \'\\\" placeholder=\\\"项目名称\\\" autocomplete=\\\"off\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>描述</label>\' +\\n      \'<textarea class=\\\"textarea\\\" data-f=\\\"desc\\\" placeholder=\\\"一句话描述（选填）\\\" style=\\\"min-height:64px\\\">\' + esc(p.desc || \'\') + \'</textarea></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>颜色标签</label><div class=\\\"work-color-row\\\">\' +\\n      PROJ_COLORS.map(function (c) {\\n        return \'<span class=\\\"work-color-dot\' + (c === color ? \' active\' : \'\') + \'\\\" data-color=\\\"\' + c + \'\\\" style=\\\"background:\' + c + \'\\\"></span>\';\\n      }).join(\'\') +\\n      \'</div></div>\' +\\n      (p.id ? \'<div class=\\\"work-form-row\\\"><label>状态</label><select class=\\\"select\\\" data-f=\\\"status\\\">\' +\\n        [\'active\', \'paused\', \'done\', \'archived\'].map(function (s) {\\n          return \'<option value=\\\"\' + s + \'\\\"\' + (p.status === s ? \' selected\' : \'\') + \'>\' + PROJ_STATUS[s].label + \'</option>\';\\n        }).join(\'\') +\\n        \'</select></div>\' : \'\') +\\n      \'</form>\';\\n    var m = openModal({\\n      title: p.id ? \'编辑项目\' : \'新建项目\',\\n      content: html,\\n      okText: p.id ? \'保存\' : \'创建\',\\n      onOk: function (mask) {\\n        var name = $(\'[data-f=\\\"name\\\"]\', mask).value.trim();\\n        if (!name) { uiToast(\'项目名不能为空\', \'warn\'); return false; }\\n        var picked = $(\'.work-color-dot.active\', mask);\\n        var patch = {\\n          name: name,\\n          desc: $(\'[data-f=\\\"desc\\\"]\', mask).value.trim(),\\n          color: picked ? picked.getAttribute(\'data-color\') : color\\n        };\\n        if (p.id) {\\n          patch.status = $(\'[data-f=\\\"status\\\"]\', mask).value;\\n          window.App.store.projects.update(p.id, patch);\\n          uiToast(\'已保存\', \'success\');\\n        } else {\\n          patch.status = \'active\';\\n          window.App.store.projects.add(patch);\\n          uiToast(\'已创建项目\', \'success\');\\n        }\\n        refreshWorkPage();\\n        return true;\\n      }\\n    });\\n    setTimeout(function () {\\n      $$(\'.work-color-dot\', m.el).forEach(function (dot) {\\n        dot.addEventListener(\'click\', function () {\\n          $$(\'.work-color-dot\', m.el).forEach(function (d) { d.classList.remove(\'active\'); });\\n          dot.classList.add(\'active\');\\n        });\\n      });\\n    }, 20);\\n  }\\n\\n  /* ---------- 7.5 /work/projects/:id 项目详情（动态路由） ---------- */\\n\\n  var DETAIL_TABS = [\\n    { id: \'tasks\', label: \'任务\' },\\n    { id: \'notes\', label: \'笔记\' },\\n    { id: \'files\', label: \'文件\' }\\n  ];\\n\\n  var projectDetail = {\\n    title: \'项目详情\',\\n    _tab: \'tasks\',\\n    _id: \'\',\\n    render: function (path) {\\n      var m = /^\\\\/work\\\\/projects\\\\/([^/]+)$/.exec(path || \'\');\\n      var id = m ? decodeURIComponent(m[1]) : \'\';\\n      this._id = id;\\n      var p = id ? window.App.store.projects.get(id) : null;\\n      if (!p) {\\n        return \'<div class=\\\"page work-page\\\" data-page=\\\"work-detail\\\">\' +\\n          \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'folder\', 34) + \'</div>\' +\\n          \'<p>项目不存在或已被删除</p>\' +\\n          \'<button class=\\\"btn btn-primary\\\" data-act=\\\"back-list\\\" style=\\\"margin-top:14px\\\">\' + icon(\'back\', 16) + \'返回项目列表</button>\' +\\n          \'</div></div>\';\\n      }\\n      var tab = this._tab || \'tasks\';\\n      var cnt = projTaskCount(p.id);\\n      var status = PROJ_STATUS[p.status] || PROJ_STATUS.active;\\n      var notes = (p.notes || []).slice().reverse();\\n      var files = (p.files || []).slice().reverse();\\n\\n      var tabsHtml = \'<div class=\\\"work-tabs\\\" data-act=\\\"tabs\\\">\' +\\n        DETAIL_TABS.map(function (t) {\\n          return \'<button class=\\\"work-tab\' + (t.id === tab ? \' active\' : \'\') + \'\\\" data-tab=\\\"\' + t.id + \'\\\">\' + t.label + \'</button>\';\\n        }).join(\'\') +\\n        \'<span class=\\\"work-tab-indicator\\\"></span></div>\';\\n\\n      var panelHtml = \'\';\\n      if (tab === \'tasks\') {\\n        var ts = getTodos().filter(function (t) { return t.projectId === id; });\\n        panelHtml = \'<div class=\\\"work-tabpanel\\\">\' +\\n          (ts.length ? ts.map(function (t) {\\n            var prio = t.priority || \'mid\';\\n            var due = t.due ? dueText(t.due) : \'\';\\n            return \'<div class=\\\"work-todo-row\' + (t.done ? \' done\' : \'\') + \'\\\" data-id=\\\"\' + esc(t.id) + \'\\\">\' +\\n              \'<input type=\\\"checkbox\\\" class=\\\"work-todo-check\\\" data-act=\\\"dt-toggle\\\" \' + (t.done ? \'checked\' : \'\') + \' aria-label=\\\"完成\\\">\' +\\n              \'<span class=\\\"work-todo-title\\\">\' + esc(t.title) + \'</span>\' +\\n              (due ? \'<span class=\\\"work-due\\\">\' + due + \'</span>\' : \'\') +\\n              \'<span class=\\\"work-prio \' + prio + \'\\\" title=\\\"优先级：\' + (PRIO_LABEL[prio] || \'中\') + \'\\\"></span>\' +\\n              \'<button type=\\\"button\\\" class=\\\"icon-btn\\\" data-act=\\\"dt-del\\\" title=\\\"删除\\\" style=\\\"width:28px;height:28px\\\">\' + icon(\'trash\', 15) + \'</button>\' +\\n              \'</div>\';\\n          }).join(\'\') : \'<div class=\\\"empty-state\\\"><p>该项目还没有任务，点下方「+ 添加任务」创建</p></div>\') +\\n          \'</div>\';\\n      } else if (tab === \'notes\') {\\n        panelHtml = \'<div class=\\\"work-tabpanel\\\">\' +\\n          (notes.length ? notes.map(function (n) {\\n            return \'<div class=\\\"work-note-item\\\" data-note=\\\"\' + esc(n.id) + \'\\\">\' +\\n              \'<div class=\\\"work-note-head\\\">\' +\\n              \'<span class=\\\"work-note-title\\\">\' + esc(n.title || \'无标题\') + \'</span>\' +\\n              \'<span class=\\\"work-note-time\\\">\' + timeText(n.createdAt) + \'</span>\' +\\n              \'<span class=\\\"chev\\\">\' + icon(\'chevron\', 15) + \'</span>\' +\\n              \'</div>\' +\\n              \'<div class=\\\"work-note-body\\\">\' + esc(n.content || \'\') + \'</div>\' +\\n              \'</div>\';\\n          }).join(\'\') : \'<div class=\\\"empty-state\\\"><p>暂无笔记，点下方「+ 添加笔记」记录</p></div>\') +\\n          \'</div>\';\\n      } else {\\n        panelHtml = \'<div class=\\\"work-tabpanel\\\">\' +\\n          (files.length ? files.map(function (f) {\\n            return \'<div class=\\\"work-file-item\\\" data-act=\\\"open-file\\\" data-url=\\\"\' + esc(f.dataUrl || \'\') + \'\\\">\' +\\n              \'<span class=\\\"work-file-icon\\\">\' + icon(\'file\', 19) + \'</span>\' +\\n              \'<div class=\\\"work-file-main\\\">\' +\\n              \'<div class=\\\"work-file-name\\\">\' + esc(f.name || \'未命名文件\') + \'</div>\' +\\n              \'<div class=\\\"work-file-meta\\\">\' + formatSize(f.size) + \' · 上传于 \' + timeText(f.uploadedAt) + \'</div>\' +\\n              \'</div>\' +\\n              \'<span class=\\\"muted\\\">\' + icon(\'download\', 16) + \'</span>\' +\\n              \'</div>\';\\n          }).join(\'\') : \'<div class=\\\"empty-state\\\"><p>暂无附件，点下方「+ 添加文件」上传记录</p></div>\') +\\n          \'<input type=\\\"file\\\" class=\\\"work-file-input\\\" data-act=\\\"file-input\\\">\' +\\n          \'</div>\';\\n      }\\n\\n      return \'<div class=\\\"page work-page\\\" data-page=\\\"work-detail\\\">\' +\\n        \'<div class=\\\"work-detail-head\\\">\' +\\n        \'<button class=\\\"icon-btn\\\" data-act=\\\"back-list\\\" title=\\\"返回项目列表\\\" aria-label=\\\"返回\\\">\' + icon(\'back\', 20) + \'</button>\' +\\n        \'<h2>\' + esc(p.name) + \'</h2>\' +\\n        \'<button class=\\\"icon-btn\\\" data-act=\\\"settings\\\" title=\\\"项目设置\\\" aria-label=\\\"项目设置\\\">\' + icon(\'gear\', 20) + \'</button>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"glass-card work-info-card\\\">\' +\\n        \'<div class=\\\"work-info-row\\\"><span class=\\\"lbl\\\">名称</span><span class=\\\"val\\\">\' + esc(p.name) + \'</span>\' + statusTag(p.status) + \'</div>\' +\\n        (p.desc ? \'<div class=\\\"work-info-row\\\"><span class=\\\"lbl\\\">描述</span><span class=\\\"val\\\">\' + esc(p.desc) + \'</span></div>\' : \'\') +\\n        \'<div class=\\\"work-info-row\\\"><span class=\\\"lbl\\\">创建日期</span><span class=\\\"val\\\">\' + (p.createdAt ? esc(String(p.createdAt).slice(0, 10)) : \'—\') + \'</span></div>\' +\\n        \'<div class=\\\"work-info-row\\\"><span class=\\\"lbl\\\">任务进度</span><span class=\\\"val\\\">\' + cnt.undone + \' 项未完成 / 共 \' + cnt.total + \' 项</span></div>\' +\\n        \'</div>\' +\\n        tabsHtml +\\n        \'<div data-act=\\\"panel\\\">\' + panelHtml + \'</div>\' +\\n        \'<div class=\\\"work-fab\\\">\' +\\n        \'<button class=\\\"btn btn-ghost\\\" data-act=\\\"add-file\\\">\' + icon(\'upload\', 16) + \'添加文件</button>\' +\\n        \'<button class=\\\"btn btn-soft\\\" data-act=\\\"add-note\\\">\' + icon(\'log\', 16) + \'添加笔记</button>\' +\\n        \'<button class=\\\"btn btn-primary\\\" data-act=\\\"add-task\\\">\' + icon(\'plus\', 16) + \'添加任务</button>\' +\\n        \'</div></div>\';\\n    },\\n    afterRender: function (el) {\\n      /* Tab 下划线滑动指示器 */\\n      var tabs = $(\'.work-tabs\', el);\\n      if (tabs) {\\n        var indicator = $(\'.work-tab-indicator\', tabs);\\n        var active = $(\'.work-tab.active\', tabs);\\n        if (indicator && active) {\\n          indicator.style.width = active.offsetWidth + \'px\';\\n          indicator.style.transform = \'translateX(\' + active.offsetLeft + \'px)\';\\n        }\\n      }\\n    },\\n    mount: function (el, path) {\\n      if (this._cleanup) this._cleanup();\\n      var self = this;\\n      activeWorkPage = self;\\n      self._id = projectIdFromPath(path);\\n      self._tab = self._tab || \'tasks\';\\n\\n      function afterRenderLocal() { self.afterRender(el); }\\n\\n      function onClick(e) {\\n        var back = e.target.closest(\'[data-act=\\\"back-list\\\"]\');\\n        if (back) { nav(\'/work/projects\'); return; }\\n        var settings = e.target.closest(\'[data-act=\\\"settings\\\"]\');\\n        if (settings) { openDetailSettings(); return; }\\n        var tabBtn = e.target.closest(\'.work-tab[data-tab]\');\\n        if (tabBtn) {\\n          self._tab = tabBtn.getAttribute(\'data-tab\');\\n          refreshWorkPage();\\n          return;\\n        }\\n        var tToggle = e.target.closest(\'[data-act=\\\"dt-toggle\\\"]\');\\n        if (tToggle) {\\n          var row = tToggle.closest(\'.work-todo-row\');\\n          var t = window.App.store.todos.get(row.getAttribute(\'data-id\'));\\n          if (t) {\\n            var nowDone = !t.done;\\n            window.App.store.todos.update(t.id, { done: nowDone, completedAt: nowDone ? new Date().toISOString() : \'\' });\\n            row.classList.add(\'leaving\');\\n            setTimeout(function () { refreshWorkPage(); }, 320);\\n          }\\n          return;\\n        }\\n        var tDel = e.target.closest(\'[data-act=\\\"dt-del\\\"]\');\\n        if (tDel) {\\n          var r2 = tDel.closest(\'.work-todo-row\');\\n          var id2 = r2.getAttribute(\'data-id\');\\n          confirmModal(\'删除任务\', \'确定删除这项任务吗？\', function () {\\n            window.App.store.todos.remove(id2);\\n            uiToast(\'已删除\', \'success\');\\n            refreshWorkPage();\\n          });\\n          return;\\n        }\\n        var note = e.target.closest(\'.work-note-item\');\\n        if (note) {\\n          note.classList.toggle(\'open\');\\n          return;\\n        }\\n        var fileItem = e.target.closest(\'[data-act=\\\"open-file\\\"]\');\\n        if (fileItem) {\\n          var url = fileItem.getAttribute(\'data-url\');\\n          if (url) { window.open(url, \'_blank\'); }\\n          else uiToast(\'该文件仅记录元数据，未保存内容\', \'warn\');\\n          return;\\n        }\\n        var addTask = e.target.closest(\'[data-act=\\\"add-task\\\"]\');\\n        if (addTask) { openDetailTaskForm(); return; }\\n        var addNote = e.target.closest(\'[data-act=\\\"add-note\\\"]\');\\n        if (addNote) { openDetailNoteForm(); return; }\\n        var addFile = e.target.closest(\'[data-act=\\\"add-file\\\"]\');\\n        if (addFile) {\\n          var fi = $(\'.work-file-input\', el);\\n          if (fi) fi.click();\\n        }\\n      }\\n\\n      function onChange(e) {\\n        var fi = e.target.closest(\'.work-file-input\');\\n        if (fi && fi.files && fi.files[0]) {\\n          addFileRecord(fi.files[0]);\\n          fi.value = \'\';\\n        }\\n      }\\n\\n      /* 详情页设置：编辑信息 / 切换状态 / 删除项目 */\\n      function openDetailSettings() {\\n        var p = window.App.store.projects.get(self._id);\\n        if (!p) return;\\n        openProjectForm(p);\\n      }\\n\\n      function openDetailTaskForm() {\\n        var html = \'<form data-form=\\\"dtask\\\" onsubmit=\\\"return false\\\">\' +\\n          \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">任务标题</label>\' +\\n          \'<input class=\\\"input\\\" data-f=\\\"title\\\" type=\\\"text\\\" placeholder=\\\"要做什么…\\\" autocomplete=\\\"off\\\"></div>\' +\\n          \'<div class=\\\"work-form-grid\\\">\' +\\n          \'<div class=\\\"work-form-row\\\"><label>象限</label><select class=\\\"select\\\" data-f=\\\"quadrant\\\">\' +\\n          QUADRANTS.map(function (q) { return \'<option value=\\\"\' + q.id + \'\\\">\' + q.label + \'</option>\'; }).join(\'\') +\\n          \'</select></div>\' +\\n          \'<div class=\\\"work-form-row\\\"><label>优先级</label><select class=\\\"select\\\" data-f=\\\"priority\\\">\' +\\n          [\'high\', \'mid\', \'low\'].map(function (pr) { return \'<option value=\\\"\' + pr + \'\\\">\' + PRIO_LABEL[pr] + \'</option>\'; }).join(\'\') +\\n          \'</select></div>\' +\\n          \'<div class=\\\"work-form-row\\\"><label>截止日期</label><input class=\\\"input\\\" data-f=\\\"due\\\" type=\\\"date\\\" value=\\\"\' + todayStr() + \'\\\"></div>\' +\\n          \'</div></form>\';\\n        openModal({\\n          title: \'添加任务\',\\n          content: html,\\n          okText: \'添加\',\\n          onOk: function (mask) {\\n            var title = $(\'[data-f=\\\"title\\\"]\', mask).value.trim();\\n            if (!title) { uiToast(\'请输入任务标题\', \'warn\'); return false; }\\n            window.App.store.todos.add({\\n              title: title,\\n              quadrant: $(\'[data-f=\\\"quadrant\\\"]\', mask).value,\\n              priority: $(\'[data-f=\\\"priority\\\"]\', mask).value,\\n              due: $(\'[data-f=\\\"due\\\"]\', mask).value || todayStr(),\\n              done: false,\\n              projectId: self._id\\n            });\\n            uiToast(\'已添加，自动关联当前项目\', \'success\');\\n            refreshWorkPage();\\n            return true;\\n          }\\n        });\\n      }\\n\\n      function openDetailNoteForm() {\\n        var html = \'<form data-form=\\\"dnote\\\" onsubmit=\\\"return false\\\">\' +\\n          \'<div class=\\\"work-form-row\\\"><label>标题（选填）</label>\' +\\n          \'<input class=\\\"input\\\" data-f=\\\"title\\\" type=\\\"text\\\" placeholder=\\\"笔记标题\\\" autocomplete=\\\"off\\\"></div>\' +\\n          \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">内容</label>\' +\\n          \'<textarea class=\\\"textarea\\\" data-f=\\\"content\\\" placeholder=\\\"写点什么…\\\" style=\\\"min-height:120px\\\"></textarea></div></form>\';\\n        openModal({\\n          title: \'添加笔记\',\\n          content: html,\\n          okText: \'保存\',\\n          onOk: function (mask) {\\n            var content = $(\'[data-f=\\\"content\\\"]\', mask).value.trim();\\n            if (!content) { uiToast(\'笔记内容不能为空\', \'warn\'); return false; }\\n            var p = window.App.store.projects.get(self._id);\\n            if (!p) return true;\\n            var notes = (p.notes || []).concat([{\\n              id: \'n-\' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),\\n              title: $(\'[data-f=\\\"title\\\"]\', mask).value.trim(),\\n              content: content,\\n              createdAt: new Date().toISOString()\\n            }]);\\n            window.App.store.projects.update(self._id, { notes: notes });\\n            uiToast(\'笔记已保存\', \'success\');\\n            refreshWorkPage();\\n            return true;\\n          }\\n        });\\n      }\\n\\n      function addFileRecord(file) {\\n        var p = window.App.store.projects.get(self._id);\\n        if (!p) return;\\n        var rec = {\\n          id: \'f-\' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),\\n          name: file.name,\\n          size: file.size,\\n          type: file.type || \'\',\\n          uploadedAt: new Date().toISOString(),\\n          dataUrl: \'\'\\n        };\\n        /* 小文件（≤256KB）读取内容便于预览，大文件仅记录元数据 */\\n        if (file.size <= 256 * 1024) {\\n          var reader = new FileReader();\\n          reader.onload = function () {\\n            rec.dataUrl = String(reader.result || \'\');\\n            saveRec();\\n          };\\n          reader.onerror = function () { saveRec(); };\\n          try { reader.readAsDataURL(file); } catch (e) { saveRec(); }\\n        } else {\\n          saveRec();\\n        }\\n        function saveRec() {\\n          var cur = window.App.store.projects.get(self._id);\\n          if (!cur) return;\\n          var files = (cur.files || []).concat([rec]);\\n          window.App.store.projects.update(self._id, { files: files });\\n          uiToast(\'已添加文件记录\', \'success\');\\n          refreshWorkPage();\\n        }\\n      }\\n\\n      el.addEventListener(\'click\', onClick);\\n      el.addEventListener(\'change\', onChange);\\n      setTimeout(afterRenderLocal, 30);\\n\\n      this._cleanup = function () {\\n        el.removeEventListener(\'click\', onClick);\\n        el.removeEventListener(\'change\', onChange);\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  function formatSize(bytes) {\\n    var b = Number(bytes) || 0;\\n    if (b < 1024) return b + \' B\';\\n    if (b < 1024 * 1024) return (b / 1024).toFixed(1) + \' KB\';\\n    return (b / (1024 * 1024)).toFixed(1) + \' MB\';\\n  }\\n\\n  function projectIdFromPath(path) {\\n    var m = /^\\\\/work\\\\/projects\\\\/([^/]+)$/.exec(path || \'\');\\n    if (!m) return \'\';\\n    try { return decodeURIComponent(m[1]); } catch (e) { return m[1]; }\\n  }\\n\\n  /* ---------- 7.6 /work/log（别名 /work/logs）工作日志 ---------- */\\n\\n  var workLog = {\\n    title: \'工作日志\',\\n    _date: \'\',\\n    _editing: false,\\n    render: function () {\\n      var d = this._date || todayStr();\\n      var rec = getLogs().filter(function (l) { return l.date === d; })[0] || null;\\n\\n      /* 自动聚合当天已完成待办作为初始内容 */\\n      if (!rec) {\\n        var doneToday = getTodos().filter(function (t) {\\n          return t.done && ((t.completedAt && t.completedAt.slice(0, 10) === d) || t.due === d);\\n        });\\n        if (doneToday.length) {\\n          var content = \'【今日完成】\\\\n\' + doneToday.map(function (t) { return \'- \' + t.title; }).join(\'\\\\n\') + \'\\\\n\';\\n          rec = window.App.store.logs.add({ date: d, content: content, autoGen: true });\\n        }\\n      } else if (!rec.content && !rec.autoGen) {\\n        var done2 = getTodos().filter(function (t) {\\n          return t.done && ((t.completedAt && t.completedAt.slice(0, 10) === d) || t.due === d);\\n        });\\n        if (done2.length) {\\n          rec = window.App.store.logs.update(rec.id, {\\n            content: \'【今日完成】\\\\n\' + done2.map(function (t) { return \'- \' + t.title; }).join(\'\\\\n\') + \'\\\\n\',\\n            autoGen: true\\n          });\\n        }\\n      }\\n\\n      var content = rec ? (rec.content || \'\') : \'\';\\n      var editing = this._editing;\\n      var dateObj = new Date(d.replace(/-/g, \'/\'));\\n      var week = [\'日\', \'一\', \'二\', \'三\', \'四\', \'五\', \'六\'][dateObj.getDay()];\\n      var dateLabel = dateObj.getFullYear() + \'年\' + (dateObj.getMonth() + 1) + \'月\' + dateObj.getDate() + \'日\';\\n\\n      /* 当天时间线：各时段完成的任务节点 */\\n      var tl = getTodos().filter(function (t) {\\n        return t.done && t.completedAt && t.completedAt.slice(0, 10) === d;\\n      }).sort(function (a, b) {\\n        return String(a.completedAt).localeCompare(String(b.completedAt));\\n      });\\n      var tlHtml = tl.length\\n        ? tl.map(function (t) {\\n            return \'<div class=\\\"work-tl-node\\\"><div class=\\\"work-tl-time\\\">\' + hmOf(t.completedAt) + \'</div>\' +\\n              \'<div class=\\\"work-tl-text\\\">\' + esc(t.title) + \'</div></div>\';\\n          }).join(\'\')\\n        : \'<div class=\\\"work-tl-empty\\\">\' + (d === todayStr() ? \'今天还没有已完成的任务节点\' : \'这一天没有完成任务记录\') + \'</div>\';\\n\\n      return \'<div class=\\\"page work-page\\\" data-page=\\\"work-log\\\">\' +\\n        \'<div class=\\\"work-log-picker\\\">\' +\\n        \'<button class=\\\"icon-btn\\\" data-act=\\\"prev-day\\\" aria-label=\\\"前一天\\\">\' + icon(\'chevL\', 20) + \'</button>\' +\\n        \'<div class=\\\"date-main\\\">\' + dateLabel + \'<span class=\\\"date-sub\\\">星期\' + week + \'</span></div>\' +\\n        \'<button class=\\\"icon-btn\\\" data-act=\\\"next-day\\\" aria-label=\\\"后一天\\\">\' + icon(\'chevR\', 20) + \'</button>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"work-log-layout\\\">\' +\\n        \'<section class=\\\"glass-card\\\">\' +\\n        (editing\\n          ? \'<textarea class=\\\"work-log-edit\\\" data-act=\\\"editor\\\" placeholder=\\\"记录今天的工作…\\\">\' + esc(content) + \'</textarea>\'\\n          : \'<div class=\\\"work-log-body\\\">\' + esc(content || \'\') + \'</div>\') +\\n        \'<div class=\\\"work-toolbar\\\">\' +\\n        \'<button class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"toggle-edit\\\">\' + icon(\'pen\', 15) + (editing ? \'完成\' : \'编辑\') + \'</button>\' +\\n        \'<button class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"gen-week\\\">\' + icon(\'calendar\', 15) + \'生成周报</button>\' +\\n        \'<button class=\\\"btn btn-ghost btn-sm\\\" data-act=\\\"gen-month\\\">\' + icon(\'calendar\', 15) + \'生成月报</button>\' +\\n        (editing ? \'<span class=\\\"muted\\\" style=\\\"font-size:0.78rem;align-self:center\\\">内容自动保存</span>\' : \'\') +\\n        \'</div>\' +\\n        \'</section>\' +\\n        \'<aside class=\\\"glass-card\\\" style=\\\"padding:16px 14px\\\">\' +\\n        \'<div style=\\\"font-weight:650;font-size:0.92rem;margin-bottom:10px;display:flex;align-items:center;gap:6px\\\">\' + icon(\'clock\', 16) + \'完成时间线</div>\' +\\n        \'<div class=\\\"work-timeline\\\">\' + tlHtml + \'</div>\' +\\n        \'</aside>\' +\\n        \'</div></div>\';\\n    },\\n    mount: function (el, path) {\\n      if (this._cleanup) this._cleanup();\\n      var self = this;\\n      activeWorkPage = self;\\n      self._date = self._date || todayStr();\\n      var saveTimer = null;\\n\\n      function saveContent(value) {\\n        var d = self._date;\\n        var rec = getLogs().filter(function (l) { return l.date === d; })[0];\\n        if (rec) {\\n          window.App.store.logs.update(rec.id, { content: value });\\n        } else {\\n          window.App.store.logs.add({ date: d, content: value, autoGen: false });\\n        }\\n      }\\n\\n      function onClick(e) {\\n        var prev = e.target.closest(\'[data-act=\\\"prev-day\\\"]\');\\n        if (prev) {\\n          var d = new Date(self._date.replace(/-/g, \'/\'));\\n          d.setDate(d.getDate() - 1);\\n          self._date = dateStr(d);\\n          refreshWorkPage();\\n          return;\\n        }\\n        var next = e.target.closest(\'[data-act=\\\"next-day\\\"]\');\\n        if (next) {\\n          var d2 = new Date(self._date.replace(/-/g, \'/\'));\\n          d2.setDate(d2.getDate() + 1);\\n          self._date = dateStr(d2);\\n          refreshWorkPage();\\n          return;\\n        }\\n        var edit = e.target.closest(\'[data-act=\\\"toggle-edit\\\"]\');\\n        if (edit) {\\n          var editor = $(\'[data-act=\\\"editor\\\"]\', el);\\n          if (editor && editor.value !== undefined) saveContent(editor.value);\\n          self._editing = !self._editing;\\n          refreshWorkPage();\\n          return;\\n        }\\n        var gw = e.target.closest(\'[data-act=\\\"gen-week\\\"]\');\\n        if (gw) { openRangePicker(\'week\'); return; }\\n        var gm = e.target.closest(\'[data-act=\\\"gen-month\\\"]\');\\n        if (gm) { openRangePicker(\'month\'); return; }\\n      }\\n\\n      function onInput(e) {\\n        var editor = e.target.closest(\'[data-act=\\\"editor\\\"]\');\\n        if (!editor) return;\\n        clearTimeout(saveTimer);\\n        saveTimer = setTimeout(function () { saveContent(editor.value); }, 600);\\n      }\\n\\n      /* 周报 / 月报：日期范围选择 + 聚合预览 */\\n      function openRangePicker(kind) {\\n        var now = new Date();\\n        var defaultStart, defaultEnd = todayStr();\\n        if (kind === \'week\') {\\n          var day = now.getDay() || 7;\\n          var mon = new Date(now);\\n          mon.setDate(now.getDate() - day + 1);\\n          defaultStart = dateStr(mon);\\n        } else {\\n          defaultStart = now.getFullYear() + \'-\' + pad2(now.getMonth() + 1) + \'-01\';\\n        }\\n        var html = \'<form data-form=\\\"range\\\" onsubmit=\\\"return false\\\">\' +\\n          \'<div class=\\\"work-picker-row\\\"><label>开始日期</label><input class=\\\"input\\\" data-f=\\\"start\\\" type=\\\"date\\\" value=\\\"\' + defaultStart + \'\\\"></div>\' +\\n          \'<div class=\\\"work-picker-row\\\"><label>结束日期</label><input class=\\\"input\\\" data-f=\\\"end\\\" type=\\\"date\\\" value=\\\"\' + defaultEnd + \'\\\"></div>\' +\\n          \'<div class=\\\"work-form-row\\\"><label>预览</label><div class=\\\"work-preview\\\" data-f=\\\"preview\\\">选择范围后点「生成预览」</div></div></form>\';\\n        openModal({\\n          title: kind === \'week\' ? \'生成周报\' : \'生成月报\',\\n          content: html,\\n          okText: \'生成预览\',\\n          onOk: function (mask) {\\n            var start = $(\'[data-f=\\\"start\\\"]\', mask).value;\\n            var end = $(\'[data-f=\\\"end\\\"]\', mask).value;\\n            if (!start || !end || start > end) { uiToast(\'日期范围无效\', \'warn\'); return false; }\\n            $(\'[data-f=\\\"preview\\\"]\', mask).textContent = buildReport(kind, start, end);\\n            return false; /* 保持弹窗打开，展示预览 */\\n          }\\n        });\\n        /* 为预览模态提供「复制」能力：二次接线 */\\n        setTimeout(function () {\\n          var masks = $$(\'.modal-mask\');\\n          var last = masks[masks.length - 1];\\n          if (last) {\\n            var foot = $(\'.modal-foot\', last);\\n            if (foot) {\\n              var copyBtn = document.createElement(\'button\');\\n              copyBtn.type = \'button\';\\n              copyBtn.className = \'btn btn-ghost\';\\n              copyBtn.textContent = \'复制报告\';\\n              copyBtn.style.marginRight = \'auto\';\\n              copyBtn.addEventListener(\'click\', function () {\\n                var preview = $(\'[data-f=\\\"preview\\\"]\', last);\\n                if (!preview || !preview.textContent.trim() || preview.textContent === \'选择范围后点「生成预览」\') {\\n                  uiToast(\'请先生成预览\', \'warn\');\\n                  return;\\n                }\\n                copyText(preview.textContent);\\n              });\\n              foot.insertBefore(copyBtn, foot.firstChild);\\n            }\\n          }\\n        }, 40);\\n      }\\n\\n      function buildReport(kind, start, end) {\\n        var logs = getLogs().filter(function (l) { return l.date >= start && l.date <= end; })\\n          .sort(function (a, b) { return a.date.localeCompare(b.date); });\\n        var doneTodos = getTodos().filter(function (t) {\\n          return t.done && t.completedAt && t.completedAt.slice(0, 10) >= start && t.completedAt.slice(0, 10) <= end;\\n        });\\n        var lines = [];\\n        lines.push(kind === \'week\' ? \'【工作周报】\' : \'【工作月报】\');\\n        lines.push(\'时间范围：\' + start + \' ~ \' + end);\\n        lines.push(\'\');\\n        lines.push(\'一、完成事项（\' + doneTodos.length + \' 项）\');\\n        if (doneTodos.length) {\\n          doneTodos.forEach(function (t) {\\n            lines.push(\'- [\' + t.completedAt.slice(0, 10) + \'] \' + t.title);\\n          });\\n        } else {\\n          lines.push(\'（该时间段内暂无已完成待办）\');\\n        }\\n        lines.push(\'\');\\n        lines.push(\'二、工作日志\');\\n        if (logs.length) {\\n          logs.forEach(function (l) {\\n            lines.push(\'【\' + l.date + \'】\' + (l.content || \'（无内容）\'));\\n          });\\n        } else {\\n          lines.push(\'（该时间段内暂无日志）\');\\n        }\\n        lines.push(\'\');\\n        lines.push(\'三、统计\');\\n        lines.push(\'- 完成待办：\' + doneTodos.length + \' 项\');\\n        lines.push(\'- 有日志天数：\' + logs.length + \' 天\');\\n        return lines.join(\'\\\\n\');\\n      }\\n\\n      function copyText(text) {\\n        if (navigator.clipboard && navigator.clipboard.writeText) {\\n          navigator.clipboard.writeText(text).then(function () {\\n            uiToast(\'已复制到剪贴板\', \'success\');\\n          }, function () { fallbackCopy(text); });\\n        } else {\\n          fallbackCopy(text);\\n        }\\n      }\\n      function fallbackCopy(text) {\\n        var ta = document.createElement(\'textarea\');\\n        ta.value = text;\\n        ta.style.position = \'fixed\';\\n        ta.style.opacity = \'0\';\\n        document.body.appendChild(ta);\\n        ta.select();\\n        try { document.execCommand(\'copy\'); uiToast(\'已复制到剪贴板\', \'success\'); } catch (e) { uiToast(\'复制失败\', \'error\'); }\\n        ta.remove();\\n      }\\n\\n      el.addEventListener(\'click\', onClick);\\n      el.addEventListener(\'input\', onInput);\\n\\n      this._cleanup = function () {\\n        el.removeEventListener(\'click\', onClick);\\n        el.removeEventListener(\'input\', onInput);\\n        if (saveTimer) clearTimeout(saveTimer);\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  /* ---------- 7.7 /work/meetings 会议记录 ---------- */\\n\\n  function avatarHtml(name, i) {\\n    var c = AVATAR_COLORS[i % AVATAR_COLORS.length];\\n    return \'<span class=\\\"work-avatar\\\" style=\\\"background:\' + c + \'\\\" title=\\\"\' + esc(name) + \'\\\">\' + esc((name || \'?\').trim().charAt(0) || \'?\') + \'</span>\';\\n  }\\n\\n  function meetingCardHtml(m) {\\n    var attendees = (m.attendees || []).filter(Boolean);\\n    var todos = (m.todos || []).filter(function (t) { return !t.done; });\\n    return \'<div class=\\\"work-meet-card glass-card\\\" data-id=\\\"\' + esc(m.id) + \'\\\">\' +\\n      \'<div class=\\\"work-meet-head\\\" data-act=\\\"toggle\\\">\' +\\n      \'<div style=\\\"flex:1;min-width:0\\\">\' +\\n      \'<div class=\\\"work-meet-title\\\">\' + esc(m.title || \'未命名会议\') + \'</div>\' +\\n      \'<div class=\\\"work-meet-sub\\\">\' +\\n      \'<span class=\\\"work-meet-dt\\\">\' + icon(\'calendar\', 14) + esc(m.datetime || \'\') + \'</span>\' +\\n      (attendees.length ? \'<span class=\\\"work-meet-avatars\\\">\' + attendees.map(avatarHtml).join(\'\') + \'</span>\' : \'\') +\\n      \'</div>\' +\\n      \'<div class=\\\"work-meet-summary\\\">\' + esc(m.summary || \'（暂无摘要）\') + \'</div>\' +\\n      \'</div>\' +\\n      \'<span class=\\\"chev\\\">\' + icon(\'chevron\', 17) + \'</span>\' +\\n      \'</div>\' +\\n      \'<div class=\\\"work-meet-body\\\"><div class=\\\"work-meet-body-inner\\\">\' +\\n      \'<div class=\\\"work-meet-sec\\\"><h4>\' + icon(\'clock\', 13) + \'时间</h4><p>\' + esc(m.datetime || \'—\') + \'</p></div>\' +\\n      \'<div class=\\\"work-meet-sec\\\"><h4>\' + icon(\'users\', 13) + \'参会人</h4><p>\' + (attendees.length ? attendees.map(esc).join(\'、\') : \'—\') + \'</p></div>\' +\\n      \'<div class=\\\"work-meet-sec\\\"><h4>\' + icon(\'info\', 13) + \'议题</h4><p>\' + esc(m.agenda || \'—\') + \'</p></div>\' +\\n      \'<div class=\\\"work-meet-sec\\\"><h4>\' + icon(\'check\', 13) + \'决议</h4><p>\' + esc(m.decisions || \'—\') + \'</p></div>\' +\\n      \'<div class=\\\"work-meet-sec\\\"><h4>\' + icon(\'todo\', 13) + \'待办</h4>\' +\\n      ((m.todos || []).length ? (m.todos || []).map(function (t, ti) {\\n        return \'<div class=\\\"work-meet-todo\' + (t.done ? \' done\' : \'\') + \'\\\" data-ti=\\\"\' + ti + \'\\\">\' +\\n          \'<span class=\\\"txt\\\">\' + esc(t.text) + \'</span>\' +\\n          (t.done && t.linked\\n            ? \'<span class=\\\"linked\\\">\' + icon(\'check\', 13) + \' 已加入今日待办</span>\'\\n            : \'<button type=\\\"button\\\" class=\\\"link-btn\\\" data-act=\\\"link-todo\\\">\' + icon(\'link\', 13) + \'加入今日待办</button>\') +\\n          \'</div>\';\\n      }).join(\'\') : \'<p class=\\\"muted\\\">暂无待办</p>\') +\\n      \'</div>\' +\\n      \'</div></div></div>\';\\n  }\\n\\n  var workMeetings = {\\n    title: \'会议记录\',\\n    render: function () {\\n      var list = getMeetings().slice().sort(function (a, b) {\\n        return String(b.datetime || b.createdAt || \'\').localeCompare(String(a.datetime || a.createdAt || \'\'));\\n      });\\n      return \'<div class=\\\"page work-page\\\" data-page=\\\"work-meetings\\\">\' +\\n        \'<div class=\\\"work-bar\\\">\' +\\n        \'<div class=\\\"work-bar-left\\\"><span class=\\\"muted\\\" style=\\\"font-size:0.88rem\\\">共 \' + list.length + \' 条记录 · 点击展开详情</span></div>\' +\\n        \'<button class=\\\"btn btn-primary\\\" data-act=\\\"new-meet\\\">\' + icon(\'plus\', 16) + \'新建会议记录</button>\' +\\n        \'</div>\' +\\n        \'<div class=\\\"work-meet-list\\\">\' +\\n        (list.length ? list.map(meetingCardHtml).join(\'\') :\\n          \'<div class=\\\"empty-state\\\"><div class=\\\"empty-icon\\\">\' + icon(\'meeting\', 34) + \'</div>还没有会议记录，点击右上角新建</div>\') +\\n        \'</div></div>\';\\n    },\\n    mount: function (el) {\\n      if (this._cleanup) this._cleanup();\\n      activeWorkPage = this;\\n\\n      function onClick(e) {\\n        var head = e.target.closest(\'[data-act=\\\"toggle\\\"]\');\\n        if (head) {\\n          var card = head.closest(\'.work-meet-card\');\\n          card.classList.toggle(\'open\');\\n          return;\\n        }\\n        var linkBtn = e.target.closest(\'[data-act=\\\"link-todo\\\"]\');\\n        if (linkBtn) {\\n          var todoRow = linkBtn.closest(\'.work-meet-todo\');\\n          var card2 = linkBtn.closest(\'.work-meet-card\');\\n          var m = window.App.store.meetings.get(card2.getAttribute(\'data-id\'));\\n          if (!m) return;\\n          var ti = Number(todoRow.getAttribute(\'data-ti\'));\\n          var todos = (m.todos || []).slice();\\n          if (!todos[ti]) return;\\n          window.App.store.todos.add({\\n            title: todos[ti].text,\\n            quadrant: \'q2\', priority: \'mid\',\\n            due: todayStr(), done: false, projectId: \'\'\\n          });\\n          todos[ti] = Object.assign({}, todos[ti], { done: true, linked: true });\\n          window.App.store.meetings.update(m.id, { todos: todos });\\n          uiToast(\'已加入今日待办\', \'success\');\\n          /* 局部更新该行 */\\n          todoRow.classList.add(\'done\');\\n          linkBtn.outerHTML = \'<span class=\\\"linked\\\">\' + icon(\'check\', 13) + \' 已加入今日待办</span>\';\\n          return;\\n        }\\n        var nm = e.target.closest(\'[data-act=\\\"new-meet\\\"]\');\\n        if (nm) openMeetingForm(null);\\n      }\\n\\n      el.addEventListener(\'click\', onClick);\\n      this._cleanup = function () {\\n        el.removeEventListener(\'click\', onClick);\\n      };\\n    },\\n    unmount: function () { if (this._cleanup) this._cleanup(); this._cleanup = null; }\\n  };\\n\\n  /* 会议表单：标准模板一键填充 */\\n  function openMeetingForm(m) {\\n    var data = m || {};\\n    var now = new Date();\\n    var defaultDt = dateStr(now) + \' \' + pad2(now.getHours()) + \':\' + pad2(now.getMinutes());\\n    var html = \'<form data-form=\\\"meet\\\" onsubmit=\\\"return false\\\">\' +\\n      \'<div class=\\\"work-form-row\\\"><label class=\\\"required\\\">会议主题</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"title\\\" type=\\\"text\\\" value=\\\"\' + esc(data.title || \'\') + \'\\\" placeholder=\\\"会议主题\\\" autocomplete=\\\"off\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>日期时间</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"datetime\\\" type=\\\"datetime-local\\\" value=\\\"\' + esc(data.datetime || defaultDt) + \'\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>参会人（逗号分隔）</label>\' +\\n      \'<input class=\\\"input\\\" data-f=\\\"attendees\\\" type=\\\"text\\\" value=\\\"\' + esc((data.attendees || []).join(\'、\')) + \'\\\" placeholder=\\\"如：李工、王工、我\\\" autocomplete=\\\"off\\\"></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>议题</label>\' +\\n      \'<textarea class=\\\"textarea\\\" data-f=\\\"agenda\\\" placeholder=\\\"本次会议讨论什么…\\\" style=\\\"min-height:60px\\\">\' + esc(data.agenda || \'\') + \'</textarea></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>决议</label>\' +\\n      \'<textarea class=\\\"textarea\\\" data-f=\\\"decisions\\\" placeholder=\\\"达成的决议…\\\" style=\\\"min-height:60px\\\">\' + esc(data.decisions || \'\') + \'</textarea></div>\' +\\n      \'<div class=\\\"work-form-row\\\"><label>待办（每行一条）</label>\' +\\n      \'<textarea class=\\\"textarea\\\" data-f=\\\"todos\\\" placeholder=\\\"每条待办占一行\\\" style=\\\"min-height:64px\\\">\' +\\n      esc((data.todos || []).map(function (t) { return t.text; }).join(\'\\\\n\')) + \'</textarea></div></form>\';\\n    openModal({\\n      title: m ? \'编辑会议记录\' : \'新建会议记录\',\\n      content: html,\\n      okText: m ? \'保存\' : \'创建\',\\n      onOk: function (mask) {\\n        var title = $(\'[data-f=\\\"title\\\"]\', mask).value.trim();\\n        if (!title) { uiToast(\'请输入会议主题\', \'warn\'); return false; }\\n        var attendees = $(\'[data-f=\\\"attendees\\\"]\', mask).value.split(/[,，、\\\\s]+/).filter(Boolean);\\n        var todoTexts = $(\'[data-f=\\\"todos\\\"]\', mask).value.split(\'\\\\n\').map(function (s) { return s.trim(); }).filter(Boolean);\\n        var patch = {\\n          title: title,\\n          datetime: $(\'[data-f=\\\"datetime\\\"]\', mask).value || defaultDt,\\n          attendees: attendees,\\n          agenda: $(\'[data-f=\\\"agenda\\\"]\', mask).value.trim(),\\n          decisions: $(\'[data-f=\\\"decisions\\\"]\', mask).value.trim(),\\n          summary: $(\'[data-f=\\\"decisions\\\"]\', mask).value.trim() || $(\'[data-f=\\\"agenda\\\"]\', mask).value.trim(),\\n          todos: todoTexts.map(function (t) { return { text: t, done: false, linked: false }; })\\n        };\\n        if (m) {\\n          window.App.store.meetings.update(m.id, patch);\\n          uiToast(\'已保存\', \'success\');\\n        } else {\\n          window.App.store.meetings.add(patch);\\n          uiToast(\'已创建会议记录\', \'success\');\\n        }\\n        refreshWorkPage();\\n        return true;\\n      }\\n    });\\n  }\\n\\n  /* ======================= 8. 注册 ======================= */\\n\\n  function registerAll() {\\n    if (!window.App || typeof App.registerPage !== \'function\') return false;\\n\\n    App.registerPage(\'/work\', workOverview);\\n    App.registerPage(\'/work/todos\', workTodos);\\n    App.registerPage(\'/work/inbox\', workInbox);\\n    App.registerPage(\'/work/projects\', workProjects);\\n    App.registerPage(\'/work/projects/:id\', projectDetail); /* 字面占位，实际由动态注册接管 */\\n    App.registerPage(\'/work/log\', workLog);\\n    App.registerPage(\'/work/logs\', workLog); /* 侧边栏与全局搜索使用复数路径 */\\n    App.registerPage(\'/work/meetings\', workMeetings);\\n    return true;\\n  }\\n\\n  /* 动态路由：/work/projects/<id> —— 骨架 router 仅精确匹配，这里按需注册精确路径 */\\n  function handleDynamicProjectRoute() {\\n    var path = currentHashPath();\\n    var m = /^\\\\/work\\\\/projects\\\\/([^/]+)$/.exec(path);\\n    if (!m) return false;\\n    var id = decodeURIComponent(m[1]);\\n    if (!window.App.store.projects.get(id)) {\\n      /* 项目不存在：交给 404 兜底 */\\n      return false;\\n    }\\n    var registered = true;\\n    try {\\n      App.registerPage(path, projectDetail);\\n    } catch (e) { registered = false; }\\n    if (!registered) return false;\\n    /* 若当前渲染的并非详情页（例如 404 兜底），同步刷新一次 */\\n    if (routerCurrent() === path) {\\n      try { App.refresh(); } catch (e) { /* ignore */ }\\n    }\\n    return true;\\n  }\\n\\n  function initDynamicRouting() {\\n    window.addEventListener(\'hashchange\', function () {\\n      handleDynamicProjectRoute();\\n    });\\n    if (document.readyState === \'loading\') {\\n      document.addEventListener(\'DOMContentLoaded\', function () {\\n        handleDynamicProjectRoute();\\n      });\\n    } else {\\n      handleDynamicProjectRoute();\\n    }\\n  }\\n\\n  /* 等待骨架就绪后注册（防御：页面脚本可能在 app.js 之前执行） */\\n  function boot() {\\n    if (!storeReady()) { setTimeout(boot, 120); return; }\\n    registerAll();\\n    initDynamicRouting();\\n  }\\n\\n  if (document.readyState === \'loading\') {\\n    document.addEventListener(\'DOMContentLoaded\', boot);\\n  } else {\\n    boot();\\n  }\\n})();\",\"old_str\":\"  /*__PART3__*/\",\"path\":\"D:\\\\Project\\\\Project\\\\ccee\\\\web1\\\\js\\\\pages\\\\work.js\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 13:38:55');
