esults.forEach(r => {\\n  console.log((r.ok ? \'[OK] \' : \'[FAIL] \') + r.name + (r.extra ? \' :: \' + r.extra : \'\'));\\n});\\nprocess.exit(fail > 0 ? 1 : 0);\\n\'\'\'\\n\\nscript_path = os.path.join(os.environ.get(\'TEMP\', \'.\'), \'work_smoke_test2.js\')\\nwith open(script_path, \'w\', encoding=\'utf-8\') as f:\\n    f.write(test_js)\\n\\nr = subprocess.run([r\'D:\\\\nodejs\\\\node.exe\', script_path], capture_output=True, text=True, timeout=60)\\nprint(r.stdout[-8000:])\\nprint(\'---STDERR---\')\\nprint(r.stderr[-2000:])\\nprint(\'exit:\', r.returncode)\\n\"},\"effect\":\"write\",\"risk_level\":\"high\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 14:02:11'),
