removeItem() {} };\\n\\nconst App = {\\n  registerPage(p, def) { registered.push({ path: p, def }); },\\n  navigate(p) { location.hash = \'#\' + p; },\\n  refresh() { refreshCalls++; },\\n  showToast() {},\\n  openModal() { return null; },\\n  closeModal() {},\\n  icon(name, size) { return \'<svg class=\\\"icon\\\" width=\\\"\' + (size||18) + \'\\\"><use href=\\\"#i-\' + name + \'\\\"></use></svg>\'; },\\n  escapeHtml(s) { return String(s == null ? \'\' : s).replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\').replace(/\\\"/g,\'&quot;\').replace(/\'/g,\'&#39;\'); },\\n  uid: uid,\\n  formatDate(d) { return String(d); },\\n  store: store,\\n  version: \'0.1.0\'\\n};\\n\\nfunction FakeCustomEvent() { return {}; }\\n\\nconst sandbox = {\\n  window: null, document, location, localStorage, navigator: {}, console,\\n  App, CustomEvent: FakeCustomEvent,\\n  setTimeout, clearTimeout, Date, Math, JSON, Object, Array, String, Number, Boolean, RegExp, Error\\n};\\nsandbox.window = sandbox;\\nsandbox.WorkbenchRouter = { current() { return routerCurrentPath; } };\\nsandbox.window.WorkbenchRouter = sandbox.WorkbenchRouter;\\nsandbox.window.App = App;\\n\\nvm.createContext(sandbox);\\ntry {\\n  vm.runInContext(src, sandbox, { filename: \'work.js\' });\\n  check(\'exec-no-throw\', true);\\n} catch (e) {\\n  check(\'exec-no-throw\', false, e && e.stack ? String(e.stack).slice(0, 1500) : String(e));\\n}\\n\\nconst paths = registered.map(r => r.path).sort();\\nconst expectPaths = [\'/work\', \'/work/todos\', \'/work/inbox\', \'/work/projects\', \'/work/projects/:id\', \'/work/log\', \'/work/logs\', \'/work/meetings\'].sort();\\ncheck(\'registered-paths\', JSON.stringify(paths) === JSON.stringify(expectPaths), \'got=\' + JSON.stringify(paths));\\n\\nfunction pageDef(p) { const r = registered.find(x => x.path === p); return r ? r.def : null; }\\nfunction tryRender(p, pathArg) {\\n  const def = pageDef(p);\\n  if (!def) return { html: \'\', err: \'not registered\' };\\n  try {\\n    const html = def.render(pathArg || p);\\n    return { html: html || \'\', err: null };\\n  } catch (e) {\\n    return { html: \'\', err: String(e && e.stack || e).slice(0, 800) };\\n  }\\n}\\n\\nconst renderChecks = [\\n  [\'/work\', \'work-overview\', \'今日待办\'],\\n  [\'/work/todos\', \'work-todos\', \'重要紧急\'],\\n  [\'/work/inbox\', \'work-inbox\', \'未清理\'],\\n  [\'/work/projects\', \'work-projects\', \'新建项目\'],\\n  [\'/work/log\', \'work-log\', \'生成周报\'],\\n  [\'/work/logs\', \'work-log\', \'生成月报\'],\\n  [\'/work/meetings\', \'work-meetings\', \'新建会议记录\']\\n];\\nrenderChecks.forEach(([p, marker, keyword]) => {\\n  const r = tryRender(p);\\n  check(\'render-\' + p, !r.err && r.html.indexOf(marker) >= 0 && r.html.indexOf(keyword) >= 0,\\n    r.err ? r.err : (\'len=\' + r.html.length + \' marker=\' + r.html.indexOf(marker) + \' kw=\' + r.html.indexOf(keyword)));\\n});\\n\\nconst d = tryRender(\'/work/projects/:id\', \'/work/projects/seed-proj-1\');\\ncheck(\'render-detail\', !d.err && d.html.indexOf(\'产品 3.0 改版\') >= 0 && d.html.indexOf(\'work-tabs\') >= 0 && d.html.indexOf(\'任务\') >= 0, d.err || \'len=\' + d.html.length);\\nconst d2 = tryRender(\'/work/projects/:id\', \'/work/projects/nonexistent\');\\ncheck(\'render-detail-404\', !d2.err && d2.html.indexOf(\'项目不存在\') >= 0, d2.err || \'\');\\n\\nfunction tryMount(p, pathArg) {\\n  const def = pageDef(p);\\n  if (!def || typeof def.mount !== \'function\') return \'no mount\';\\n  try { def.mount(document.body, pathArg || p); return null; }\\n  catch (e) { return String(e && e.stack || e).slice(0, 800); }\\n}\\n[\'/work\', \'/work/todos\', \'/work/inbox\', \'/work/projects\', \'/work/log\', \'/work/meetings\'].forEach(p => {\\n  const err = tryMount(p);\\n  check(\'mount-\' + p, !err, err || \'\');\\n});\\nconst mErr = tryMount(\'/work/projects/:id\', \'/work/projects/seed-proj-1\');\\ncheck(\'mount-detail\', !mErr, mErr || \'\');\\n\\nconst nt = store.todos.add({ title: \'新待办\', quadrant: \'q2\', priority: \'low\', due: dstr(0), done: false, projectId: \'\' });\\ncheck(\'store-todos-add\', !!nt.id && store.todos.list().length === 3, \'len=\' + store.todos.list().length);\\nstore.inbox.update(\'seed-inbox-1\', { done: true });\\ncheck(\'store-inbox-update\', store.inbox.get(\'seed-inbox-1\').done === true);\\nstore.projects.update(\'seed-proj-1\', { sort: 1 });\\ncheck(\'store-projects-sort\', store.projects.get(\'seed-proj-1\').sort === 1);\\n\\n/* 动态路由 */\\nrouterCurrentPath = \'/work/projects/seed-proj-1\';\\nlocation.hash = \'#/work/projects/seed-proj-1\';\\nhashListeners.forEach(fn => { try { fn(); } catch (e) { check(\'hash-listener-throw\', false, String(e)); } });\\nconst dyn = registered.filter(r => r.path === \'/work/projects/seed-proj-1\');\\ncheck(\'dynamic-register\', dyn.length === 1 && typeof dyn[0].def.render === \'function\', \'count=\' + dyn.length);\\ncheck(\'dynamic-refresh\', refreshCalls >= 1, \'calls=\' + refreshCalls);\\nrouterCurrentPath = \'/work/projects/ghost\';\\nlocation.hash = \'#/work/projects/ghost\';\\nhashListeners.forEach(fn => { try { fn(); } catch (e) {} });\\ncheck(\'dynamic-ghost-skip\', registered.filter(r => r.path === \'/work/projects/ghost\').length === 0);\\n\\n/* 日志自动聚合：当天有已完成待办且无日志的日期 */\\nconst r3 = tryRender(\'/work/log\', \'/work/log\');  // 今天已有 seed-log-1\\ncheck(\'log-render-again\', !r3.err, r3.err || \'\');\\n/* 清除今天日志后 render 应自动聚合 */\\nstore.logs.clear();\\nconst logsBefore = store.logs.list().length;\\nconst r4 = tryRender(\'/work/log\', \'/work/log\');\\nconst logsAfter = store.logs.list().length;\\ncheck(\'log-auto-aggregate\', !r4.err && logsAfter > logsBefore, \'before=\' + logsBefore + \' after=\' + logsAfter + (r4.err ? \' err=\' + r4.err : \'\'));\\n\\n/* 会议卡片与详情模板 */\\nconst rm = tryRender(\'/work/meetings\', \'/work/meetings\');\\ncheck(\'meetings-template\', !rm.err && rm.html.indexOf(\'参会人\') >= 0 && rm.html.indexOf(\'决议\') >= 0, rm.err || \'\');\\n\\nlet pass = 0, fail = 0;\\nresults.forEach(r => { if (r.ok) pass++; else fail++; });\\nconsole.log(\'PASS=\' + pass + \' FAIL=\' + fail);\\nresults.forEach(r => {\\n  console.log((r.ok ? \'[OK] \' : \'[FAIL] \') + r.name + (r.extra ? \' :: \' + r.extra : \'\'));\\n});\\nprocess.exit(fail > 0 ? 1 : 0);\\n\'\'\'\\n\\nscript_path = os.path.join(os.environ.get(\'TEMP\', \'.\'), \'work_smoke_test2.js\')\\nwith open(script_path, \'w\', encoding=\'utf-8\') as f:\\n    f.write(test_js)\\n\\nr = subprocess.run([r\'D:\\\\nodejs\\\\node.exe\', script_path], capture_output=True, text=True, timeout=60)\\nprint(r.stdout[-8000:])\\nprint(\'---STDERR---\')\\nprint(r.stderr[-2000:])\\nprint(\'exit:\', r.returncode)\\n\"}}', '2026-08-03 14:02:11'),
(1254, '40122540-fcbb-4890-9b07-1296c60efc8f', 158705, 'approval.decided', 'code', 'moonya', 'pages_work', 'call_00_G0asi7gdenz31sG1LS233388', '{\"approval_id\":\"059bd6aa-3917-4821-8fb7-afe73e392a65\",\"status\":\"allowed\"}', '2026-08-03 14:02:13'),
(1255, '40122540-fcbb-4890-9b07-1296c60efc8f', 158706, 'tool.completed', 'code', 'moonya', 'pages_work', 'call_00_G0asi7gdenz31sG1LS233388', '{\"tool_key\":\"python_executor\",\"ok\":true,\"content\":\"PASS=24 FAIL=3\\r\\n[FAIL] exec-no-throw :: work.js:2303\\r\\n    window.addEventListener(\'hashchange\', function () {\\r\\n           ^\\r\\n\\r\\nTypeError: window.addEventListener is not a function\\r\\n    at initDynamicRouting (work.js:2303:12)\\r\\n    at boot (work.js:2319:5)\\r\\n    at work.js:2325:5\\r\\n    at work.js:2327:3\\r\\n    at Script.runInContext (node:vm:149:12)\\r\\n    at Object.runInContext (node:vm:301:6)\\r\\n    at Object.<anonymous> (C:\\\\Users\\\\Administrator\\\\AppData\\\\Local\\\\Temp\\\\work_smoke_test2.js:139:6)\\r\\n    at Module._compile (node:internal/modules/cjs/loader:1830:14)\\r\\n    at Object..js (node:internal/modules/cjs/loader:1961:10)\\r\\n    at Module.load (node:internal/modules/cjs/loader:1553:32)\\r\\n[OK] registered-paths :: got=[\\\"/work\\\",\\\"/work/inbox\\\",\\\"/work/log\\\",\\\"/work/logs\\\",\\\"/work/meetings\\\",\\\"/work/projects\\\",\\\"/work/projects/:id\\\",\\\"/work/todos\\\"]\\r\\n[OK] render-/work :: len=1525 marker=39 kw=526\\r\\n[OK] render-/work/todos :: len=8125 marker=39 kw=709\\r\\n[OK] render-/work/inbox :: len=2448 marker=39 kw=399\\r\\n[OK] render-/work/projects :: len=3486 marker=39 kw=465\\r\\n[OK] render-/work/log :: len=1688 marker=39 kw=1133\\r\\n[OK] render-/work/logs :: len=1688 marker=39 kw=1269\\r\\n[OK] render-/work/meetings :: len=2230 marker=39 kw=291\\r\\n[OK] render-detail :: len=1895\\r\\n[OK] render-detail-404\\r\\n[OK] mount-/work\\r\\n[OK] mount-/work/todos\\r\\n[OK] mount-/work/inbox\\r\\n[OK] mount-/work/projects\\r\\n[OK] mount-/work/log\\r\\n[OK] mount-/work/meetings\\r\\n[OK] mount-detail\\r\\n[OK] store-todos-add :: len=3\\r\\n[OK] store-inbox-update\\r\\n[OK] store-projects-sort\\r\\n[FAIL] dynamic-register :: count=0\\r\\n[FAIL] dynamic-refresh :: calls=0\\r\\n[OK] dynamic-ghost-skip\\r\\n[OK] log-render-again\\r\\n[OK] log-auto-aggregate :: before=0 after=1\\r\\n[OK] meetings-template\\r\\n\\r\\n---STDERR---\\r\\n\\r\\nexit: 1\\r\\n\",\"error\":null,\"stage\":\"execute\",\"status\":\"success\",\"error_code\":\"\",\"command_fingerprint\":\"\",\"operation_receipt\":null}', '2026-08-03 14:02:13'),
(1256, '40122540-fcbb-4890-9b07-1296c60efc8f', 158707, 'tool.completed', 'code', 'moonya', 'pages_study', 'call_00_uiTyjR9gz1lNhN1O5MaB9687', '{\"tool_key\":\"shell_executor\",\"ok\":false,\"content\":\"inspect 阶段只允许已证明为只读的命令；当前分类为 write。\",\"error\":{\"code\":\"shell_readonly_violation\",\"message\":\"inspect 阶段只允许已证明为只读的命令；当前分类为 write。\"},\"stage\":\"preflight\",\"status\":\"error\",\"error_code\":\"shell_readonly_violation\",\"command_fingerprint\":\"81d868dfc65fd829f30c0070f13c69c31244581abbc8a88626546e9eb3ab4bfd\",\"operation_receipt\":null}', '2026-08-03 14:02:13'),
(1257, '40122540-fcbb-4890-9b07-1296c60efc8f', 158708, 'agent.turn.started', 'code', 'moonya', 'pages_work', NULL, '{\"turn_id\":\"pages_work-turn-34\",\"model\":\"deepseek-v4-flash\",\"round\":34,\"phase\":\"execution\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":34,\"round\":34,\"phase\":\"execution\"}}', '2026-08-03 14:02:13'),
(1258, '40122540-fcbb-4890-9b07-1296c60efc8f', 158709, 'agent.turn.started', 'code', 'moonya', 'pages_study', NULL, '{\"turn_id\":\"pages_study-turn-34\",\"model\":\"deepseek-v4-flash\",\"round\":34,\"phase\":\"execution\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":34,\"round\":34,\"phase\":\"execution\"}}', '2026-08-03 14:02:13'),
(1259, '40122540-fcbb-4890-9b07-1296c60efc8f', 159325, 'agent.turn.completed', 'code', 'moonya', 'pages_work', NULL, '{\"turn_id\":\"pages_work-turn-34\",\"status\":\"completed\",\"reasoning_content\":\"24 通过，3 失败：\\n\\n1. **exec-no-throw**：`window.addEventListener is not a function` —— 这是**测试环境问题**，不是 work.js 问题！测试沙箱里 `window = sandbox`，而 sandbox 对象没有 addEventListener 方法。真实浏览器里 window.addEventListener 存在。所以这是 mock 不完整。修复：sandbox 里加 addEventListener（把 hashchange 记录到 hashListeners）。\\n\\n2. **dynamic-register / dynamic-refresh**：因为 exec 抛错（window.addEventListener），initDynamicRouting 未完成，hashchange 监听未注册 → hashListeners 为空 → 测试触发不到。修复 mock 后应通过。\\n\\n修复测试脚本：sandbox.window 需要有 addEventListener/removeEventListener。把 window 对象单独做成一个带 addEventListener 的对象，document 保持。\\n\\nsandbox.window = { addEventListener: (t,fn)=>{ if(t===\'hashchange\') hashListeners.push(fn); }, removeEventListener(){} }，然后 window.App、window.WorkbenchRouter 也挂上去。work.js 里用的是 `window.addEventListener(\'hashchange\', ...)` 和 `window.App`、`window.WorkbenchRouter`。而 `window.App.registerPage` 通过 App 变量也行（work.js 里 `window.App && typeof App.registerPage`）。\\n\\n修改 sandbox：\\n```js\\nconst win = {\\n  addEventListener(t, fn) { if (t === \'hashchange\') hashListeners.push(fn); },\\n  removeEventListener() {},\\n  App, WorkbenchRouter: { current() { return routerCurrentPath; } },\\n  location, localStorage, navigator: {}, document,\\n  setTimeout, clearTimeout, Date, Math, JSON, ...\\n};\\n```\\n等等，work.js 里用到的 window 属性：window.App、window.WorkbenchRouter、window.addEventListener、window.innerWidth/innerHeight（openMenu）、window.open（文件预览）、window.matchMedia（无）。openMenu 测试不触发（交互时）。window.open 不触发。\\n\\n直接给 sandbox.window = win 对象（含 addEventListener），其余全局变量（document、location 等）作为 sandbox 顶层。work.js 里 `window.App` → win.App。`document` → sandbox.document。✓\\n\\n还有 openMenu 里 `window.innerWidth` —— 交互时不触发。\\n\\n重跑修正版。\",\"content\":\"3 个失败均为**测试 mock 不完整**所致（沙箱 `window` 缺少 `addEventListener`，导致动态路由监听未注册）。修正测试环境后重跑：\",\"content_discarded\":false,\"summary\":\"3 个失败均为**测试 mock 不完整**所致（沙箱 `window` 缺少 `addEventListener`，导致动态路由监听未注册）。修正测试环境后重跑：\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":34,\"round\":34,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"},\"round\":34,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"}', '2026-08-03 14:03:15'),
(1260, '40122540-fcbb-4890-9b07-1296c60efc8f', 159326, 'agent.turn.completed', 'code', 'moonya', 'pages_study', NULL, '{\"turn_id\":\"pages_study-turn-34\",\"status\":\"completed\",\"reasoning_content\":\"The `&` made it classified as write (pipe/ampersand). Use a single dir command without & in inspect, or use PowerShell Get-ChildItem (which worked before).\",\"content\":\"\",\"content_discarded\":false,\"summary\":\"The `&` made it classified as write (pipe/ampersand). Use a single dir command without & in inspect, or use PowerShell Get-ChildItem (which worked before).\",\"metadata\":{\"model\":\"deepseek-v4-flash\",\"iteration\":34,\"round\":34,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"},\"round\":34,\"phase\":\"execution\",\"finish_reason\":\"tool_calls\"}', '2026-08-03 14:03:15');
INSERT INTO `team_run_events` (`id`, `run_id`, `seq`, `event_name`, `agent_key`, `parent_agent_key`, `task_id`, `tool_call_id`, `payload`, `created_at`) VALUES
(1261, '40122540-fcbb-4890-9b07-1296c60efc8f', 159327, 'tool.started', 'code', 'moonya', 'pages_work', 'call_00_6W36LYfsXNyYVPzwklbG1644', '{\"tool_key\":\"python_executor\",\"display_name\":\"Python 执行器\",\"arguments\":{\"code\":\"import subprocess, os\\n\\ntest_js = r\'\'\'\\nconst fs = require(\'fs\');\\nconst vm = require(\'vm\');\\nconst path = \'D:/Project/Project/ccee/web1/js/pages/work.js\';\\nconst src = fs.readFileSync(path, \'utf8\');\\n\\nconst results = [];\\nfunction check(name, cond, extra) {\\n  results.push({ name, ok: !!cond, extra: extra || \'\' });\\n}\\n\\nfunction makeEl(tag) {\\n  return {\\n    tagName: (tag || \'div\').toUpperCase(),\\n    innerHTML: \'\', textContent: \'\', className: \'\', id: \'\', value: \'\',\\n    style: {}, children: [], parentNode: null, dataset: {},\\n    classList: {\\n      _s: new Set(),\\n      add(c) { this._s.add(c); }, remove(c) { this._s.delete(c); },\\n      toggle(c, f) { if (f === undefined) { this._s.has(c) ? this._s.delete(c) : this._s.add(c); } else { f ? this._s.add(c) : this._s.delete(c); } },\\n      contains(c) { return this._s.has(c); }\\n    },\\n    addEventListener(t, fn) { (this._listeners = this._listeners || {})[t] = (this._listeners[t] || []).concat([fn]); },\\n    removeEventListener() {},\\n    appendChild(c) { c.parentNode = this; this.children.push(c); return c; },\\n    removeChild(c) { const i = this.children.indexOf(c); if (i >= 0) this.children.splice(i, 1); return c; },\\n    insertBefore(c, ref) { c.parentNode = this; this.children.push(c); return c; },\\n    remove() { if (this.parentNode) this.parentNode.removeChild(this); },\\n    querySelector() { return null; },\\n    querySelectorAll() { return []; },\\n    setAttribute(k, v) { this[k] = v; },\\n    getAttribute(k) { return this[k] != null ? String(this[k]) : null; },\\n    closest() { return null; },\\n    contains() { return false; },\\n    getBoundingClientRect() { return { left: 0, top: 0, width: 120, height: 40, bottom: 40, right: 120 }; },\\n    offsetWidth: 0, offsetLeft: 0,\\n    focus() {}, blur() {}, click() {}, dispatchEvent() {},\\n    setPointerCapture() {}, releasePointerCapture() {}\\n  };\\n}\\n\\nlet seq = 0;\\nfunction uid() { return \'id-\' + (++seq); }\\nfunction nowISO() { return new Date().toISOString(); }\\nfunction dstr(n) { const d = new Date(); d.setDate(d.getDate() + n); return d.getFullYear() + \'-\' + String(d.getMonth()+1).padStart(2,\'0\') + \'-\' + String(d.getDate()).padStart(2,\'0\'); }\\nfunction makeColl(seed) {\\n  const data = seed.map(x => Object.assign({}, x));\\n  const listeners = [];\\n  function save() { listeners.forEach(fn => { try { fn(); } catch (e) {} }); }\\n  return {\\n    data,\\n    list() { return data.slice(); },\\n    get(id) { return data.find(x => x.id === id) || null; },\\n    add(item) { const rec = Object.assign({}, item, { id: uid(), createdAt: nowISO() }); data.unshift(rec); save(); return rec; },\\n    update(id, patch) { const i = data.findIndex(x => x.id === id); if (i < 0) return null; data[i] = Object.assign({}, data[i], patch); save(); return data[i]; },\\n    remove(id) { const i = data.findIndex(x => x.id === id); if (i < 0) return false; data.splice(i, 1); save(); return true; },\\n    clear() { data.length = 0; save(); },\\n    count() { return data.length; },\\n    query(fn) { return data.filter(fn); },\\n    subscribe(fn) { listeners.push(fn); return () => { const i = listeners.indexOf(fn); if (i >= 0) listeners.splice(i, 1); }; }\\n  };\\n}\\n\\nconst store = {\\n  settings: { theme: \'light\', fontSize: 15, sidebarCollapsed: false },\\n  todos: makeColl([\\n    { id: \'seed-todo-1\', title: \'回复客户邮件\', quadrant: \'q1\', priority: \'high\', due: dstr(0), done: false, projectId: \'\', createdAt: dstr(-1) },\\n    { id: \'seed-todo-6\', title: \'完成报销单\', quadrant: \'q1\', priority: \'mid\', due: dstr(-1), done: true, completedAt: new Date(Date.now() - 3600e3).toISOString(), projectId: \'\', createdAt: dstr(-3) }\\n  ]),\\n  inbox: makeColl([\\n    { id: \'seed-inbox-1\', text: \'确认会议室\', urgency: \'high\', done: false, createdAt: dstr(0) },\\n    { id: \'seed-inbox-3\', text: \'考虑番茄钟\', urgency: \'low\', done: true, createdAt: dstr(-2) }\\n  ]),\\n  projects: makeColl([\\n    { id: \'seed-proj-1\', name: \'产品 3.0 改版\', desc: \'主流程重构\', color: \'#b06f47\', status: \'active\', createdAt: dstr(-20) },\\n    { id: \'seed-proj-2\', name: \'客厅改造\', desc: \'采购升降桌\', color: \'#6c9170\', status: \'paused\', createdAt: dstr(-45) },\\n    { id: \'seed-proj-arch\', name: \'旧项目\', desc: \'已归档\', color: \'#8a7a6a\', status: \'archived\', createdAt: dstr(-60) }\\n  ]),\\n  logs: makeColl([{ id: \'seed-log-1\', date: dstr(0), content: \'上午评审，下午整理待办。\' }]),\\n  meetings: makeColl([\\n    { id: \'seed-meet-1\', title: \'项目周会\', datetime: dstr(0) + \' 10:00\', attendees: [\'李工\', \'王工\', \'我\'], summary: \'确定排期\', decisions: \'周五联调\', todos: [{ text: \'整理评审意见\', done: false, linked: false }], createdAt: dstr(-1) }\\n  ]),\\n  subscribe(fn) { this._ls = this._ls || []; this._ls.push(fn); return () => {}; }\\n};\\n\\nconst registered = [];\\nconst hashListeners = [];\\nlet routerCurrentPath = \'/work\';\\nlet refreshCalls = 0;\\n\\nconst document = {\\n  readyState: \'complete\',\\n  body: makeEl(\'body\'),\\n  head: makeEl(\'head\'),\\n  documentElement: makeEl(\'html\'),\\n  _els: {},\\n  getElementById(id) { return this._els[id] || null; },\\n  querySelector() { return null; },\\n  querySelectorAll() { return []; },\\n  createElement(tag) { return makeEl(tag); },\\n  addEventListener(t, fn) { if (t === \'hashchange\') hashListeners.push(fn); },\\n  removeEventListener() {}\\n};\\n\\nconst location = { hash: \'#/work\', href: \'http://localhost/index.html#/work\' };\\nconst localStorage = { getItem() { return null; }, setItem() {}, removeItem() {} };\\n\\nconst App = {\\n  registerPage(p, def) { registered.push({ path: p, def }); },\\n  navigate(p) { location.hash = \'#\' + p; },\\n  refresh() { refreshCalls++; },\\n  showToast() {},\\n  openModal() { return null; },\\n  closeModal() {},\\n  icon(name, size) { return \'<svg class=\\\"icon\\\" width=\\\"\' + (size||18) + \'\\\"><use href=\\\"#i-\' + name + \'\\\"></use></svg>\'; },\\n  escapeHtml(s) { return String(s == null ? \'\' : s).replace(/&/g,\'&amp;\').replace(/</g,\'&lt;\').replace(/>/g,\'&gt;\').replace(/\\\"/g,\'&quot;\').replace(/\'/g,\'&#39;\'); },\\n  uid: uid,\\n  formatDate(d) { return String(d); },\\n  store: store,\\n  version: \'0.1.0\'\\n};\\n\\nconst win = {\\n  App: App,\\n  WorkbenchRouter: { current() { return routerCurrentPath; } },\\n  addEventListener(t, fn) { if (t === \'hashchange\') hashListeners.push(fn); },\\n  removeEventListener() {},\\n  innerWidth: 1280, innerHeight: 800,\\n  open() {}\\n};\\n\\nfunction FakeCustomEvent() { return {}; }\\n\\nconst sandbox = {\\n  window: win, document, location, localStorage, navigator: {}, console,\\n  App, CustomEvent: FakeCustomEvent,\\n  setTimeout, clearTimeout, Date, Math, JSON, Object, Array, String, Number, Boolean, RegExp, Error\\n};\\nwin.document = document;\\nwin.location = location;\\nwin.localStorage = localStorage;\\n\\nvm.createContext(sandbox);\\ntry {\\n  vm.runInContext(src, sandbox, { filename: \'work.js\' });\\n  check(\'exec-no-throw\', true);\\n} catch (e) {\\n  check(\'exec-no-throw\', false, e && e.stack ? String(e.stack).slice(0, 1500) : String(e));\\n}\\n\\nconst paths = registered.map(r => r.path).sort();\\nconst expectPaths = [\'/work\', \'/work/todos\', \'/work/inbox\', \'/work/projects\', \'/work/projects/:id\', \'/work/log\', \'/work/logs\', \'/work/meetings\'].sort();\\ncheck(\'registered-paths\', JSON.stringify(paths) === JSON.stringify(expectPaths), \'got=\' + JSON.stringify(paths));\\n\\nfunction pageDef(p) { const r = registered.find(x => x.path === p); return r ? r.def : null; }\\nfunction tryRender(p, pathArg) {\\n  const def = pageDef(p);\\n  if (!def) return { html: \'\', err: \'not registered\' };\\n  try {\\n    const html = def.render(pathArg || p);\\n    return { html: html || \'\', err: null };\\n  } catch (e) {\\n    return { html: \'\', err: String(e && e.stack || e).slice(0, 800) };\\n  }\\n}\\n\\nconst renderChecks = [\\n  [\'/work\', \'work-overview\', \'今日待办\'],\\n  [\'/work/todos\', \'work-todos\', \'重要紧急\'],\\n  [\'/work/inbox\', \'work-inbox\', \'未清理\'],\\n  [\'/work/projects\', \'work-projects\', \'新建项目\'],\\n  [\'/work/log\', \'work-log\', \'生成周报\'],\\n  [\'/work/logs\', \'work-log\', \'生成月报\'],\\n  [\'/work/meetings\', \'work-meetings\', \'新建会议记录\']\\n];\\nrenderChecks.forEach(([p, marker, keyword]) => {\\n  const r = tryRender(p);\\n  check(\'render-\' + p, !r.err && r.html.indexOf(marker) >= 0 && r.html.indexOf(keyword) >= 0,\\n    r.err ? r.err : (\'len=\' + r.html.length + \' marker=\' + r.html.indexOf(marker) + \' kw=\' + r.html.indexOf(keyword)));\\n});\\n\\nconst d = tryRender(\'/work/projects/:id\', \'/work/projects/seed-proj-1\');\\ncheck(\'render-detail\', !d.err && d.html.indexOf(\'产品 3.0 改版\') >= 0 && d.html.indexOf(\'work-tabs\') >= 0 && d.html.indexOf(\'任务\') >= 0, d.err || \'len=\' + d.html.length);\\nconst d2 = tryRender(\'/work/projects/:id\', \'/work/projects/nonexistent\');\\ncheck(\'render-detail-404\', !d2.err && d2.html.indexOf(\'项目不存在\') >= 0, d2.err || \'\');\\n\\nfunction tryMount(p, pathArg) {\\n  const def = pageDef(p);\\n  if (!def || typeof def.mount !== \'function\') return \'no mount\';\\n  try { def.mount(document.body, pathArg || p); return null; }\\n  catch (e) { return String(e && e.stack || e).slice(0, 800); }\\n}\\n[\'/work\', \'/work/todos\', \'/work/inbox\', \'/work/projects\', \'/work/log\', \'/work/meetings\'].forEach(p => {\\n  const err = tryMount(p);\\n  check(\'mount-\' + p, !err, err || \'\');\\n});\\nconst mErr = tryMount(\'/work/projects/:id\', \'/work/projects/seed-proj-1\');\\ncheck(\'mount-detail\', !mErr, mErr || \'\');\\n\\nconst nt = store.todos.add({ title: \'新待办\', quadrant: \'q2\', priority: \'low\', due: dstr(0), done: false, projectId: \'\' });\\ncheck(\'store-todos-add\', !!nt.id && store.todos.list().length === 3, \'len=\' + store.todos.list().length);\\nstore.inbox.update(\'seed-inbox-1\', { done: true });\\ncheck(\'store-inbox-update\', store.inbox.get(\'seed-inbox-1\').done === true);\\nstore.projects.update(\'seed-proj-1\', { sort: 1 });\\ncheck(\'store-projects-sort\', store.projects.get(\'seed-proj-1\').sort === 1);\\n\\n/* 动态路由 */\\nrouterCurrentPath = \'/work/projects/seed-proj-1\';\\nlocation.hash = \'#/work/projects/seed-proj-1\';\\nhashListeners.forEach(fn => { try { fn(); } catch (e) { check(\'hash-listener-throw\', false, String(e)); } });\\nconst dyn = registered.filter(r => r.path === \'/work/projects/seed-proj-1\');\\ncheck(\'dynamic-register\', dyn.length === 1 && typeof dyn[0].def.render === \'function\', \'count=\' + dyn.length);\\ncheck(\'dynamic-refresh\', refreshCalls >= 1, \'calls=\' + refreshCalls);\\nrouterCurrentPath = \'/work/projects/ghost\';\\nlocation.hash = \'#/work/projects/ghost\';\\nhashListeners.forEach(fn => { try { fn(); } catch (e) {} });\\ncheck(\'dynamic-ghost-skip\', registered.filter(r => r.path === \'/work/projects/ghost\').length === 0);\\n\\n/* 日志自动聚合 */\\nstore.logs.clear();\\nconst logsBefore = store.logs.list().length;\\nconst r4 = tryRender(\'/work/log\', \'/work/log\');\\nconst logsAfter = store.logs.list().length;\\ncheck(\'log-auto-aggregate\', !r4.err && logsAfter > logsBefore, \'before=\' + logsBefore + \' after=\' + logsAfter + (r4.err ? \' err=\' + r4.err : \'\'));\\n\\n/* 会议模板 */\\nconst rm = tryRender(\'/work/meetings\', \'/work/meetings\');\\ncheck(\'meetings-template\', !rm.err && rm.html.indexOf(\'参会人\') >= 0 && rm.html.indexOf(\'决议\') >= 0, rm.err || \'\');\\n\\n/* 收件箱左滑升级表单可打开（openModal 自实现）——直接调用内部逻辑验证不抛错 */\\ntry {\\n  const inboxDef = pageDef(\'/work/inbox\');\\n  check(\'inbox-def-exists\', !!inboxDef);\\n} catch (e) { check(\'inbox-def-exists\', false, String(e)); }\\n\\nlet pass = 0, fail = 0;\\nresults.forEach(r => { if (r.ok) pass++; else fail++; });\\nconsole.log(\'PASS=\' + pass + \' FAIL=\' + fail);\\nresults.forEach(r => {\\n  console.log((r.ok ? \'[OK] \' : \'[FAIL] \') + r.name + (r.extra ? \' :: \' + r.extra : \'\'));\\n});\\nprocess.exit(fail > 0 ? 1 : 0);\\n\'\'\'\\n\\nscript_path = os.path.join(os.environ.get(\'TEMP\', \'.\'), \'work_smoke_test3.js\')\\nwith open(script_path, \'w\', encoding=\'utf-8\') as f:\\n    f.write(test_js)\\n\\nr = subprocess.run([r\'D:\\\\nodejs\\\\node.exe\', script_path], capture_output=True, text=True, timeout=60)\\nprint(r.stdout[-8000:])\\nprint(\'---STDERR---\')\\nprint(r.stderr[-2000:])\\nprint(\'exit:\', r.returncode)\\n\"},\"effect\":\"write\",\"risk_level\":\"high\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 14:03:15'),
