(1324, '40122540-fcbb-4890-9b07-1296c60efc8f', 165493, 'tool.started', 'code', 'moonya', 'pages_study', 'call_00_wR7BJuRZY0hG6yFikbYe4179', '{\"tool_key\":\"create_file\",\"display_name\":\"Create File\",\"arguments\":{\"content\":\"/* study.js 静态交叉校验：渲染 id 与源码选择器引用一致性 */\\n\'use strict\';\\nvar fs = require(\'fs\');\\n\\nfunction makeEl() {\\n  return { style: {}, dataset: {}, classList: { add: function () {}, remove: function () {} },\\n    setAttribute: function () {}, getAttribute: function () { return null; },\\n    appendChild: function () {}, addEventListener: function () {},\\n    querySelector: function () { return null; }, querySelectorAll: function () { return []; },\\n    firstChild: null, innerHTML: \'\', textContent: \'\', hidden: false };\\n}\\nfunction daysFromNow(n) { var d = new Date(); d.setDate(d.getDate() + n); return d.getFullYear() + \'-\' + String(d.getMonth() + 1).padStart(2, \'0\') + \'-\' + String(d.getDate()).padStart(2, \'0\'); }\\nfunction makeCollection(seed) {\\n  var arr = (seed || []).map(function (x) { return Object.assign({}, x); });\\n  return {\\n    list: function () { return arr.slice(); }, count: function () { return arr.length; },\\n    get: function (id) { return arr.find(function (x) { return x.id === id; }) || null; },\\n    add: function (item) { var r = Object.assign({}, item, { id: \'n\' }); arr.unshift(r); return r; },\\n    update: function (id, patch) { var i = arr.findIndex(function (x) { return x.id === id; }); if (i < 0) return null; arr[i] = Object.assign({}, arr[i], patch); return arr[i]; },\\n    remove: function () { return true; }, clear: function () {}, query: function (fn) { return arr.filter(fn); }\\n  };\\n}\\nvar settings = { theme: \'light\', fontSize: 15, sidebarCollapsed: false };\\nvar store = {\\n  settings: settings, updateSettings: function (p) { settings = Object.assign({}, settings, p); },\\n  subscribe: function () { return function () {}; }, summary: function () { return {}; },\\n  knowledge: makeCollection([{ id: \'k1\', path: \'行测 > 判断推理 > 图形推理\', title: \'对称性规律\', mastery: 3, reviewDate: daysFromNow(2), questionCount: 8, content: \'x\' }]),\\n  questions: makeCollection([{ id: \'q1\', module: \'判断推理\', stem: \'题干…\', options: [\'A. a\', \'B. b\'], answer: \'A\', analysis: \'x\', source: \'真题\', tags: [\'逻辑判断\'] }]),\\n  wrongQuestions: makeCollection([{ id: \'w1\', questionId: \'q1\', reason: \'粗心\', reviewCount: 1, consecutive: 0, lastResult: false, status: \'pending\', nextReview: daysFromNow(0) }]),\\n  plans: makeCollection([{ id: \'p1\', type: \'week\', title: \'计划\', start: daysFromNow(-1), end: daysFromNow(5), modules: { \'言语理解\': 2 }, progress: 30, status: \'active\' }]),\\n  checkins: makeCollection([{ id: \'c1\', date: daysFromNow(0), durationMin: 30, modules: [], summary: \'\' }]),\\n  shizheng: makeCollection([{ id: \'s1\', title: \'时政\', source: \'人民日报\', date: daysFromNow(-3), summary: \'摘要\', insight: \'\', quote: \'\', tags: [\'科技\'] }])\\n};\\nvar registered = {};\\nglobal.window = {\\n  App: {\\n    version: \'0.1.0\',\\n    registerPage: function (p, d) { registered[p] = d; },\\n    navigate: function () {}, refresh: function () {}, store: store,\\n    escapeHtml: function (s) { return String(s == null ? \'\' : s); },\\n    icon: function () { return \'<svg></svg>\'; }, uid: function () { return \'x\'; },\\n    showToast: function () {}, openModal: function () { return makeEl(); },\\n    formatDate: function () { return \'\'; }, closeModal: function () {}\\n  }\\n};\\nglobal.document = {\\n  getElementById: function () { return null; }, createElement: function () { return makeEl(); },\\n  head: { appendChild: function () {} }, documentElement: { appendChild: function () {}, style: {} },\\n  addEventListener: function () {},\\n  body: { classList: { add: function () {}, remove: function () {}, contains: function () { return false; } }, style: {} }\\n};\\n\\nvar file = \'D:\\\\\\\\Project\\\\\\\\Project\\\\\\\\ccee\\\\\\\\web1\\\\\\\\js\\\\\\\\pages\\\\\\\\study.js\';\\nvar src = fs.readFileSync(file, \'utf8\');\\nrequire(file);\\n\\nvar failures = [];\\nvar renderedIds = {};   // id -> 出现的页面列表\\nvar sourceIds = {};     // 源码中 id=\\\"...\\\"（render 模板 + 弹窗 HTML）\\n\\n// 1. 渲染输出收集 id\\nObject.keys(registered).forEach(function (key) {\\n  var def = registered[key];\\n  if (typeof def.render !== \'function\') return;\\n  var html;\\n  try { html = def.render(key); } catch (e) { failures.push(key + \': render 异常 \' + e.message); return; }\\n  var m, re = /id=\\\"([^\\\"]+)\\\"/g;\\n  while ((m = re.exec(html))) {\\n    var id = m[1];\\n    if (renderedIds[id] && renderedIds[id].indexOf(key) >= 0 && !/^(st-)/.test(id)) {\\n      failures.push(\'重复 id「\' + id + \'」出现在页面 \' + key);\\n    }\\n    (renderedIds[id] = renderedIds[id] || []).push(key);\\n  }\\n});\\n// 2. 源码中所有 id=\\\"...\\\"\\nvar m2, re2 = /id=\\\"([A-Za-z0-9_-]+)\\\"/g;\\nwhile ((m2 = re2.exec(src))) sourceIds[m2[1]] = true;\\n\\n// 3. 源码中选择器引用\\nvar refs = [];\\nvar m3, re3 = /(?:querySelector|getElementById)\\\\(\\\\s*[\'\\\"]#([A-Za-z0-9_-]+)[\'\\\"]\\\\s*\\\\)/g;\\nwhile ((m3 = re3.exec(src))) refs.push(m3[1]);\\n\\nvar known = Object.keys(sourceIds).concat(Object.keys(renderedIds));\\nvar unknownRefs = refs.filter(function (r) { return known.indexOf(r) < 0; });\\nif (unknownRefs.length) failures.push(\'引用了未定义 id: \' + unknownRefs.join(\', \'));\\n\\n// 4. 每页 mount 引用的 id 应在本页 render 输出中（或为弹窗 id，弹窗 id 已在 sourceIds）\\nObject.keys(registered).forEach(function (key) {\\n  var def = registered[key];\\n  if (!def || typeof def.mount !== \'function\') return;\\n  var body = def.mount.toString();\\n  var m4, re4 = /querySelector\\\\(\\\\s*[\'\\\"]#([A-Za-z0-9_-]+)[\'\\\"]\\\\s*\\\\)/g;\\n  while ((m4 = re4.exec(body))) {\\n    var id4 = m4[1];\\n    var inThisPage = (renderedIds[id4] || []).indexOf(key) >= 0;\\n    if (!inThisPage && !sourceIds[id4]) {\\n      failures.push(key + \' mount 引用的 #\' + id4 + \' 不在本页 render 输出中\');\\n    }\\n  }\\n});\\n\\n// 5. render 输出中不应出现模板变量残留（${ 未替换）\\nObject.keys(registered).forEach(function (key) {\\n  var def = registered[key];\\n  if (typeof def.render !== \'function\') return;\\n  try {\\n    var html = def.render(key);\\n    if (html.indexOf(\'${\') >= 0) failures.push(key + \': render 输出含未替换模板变量 ${\');\\n  } catch (e) { /* 已在前面报告 */ }\\n});\\n\\nif (failures.length) {\\n  console.error(\'FAILURES:\\\\n\' + failures.join(\'\\\\n\'));\\n  process.exit(1);\\n}\\nconsole.log(\'PASS: 静态交叉校验通过（\' + Object.keys(renderedIds).length + \' 个渲染 id，\' + refs.length + \' 处选择器引用全部可解析）\');\\n\",\"path\":\"C:\\\\Users\\\\Administrator\\\\AppData\\\\Local\\\\Temp\\\\study-harness4.js\"},\"effect\":\"write\",\"risk_level\":\"medium\",\"phase\":null,\"operation_id\":null,\"intent\":null,\"shell\":null,\"command_fingerprint\":null}', '2026-08-03 14:12:51'),
