92,\\\"hwnd\\\":923574,\\\"is_foreground\\\":true,\\\"is_minimized\\\":false,\\\"bounds\\\":{\\\"x\\\":60,\\\"y\\\":256,\\\"width\\\":1340,\\\"height\\\":820}}}],\\\"window\\\":{\\\"app\\\":\\\"MoonYa.exe\\\",\\\"title\\\":\\\"MoonYa\\\",\\\"process_id\\\":32392,\\\"hwnd\\\":923574,\\\"is_foreground\\\":true,\\\"is_minimized\\\":false,\\\"bounds\\\":{\\\"x\\\":60,\\\"y\\\":256,\\\"width\\\":1340,\\\"height\\\":820}},\\\"diagnostics\\\":{\\\"accessibility_provider\\\":\\\"uia-net\\\",\\\"screenshot_provider\\\":\\\"copyfromscreen\\\",\\\"node_count\\\":10,\\\"usable_node_count\\\":6,\\\"focus_available\\\":true,\\\"focus_source\\\":\\\"uia_focused_element\\\",\\\"truncated\\\":false}}\",\"error\":null,\"stage\":null,\"status\":null,\"error_code\":null,\"command_fingerprint\":null,\"operation_receipt\":null}', '2026-08-07 12:42:53');
