(2151, '0481997e-aeb2-45b2-b0a8-bd4234be168f', 337, 'tool.started', 'file', 'moonya', 'file-overview', 'call_00_2mvO4DsJVTxVt4aifqkN3289', '{\"tool_key\":\"shell_executor\",\"display_name\":\"Shell 执行器\",\"arguments\":{\"command\":\"powershell -NoProfile -Command \\\"$h=$env:USERPROFILE; $folders=@(\'Desktop\',\'Documents\',\'Downloads\',\'Pictures\',\'Videos\',\'Music\',\'Doubao\',\'WPS Cloud Files\',\'WPSDrive\',\'source\',\'AndroidStudioProjects\',\'ZCodeProject\',\'PyCharmMiscProject\',\'CodeBuddy\',\'WorkBuddy\'); foreach($f in $folders){ $p=Join-Path $h $f; if(Test-Path -LiteralPath $p){ $items=@(Get-ChildItem -Force -LiteralPath $p -ErrorAction SilentlyContinue); $count=$items.Count; $size=(Get-ChildItem -Force -Recurse -LiteralPath $p -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum; if($null -eq $size){$size=0}; $sizeMB=[math]::Round($size/1MB,1); $dirs=@($items | Where-Object {$_.PSIsContainer} | Select-Object -First 2 -ExpandProperty Name); $bigfile=@($items | Where-Object {-not $_.PSIsContainer} | Sort-Object Length -Descending | Select-Object -First 1 -ExpandProperty Name); $reps=@(); if($dirs.Count -gt 0){$reps+=(\'文件夹: \'+($dirs -join \'、\'))}; if($bigfile.Count -gt 0){$reps+=(\'文件: \'+$bigfile[0])}; $line=(\'{0}|条目={1}|大小={2}MB|代表={3}\' -f $f,$count,$sizeMB,($reps -join \' ; \')); Write-Output $line } }; Write-Output \'DONE\'\\\"\",\"shell\":\"cmd\",\"phase\":\"inspect\",\"operation_id\":\"inspect-home-folders\",\"intent\":\"只读统计用户主目录常见文件夹的顶层条目数、递归总大小及代表性条目名称\",\"success_criteria\":{\"expected_exit_code\":0,\"stdout_contains\":[\"DONE\"],\"stdout_regex\":[\"Desktop\\\\|条目=\\\\d+\"]},\"blocking\":false,\"completion_mode\":\"finite\"},\"effect\":\"read\",\"risk_level\":\"low\",\"phase\":\"inspect\",\"operation_id\":\"inspect-home-folders\",\"intent\":\"只读统计用户主目录常见文件夹的顶层条目数、递归总大小及代表性条目名称\",\"shell\":\"powershell\",\"command_fingerprint\":\"e9cfeda005450560f46a88d1a1abd9473bb76e35537906d5523f90e63c84a297\"}', '2026-08-08 11:34:21'),
